window.KLUB_DATA=[{"id":"p1q1","package":1,"number":1,"question":"Batang muda membengkok ke arah jendela yang mendapat cahaya. Respons ini disebut ...","options":{"A":"fototropisme positif","B":"tigmotropisme","C":"geotropisme negatif akar","D":"hidrotropisme negatif"},"answer":"A","answerText":"fototropisme positif","modul":4,"moduleName":"Fisiologi Tumbuhan","difficulty":"Sedang","explain":"Fototropisme positif berarti tumbuh menuju cahaya.","deepConcept":"Tropisme adalah respons pertumbuhan yang arahnya bergantung arah rangsangan. Respons positif tumbuh mendekati rangsangan; respons negatif menjauhinya. Cahaya, air, gravitasi, dan sentuhan memunculkan jenis tropisme berbeda.","conceptName":"tropisme","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q2","package":1,"number":2,"question":"Strategi perlindungan keanekaragaman hayati secara in situ dilakukan dengan ...","options":{"A":"melindungi spesies di habitat alaminya","B":"memindahkan semua hewan ke akuarium","C":"menyimpan semua biji di freezer saja","D":"mengawetkan hewan yang sudah punah"},"answer":"A","answerText":"melindungi spesies di habitat alaminya","modul":13,"moduleName":"Ekologi dan Pelestarian Lingkungan","difficulty":"Sedang","explain":"Konservasi in situ berlangsung di habitat asli.","deepConcept":"Konservasi in situ melindungi spesies di habitat aslinya, sementara ex situ menjaga populasi atau plasma nutfah di luar habitat. Gangguan dan fragmentasi habitat dapat mengurangi keterhubungan populasi asli.","conceptName":"konservasi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q3","package":1,"number":3,"question":"Jaringan yang mengangkut air dan mineral dari akar ke daun adalah ...","options":{"A":"epidermis saja","B":"floem","C":"xilem","D":"kambium saja"},"answer":"C","answerText":"xilem","modul":4,"moduleName":"Fisiologi Tumbuhan","difficulty":"Mudah","explain":"Xilem mengalirkan air dan ion mineral terutama ke arah atas.","deepConcept":"Xilem mengalirkan air/mineral dari akar; floem mentranslokasikan gula dari bagian sumber ke bagian pemakai/penyimpan. Sel penjaga mengubah turgor untuk membuka atau menutup stomata.","conceptName":"transport","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q4","package":1,"number":4,"question":"Panel surya menerima energi cahaya 500 J dan menghasilkan energi listrik 100 J. Efisiensinya ...","options":{"A":"20%","B":"10%","C":"50%","D":"80%"},"answer":"A","answerText":"20%","modul":11,"moduleName":"Bentuk Energi dan Perubahannya","difficulty":"Sedang","explain":"Efisiensi=100/500×100%=20%.","math":{"title":"Efisiensi dari konservasi energi","foundation":"Energi masuk tidak seluruhnya berubah menjadi keluaran yang diinginkan. Secara definisi, efisiensi η = (E berguna/E masuk)×100%. Pada alat biasa, sisanya terbuang sebagai kalor, suara, dll.","steps":["Efisiensi adalah proporsi energi masuk yang benar-benar menjadi energi berguna.","Dari definisi bagian = keluaran/masukan, sehingga η = E berguna/E masuk × 100%.","η = (100/500) × 100% = 20%.","Energi yang tidak menjadi keluaran berguna = 400 J (misalnya terdisipasi sebagai kalor)."],"symbol":"efficiency"},"deepConcept":"Energi tidak diciptakan dari ketiadaan. Efisiensi adalah persentase energi masuk yang menjadi keluaran berguna; tidak mengukur energi yang “hilang”, tetapi energi yang berpindah ke bentuk tak diinginkan.","conceptName":"energi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"B":"Efisiensi 10% menyatakan energi berguna 50 J dari masukan 500 J, padahal keluaran soal 100 J.","C":"Efisiensi 50% menyatakan energi berguna 250 J dari masukan 500 J, padahal keluaran soal 100 J.","D":"Efisiensi 80% menyatakan energi berguna 400 J dari masukan 500 J, padahal keluaran soal 100 J."}},{"id":"p1q5","package":1,"number":5,"question":"Sebuah resistor 6 Ω diberi tegangan 12 V. Arus yang mengalir adalah ...","options":{"A":"72 A","B":"6 A","C":"2 A","D":"0,5 A"},"answer":"C","answerText":"2 A","modul":8,"moduleName":"Listrik dan Magnet","difficulty":"Sedang","explain":"I=V/R=12/6=2 A.","math":{"title":"Hukum Ohm","foundation":"Untuk resistor ohmik pada kondisi tetap, tegangan V sebanding dengan arus I: V = I R. Dengan membagi kedua ruas, I = V/R atau R = V/I sesuai besaran yang ditanyakan.","steps":["Mulai dari Hukum Ohm: V = I × R.","Bagi kedua ruas dengan R → I = V/R.","I = 12/6 = 2 A."],"symbol":"ohm"},"deepConcept":"Rangkaian seri memiliki arus yang sama dan tegangan terbagi, sehingga R total dijumlahkan. Rangkaian paralel memiliki tegangan yang sama dan arus terbagi, sehingga kebalikan hambatan dijumlahkan.","conceptName":"rangkaian","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Arus 72 A pada hambatan 6 Ω memerlukan V = IR = 432 V, tidak sama dengan sumber 12 V.","B":"Arus 6 A pada hambatan 6 Ω memerlukan V = IR = 36 V, tidak sama dengan sumber 12 V.","D":"Arus 0,5 A pada hambatan 6 Ω memerlukan V = IR = 3 V, tidak sama dengan sumber 12 V."}},{"id":"p1q6","package":1,"number":6,"question":"Sebuah bandul melakukan 40 getaran dalam 20 s. Frekuensinya adalah ...","options":{"A":"20 Hz","B":"2 Hz","C":"0,5 Hz","D":"800 Hz"},"answer":"B","answerText":"2 Hz","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sedang","explain":"f=40/20=2 Hz.","math":{"title":"Frekuensi dan periode dari definisi","foundation":"Frekuensi f adalah banyaknya getaran n dalam waktu t, maka f = n/t. Periode T adalah waktu satu getaran, sehingga T = t/n = 1/f. Satuan f = hertz (Hz), T = detik (s).","steps":["Frekuensi adalah getaran per detik: f = n/t.","Periode adalah detik per getaran: T = t/n = 1/f.","Diketahui n = 40 dan t = 20 s, jadi f = 40/20 = 2 Hz."],"symbol":"frequency"},"deepConcept":"Frekuensi menyatakan banyak siklus per detik; periode menyatakan durasi satu siklus, dengan f = 1/T. Kecepatan gelombang terhubung ke frekuensi dan panjang gelombang melalui v = fλ.","conceptName":"gelombang","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Frekuensi 20 Hz akan menghasilkan n = f×t = 400 getaran selama 20 s, bukan 40 getaran.","C":"Frekuensi 0,5 Hz akan menghasilkan n = f×t = 10 getaran selama 20 s, bukan 40 getaran.","D":"Frekuensi 800 Hz akan menghasilkan n = f×t = 16.000 getaran selama 20 s, bukan 40 getaran."}},{"id":"p1q7","package":1,"number":7,"question":"Seorang pesepeda menempuh jarak 1.200 m dalam 4 menit dengan kelajuan tetap. Kelajuannya adalah ...","options":{"A":"3 m/s","B":"10 m/s","C":"5 m/s","D":"20 m/s"},"answer":"C","answerText":"5 m/s","modul":6,"moduleName":"Mekanika","difficulty":"Sedang","explain":"Kelajuan = 1.200/(4×60) = 5 m/s.","math":{"title":"Kelajuan dari definisi gerak","foundation":"Kelajuan rata-rata didefinisikan sebagai total jarak dibagi total waktu: v = s/t. Jika jarak dan waktu memakai satuan yang tidak cocok, konversikan terlebih dahulu.","steps":["Besaran diketahui: jarak s = 1.200 m; waktu t = 4 menit.","Definisi kelajuan rata-rata: v = s/t.","Samakan satuan: s = 1.200 m dan t = 240 s.","v = 1.200/240 = 5 m/s."],"symbol":"speed"},"deepConcept":"Kelajuan rata-rata memakai jarak tempuh total dibagi durasi total. Untuk memperoleh m/s, pakai meter dan detik; 1 km = 1.000 m dan 1 menit = 60 detik.","conceptName":"kelajuan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Nilai 3 m/s tidak sama dengan s/t = 1.200/240 = 5 m/s untuk data pada soal.","B":"Nilai 10 m/s tidak sama dengan s/t = 1.200/240 = 5 m/s untuk data pada soal.","D":"Nilai 20 m/s tidak sama dengan s/t = 1.200/240 = 5 m/s untuk data pada soal."}},{"id":"p1q8","package":1,"number":8,"question":"Bakteri tetap dapat berkembang biak meski tidak memiliki inti bermembran, karena DNA-nya tersimpan di ...","options":{"A":"badan Golgi","B":"daerah nukleoid","C":"kloroplas","D":"nukleolus"},"answer":"B","answerText":"daerah nukleoid","modul":5,"moduleName":"Sistem Organ, Sel, dan Genetika","difficulty":"Sulit","explain":"Prokariota memiliki DNA pada wilayah nukleoid.","deepConcept":"Kloroplas menangkap energi cahaya; mitokondria menghasilkan banyak ATP melalui respirasi aerob; ribosom menyusun protein; badan Golgi memodifikasi dan mengemas produk. DNA sel eukariotik sebagian besar berada di nukleus, sedangkan bakteri memiliki nukleoid.","conceptName":"organel","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q9","package":1,"number":9,"question":"Katrol tetap ideal digunakan mengangkat beban 200 N. Besar gaya minimum yang diperlukan adalah ...","options":{"A":"50 N","B":"400 N","C":"200 N","D":"100 N"},"answer":"C","answerText":"200 N","modul":6,"moduleName":"Mekanika","difficulty":"Sulit","explain":"Keuntungan mekanik katrol tetap ideal =1.","math":{"title":"Keuntungan mekanik katrol ideal","foundation":"Pada katrol ideal, tegangan tali sama di setiap ruas. Jika n ruas tali menopang beban W, maka nF = W. Ini menghemat gaya, tetapi jarak tali yang ditarik menjadi n kali kenaikan beban.","steps":["Jumlah ruas tali penopang beban = 1.","Tegangan pada setiap ruas = F, sehingga jumlah gaya penopang = nF.","Untuk beban setimbang: nF = W, lalu F = W/n.","F = 200/1 = 200 N."],"symbol":"pulley"},"deepConcept":"Gaya adalah besaran vektor; resultan harus mempertimbangkan arah. Benda bermassa m mengalami percepatan a menurut ΣF = ma. Gaya gesek yang melawan gerak dikurangkan dari gaya dorong.","conceptName":"gaya","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Jika setiap ruas menarik 50 N, total gaya penopang = 1×50 = 50 N, tidak sama dengan beban 200 N.","B":"Jika setiap ruas menarik 400 N, total gaya penopang = 1×400 = 400 N, tidak sama dengan beban 200 N.","D":"Jika setiap ruas menarik 100 N, total gaya penopang = 1×100 = 100 N, tidak sama dengan beban 200 N."}},{"id":"p1q10","package":1,"number":10,"question":"Enzim amilase dalam air liur terutama menguraikan ...","options":{"A":"protein","B":"amilum","C":"lemak","D":"selulosa dalam tubuh manusia"},"answer":"B","answerText":"amilum","modul":3,"moduleName":"Fisiologi Hewan","difficulty":"Sedang","explain":"Amilase menguraikan pati menjadi molekul lebih sederhana.","deepConcept":"Pencernaan memecah molekul besar agar dapat diserap. Amilase memecah pati, pepsin memecah protein, lipase memecah trigliserida; empedu bukan enzim, tetapi mengemulsikan lemak. Vili usus memperluas luas penyerapan.","conceptName":"pencernaan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q11","package":1,"number":11,"question":"Pemotongan pucuk utama sering membuat tunas samping lebih aktif karena berkurangnya pengaruh hormon ...","options":{"A":"insulin","B":"auksin dari dominansi apikal","C":"adrenalin","D":"tiroksin"},"answer":"B","answerText":"auksin dari dominansi apikal","modul":4,"moduleName":"Fisiologi Tumbuhan","difficulty":"Sulit","explain":"Auksin pucuk memelihara dominansi apikal.","deepConcept":"Pucuk batang menghasilkan auksin yang berperan mempertahankan dominansi apikal sehingga pertumbuhan tunas samping terhambat. Pemangkasan pucuk mengubah keseimbangan hormon dan dapat merangsang cabang.","conceptName":"hormon","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q12","package":1,"number":12,"question":"Benda bermassa 300 g memiliki volume 100 cm³. Massa jenisnya adalah ...","options":{"A":"3 g/cm³","B":"300 g/cm³","C":"30 g/cm³","D":"0,3 g/cm³"},"answer":"A","answerText":"3 g/cm³","modul":7,"moduleName":"Wujud Benda dan Fluida","difficulty":"Sedang","explain":"ρ=m/V=300/100=3.","math":{"title":"Definisi massa jenis","foundation":"Massa jenis menyatakan berapa massa yang terdapat dalam setiap satuan volume: ρ = m/V. Satuan harus konsisten: 1.000 cm³ = 0,001 m³ dan 1 g/cm³ = 1.000 kg/m³.","steps":["Dari definisi, massa jenis ρ = massa/volume = m/V.","Gunakan satuan konsisten: m = 300 g; V = 100 cm³.","ρ = 300/100 = 3 g/cm³."],"symbol":"density"},"deepConcept":"Massa jenis ρ = m/V; benda bebas dalam fluida yang massa jenisnya lebih kecil dari benda cenderung tenggelam, sebaliknya dapat terapung. Untuk benda terapung, gaya apung mengimbangi berat benda.","conceptName":"massa","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"B":"Jika massa jenis 300 g/cm³, massa yang sesuai pada volume soal menjadi m = ρV = 30.000 g, sedangkan massa benda sebenarnya 300.","C":"Jika massa jenis 30 g/cm³, massa yang sesuai pada volume soal menjadi m = ρV = 3.000 g, sedangkan massa benda sebenarnya 300.","D":"Jika massa jenis 0,3 g/cm³, massa yang sesuai pada volume soal menjadi m = ρV = 30 g, sedangkan massa benda sebenarnya 300."}},{"id":"p1q13","package":1,"number":13,"question":"Vaksin dapat memberi perlindungan karena merangsang pembentukan ...","options":{"A":"respons imun spesifik dan sel memori","B":"klorofil dalam darah","C":"tulang tambahan","D":"zat antibodi tanpa keterlibatan sistem imun"},"answer":"A","answerText":"respons imun spesifik dan sel memori","modul":14,"moduleName":"Kesehatan, Lingkungan, dan Teknologi","difficulty":"Sedang","explain":"Vaksin membentuk imunitas adaptif.","deepConcept":"Pencegahan penyakit mencakup pengendalian pajanan, sanitasi, vaksinasi, dan perawatan yang tepat. Vaksin merangsang respons imun adaptif dan memori; antibiotik hanya bermanfaat untuk infeksi yang sesuai, bukan semua penyakit.","conceptName":"kesehatan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q14","package":1,"number":14,"question":"Dalam rantai makanan rumput → belalang → katak → ular, konsumen tingkat II adalah ...","options":{"A":"rumput","B":"ular","C":"belalang","D":"katak"},"answer":"D","answerText":"katak","modul":13,"moduleName":"Ekologi dan Pelestarian Lingkungan","difficulty":"Sedang","explain":"Belalang konsumen I, katak konsumen II.","deepConcept":"Dalam rantai makanan, produsen membentuk bahan organik melalui fotosintesis, konsumen I memakan produsen, konsumen II memakan konsumen I, dan pengurai mendaur ulang unsur hara.","conceptName":"rantai","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q15","package":1,"number":15,"question":"Troli 6 kg diberi resultan gaya mendatar 24 N pada permukaan licin. Percepatannya adalah ...","options":{"A":"4 m/s²","B":"2 m/s²","C":"6 m/s²","D":"144 m/s²"},"answer":"A","answerText":"4 m/s²","modul":6,"moduleName":"Mekanika","difficulty":"Sedang","explain":"a=F/m=24/6=4 m/s².","math":{"title":"Hukum II Newton dan resultan gaya","foundation":"Hukum II Newton menyatakan ΣF = m a. Gaya berlawanan arah diberi tanda berlawanan sehingga ΣF = F dorong − F gesek; akibatnya a = ΣF/m.","steps":["Pilih arah dorong/tarik sebagai arah positif.","Dari Hukum II Newton: ΣF = ma, sehingga a = ΣF/m.","Gaya bersih ΣF = 24 − 0 = 24 N.","a = 24/6 = 4 m/s²."],"symbol":"newton"},"deepConcept":"Gaya adalah besaran vektor; resultan harus mempertimbangkan arah. Benda bermassa m mengalami percepatan a menurut ΣF = ma. Gaya gesek yang melawan gerak dikurangkan dari gaya dorong.","conceptName":"gaya","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"B":"Jika percepatan 2 m/s², gaya bersih yang dibutuhkan m×a = 6×2 = 12 N, padahal soal menetapkan gaya bersih 24 N.","C":"Jika percepatan 6 m/s², gaya bersih yang dibutuhkan m×a = 6×6 = 36 N, padahal soal menetapkan gaya bersih 24 N.","D":"Jika percepatan 144 m/s², gaya bersih yang dibutuhkan m×a = 6×144 = 864 N, padahal soal menetapkan gaya bersih 24 N."}},{"id":"p1q16","package":1,"number":16,"question":"Air bermassa 2 kg dipanaskan dari 20 °C ke 30 °C. Jika kalor jenis air 4.200 J/kg°C, kalor yang diserap adalah ...","options":{"A":"42.000 J","B":"8.400 J","C":"420.000 J","D":"84.000 J"},"answer":"D","answerText":"84.000 J","modul":10,"moduleName":"Suhu dan Kalor","difficulty":"Sulit","explain":"Q=mcΔT=2×4.200×10.","math":{"title":"Kalor jenis dan perubahan suhu","foundation":"Kalor jenis c didefinisikan sebagai energi kalor yang dibutuhkan per satuan massa untuk menaikkan suhu sebesar satu derajat: c = Q/(mΔT). Susun ulang menjadi Q = mcΔT, berlaku selama tidak ada perubahan wujud.","steps":["Definisi kalor jenis: c = Q/(mΔT).","Kalikan kedua ruas dengan mΔT → Q = mcΔT.","Massa m = 2 kg; kalor jenis c = 4.200 J/(kg·°C); perubahan suhu ΔT = 10 °C.","Q = 2 × 4.200 × 10 = 84.000 J. Satuan kg dan °C saling habis."],"symbol":"heat"},"deepConcept":"Kalor adalah energi yang berpindah karena beda suhu. Saat tidak terjadi perubahan wujud, Q = mcΔT; makin besar massa, kalor jenis, atau selisih suhu, makin besar energi yang diperlukan.","conceptName":"kalor","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Kalor 42.000 J menghasilkan ΔT = Q/(mc) = 42.000/(2×4.200), berbeda dari ΔT soal 10 °C. Yang memenuhi Q = mcΔT adalah 84.000 J.","B":"Kalor 8.400 J menghasilkan ΔT = Q/(mc) = 8.400/(2×4.200), berbeda dari ΔT soal 10 °C. Yang memenuhi Q = mcΔT adalah 84.000 J.","C":"Kalor 420.000 J menghasilkan ΔT = Q/(mc) = 420.000/(2×4.200), berbeda dari ΔT soal 10 °C. Yang memenuhi Q = mcΔT adalah 84.000 J."}},{"id":"p1q17","package":1,"number":17,"question":"Paku besi dililit kawat berarus lalu dapat menarik klip. Penyebab utamanya adalah ...","options":{"A":"arus listrik menghasilkan medan magnet","B":"besi berubah menjadi baterai kimia","C":"kawat menghilangkan gravitasi","D":"klip kehilangan massa"},"answer":"A","answerText":"arus listrik menghasilkan medan magnet","modul":8,"moduleName":"Listrik dan Magnet","difficulty":"Sedang","explain":"Medan magnet dihasilkan oleh arus pada lilitan.","deepConcept":"Hukum Ohm V = IR memberi hubungan antara beda potensial, arus, dan hambatan untuk resistor ohmik. Ampere adalah satuan arus, volt satuan beda potensial, dan ohm satuan hambatan.","conceptName":"ohm","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q18","package":1,"number":18,"question":"Berbagai varietas padi dengan sifat rasa dan umur panen berbeda menunjukkan keanekaragaman tingkat ...","options":{"A":"genetik","B":"ekosistem","C":"bioma","D":"komunitas"},"answer":"A","answerText":"genetik","modul":2,"moduleName":"Keanekaragaman dan Klasifikasi","difficulty":"Sedang","explain":"Variasi dalam satu jenis mencerminkan keanekaragaman gen.","deepConcept":"Keanekaragaman genetik terjadi dalam satu spesies akibat kombinasi alel yang berbeda. Perbedaan gen tidak otomatis berarti spesies baru; pemisahan spesies membutuhkan bukti biologis dan evolusioner yang memadai.","conceptName":"genetik","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q19","package":1,"number":19,"question":"Dongkrak hidrolik memiliki luas penampang kecil 5 cm² dan besar 100 cm². Gaya pada piston kecil 50 N menghasilkan gaya pada piston besar ...","options":{"A":"100 N","B":"500 N","C":"2.000 N","D":"1.000 N"},"answer":"D","answerText":"1.000 N","modul":7,"moduleName":"Wujud Benda dan Fluida","difficulty":"Sulit","explain":"F2=F1×A2/A1=50×20=1.000.","math":{"title":"Penurunan hukum Pascal","foundation":"Dalam fluida tertutup yang ideal, tambahan tekanan diteruskan sama besar: p₁ = p₂. Karena p = F/A, diperoleh F₁/A₁ = F₂/A₂. Piston berluas lebih besar menghasilkan gaya lebih besar.","steps":["Tekanan sama: F₁/A₁ = F₂/A₂.","Susun ulang sesuai gaya yang dicari: F₂ = F₁ × (A₂/A₁), atau F₁ = F₂ × (A₁/A₂).","F₂ = 50 × (100/5) = 1.000 N.","Perbandingan luas bebas satuan karena pembilang dan penyebut memakai cm² yang sama."],"symbol":"pascal"},"deepConcept":"Hukum Pascal menghubungkan kenaikan tekanan yang sama dalam fluida tertutup. Karena p = F/A, perbandingan gaya piston sebanding perbandingan luasnya; hasil ideal mengabaikan gesekan.","conceptName":"hidrolik","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Gaya keluaran 100 N memberi tekanan di piston besar F₂/A₂ = 100/100 = 1 N/cm², berbeda dari tekanan masuk 10 N/cm².","B":"Gaya keluaran 500 N memberi tekanan di piston besar F₂/A₂ = 500/100 = 5 N/cm², berbeda dari tekanan masuk 10 N/cm².","C":"Gaya keluaran 2.000 N memberi tekanan di piston besar F₂/A₂ = 2.000/100 = 20 N/cm², berbeda dari tekanan masuk 10 N/cm²."}},{"id":"p1q20","package":1,"number":20,"question":"Tekanan hidrostatis pada kedalaman 2 m di air (ρ=1.000 kg/m³; g=10 m/s²) adalah ...","options":{"A":"20.000 Pa","B":"200.000 Pa","C":"2.000 Pa","D":"10.000 Pa"},"answer":"A","answerText":"20.000 Pa","modul":7,"moduleName":"Wujud Benda dan Fluida","difficulty":"Sedang","explain":"p=ρgh=1.000×10×2.","math":{"title":"Penurunan tekanan hidrostatis","foundation":"Bayangkan kolom cairan berluas A dan tinggi h. Volumenya V = Ah, massanya m = ρAh, beratnya F = mg = ρAhg. Tekanan p = F/A sehingga p = ρgh. Untuk dua titik, Δp = ρgΔh.","steps":["Tekanan kolom cairan: p = F/A. Dengan F = mg = ρAhg, maka p = ρgh.","Yang dicari tekanan hidrostatis relatif terhadap permukaan, bukan tekanan absolut.","ρ = 1.000 kg/m³, g = 10 m/s², h = 2 m.","p = 1.000 × 10 × 2 = 20.000 Pa."],"symbol":"hydro"},"deepConcept":"Tekanan hidrostatis adalah tekanan akibat berat kolom fluida di atas titik. Tekanan bertambah jika massa jenis, percepatan gravitasi, atau kedalaman meningkat.","conceptName":"hidrostatis","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"B":"Tekanan 200.000 Pa mengharuskan kedalaman h = p/(ρg) = 20 m, bukan 2 m.","C":"Tekanan 2.000 Pa mengharuskan kedalaman h = p/(ρg) = 0,2 m, bukan 2 m.","D":"Tekanan 10.000 Pa mengharuskan kedalaman h = p/(ρg) = 1 m, bukan 2 m."}},{"id":"p1q21","package":1,"number":21,"question":"Dalam cahaya cukup, laju fotosintesis tetap rendah karena konsentrasi CO2 sangat kecil. Faktor pembatasnya adalah ...","options":{"A":"warna meja","B":"jenis pot","C":"konsentrasi karbon dioksida","D":"jumlah akar tanpa kaitan kondisi"},"answer":"C","answerText":"konsentrasi karbon dioksida","modul":4,"moduleName":"Fisiologi Tumbuhan","difficulty":"Sedang","explain":"Faktor dengan suplai rendah membatasi fotosintesis.","deepConcept":"Fotosintesis memerlukan cahaya, CO₂, air, pigmen, dan enzim. Laju fotosintesis dibatasi faktor yang paling tidak mencukupi; peningkatan cahaya tidak lagi menaikkan laju jika faktor lain menjadi batas.","conceptName":"fotosintesis","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q22","package":1,"number":22,"question":"Saat karbon dioksida dalam darah meningkat, pusat pernapasan biasanya merespons dengan ...","options":{"A":"meningkatkan frekuensi atau kedalaman napas","B":"mengurangi suplai oksigen secara sengaja","C":"menutup alveolus secara permanen","D":"menghentikan pertukaran gas"},"answer":"A","answerText":"meningkatkan frekuensi atau kedalaman napas","modul":3,"moduleName":"Fisiologi Hewan","difficulty":"Sedang","explain":"Kenaikan CO2 memicu respons ventilasi.","deepConcept":"Aliran darah sistemik: bilik kiri → aorta → jaringan → vena kava → serambi kanan. Aliran pulmonal: bilik kanan → arteri pulmonalis → paru-paru → vena pulmonalis → serambi kiri. Katup menjaga aliran satu arah.","conceptName":"peredaran","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q23","package":1,"number":23,"question":"Tiga termometer menunjukkan 32, 32, dan 34 °C saat mengukur air yang sama. Tindakan terbaik sebelum menyimpulkan suhu air adalah ...","options":{"A":"membuang semua data tanpa pemeriksaan","B":"memeriksa kalibrasi termometer dan mengulang pengukuran","C":"langsung mengambil nilai tertinggi","D":"menganggap alat dengan angka terbesar paling akurat"},"answer":"B","answerText":"memeriksa kalibrasi termometer dan mengulang pengukuran","modul":1,"moduleName":"Keterampilan dan Metode Ilmiah","difficulty":"Sulit","explain":"Kalibrasi serta pengulangan membantu memeriksa ketelitian dan ketepatan.","deepConcept":"Akurasi menunjukkan kedekatan dengan nilai yang benar; presisi menunjukkan konsistensi pengukuran berulang. Kalibrasi memeriksa bias alat, sedangkan pengulangan menguji kestabilan hasil.","conceptName":"pengukuran","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q24","package":1,"number":24,"question":"Seorang siswa menguji pengaruh jumlah pupuk terhadap tinggi tanaman, sementara air dan cahaya dibuat sama. Faktor yang sengaja diubah adalah ...","options":{"A":"tinggi tanaman","B":"jenis pot","C":"jumlah daun yang tumbuh","D":"jumlah pupuk"},"answer":"D","answerText":"jumlah pupuk","modul":1,"moduleName":"Keterampilan dan Metode Ilmiah","difficulty":"Sedang","explain":"Variabel bebas adalah jumlah pupuk.","deepConcept":"Variabel bebas adalah faktor yang sengaja diubah; variabel terikat adalah hasil yang diukur; variabel kontrol adalah faktor lain yang dibuat tetap. Perbandingan bermakna jika perlakuan berbeda pada satu faktor utama saja.","conceptName":"variabel","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q25","package":1,"number":25,"question":"Drone pertanian dapat membantu pemantauan tanaman jika dilengkapi kamera multispektral yang mengukur ...","options":{"A":"perbedaan pantulan cahaya untuk menilai kondisi vegetasi","B":"jumlah kromosom langsung tanpa sampel","C":"kandungan oksigen di inti Bumi","D":"tekanan darah petani dari udara"},"answer":"A","answerText":"perbedaan pantulan cahaya untuk menilai kondisi vegetasi","modul":14,"moduleName":"Kesehatan, Lingkungan, dan Teknologi","difficulty":"Sulit","explain":"Indeks vegetasi memakai pantulan spektral.","deepConcept":"Sensor mengubah besaran fisik/kimia/optik menjadi informasi terukur. Kamera multispektral memanfaatkan perbedaan pantulan spektral; PM2,5 mengacu pada partikel dengan diameter aerodinamis tidak lebih dari 2,5 μm.","conceptName":"sensor","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q26","package":1,"number":26,"question":"Sebuah pengungkit seimbang. Beban 100 N berada 20 cm dari titik tumpu. Gaya kuasa bekerja 50 cm dari titik tumpu. Besar gaya kuasa adalah ...","options":{"A":"20 N","B":"100 N","C":"40 N","D":"250 N"},"answer":"C","answerText":"40 N","modul":6,"moduleName":"Mekanika","difficulty":"Sulit","explain":"Momen: 100×20 = F×50; F=40 N.","math":{"title":"Keseimbangan momen gaya","foundation":"Momen gaya terhadap titik tumpu adalah τ = F × l (lengan tegak lurus). Tuas seimbang apabila momen searah jarum jam sama dengan momen berlawanan arah: F₁l₁ = F₂l₂.","steps":["Abaikan gesekan dan massa tuas; jumlah momen terhadap titik tumpu = 0.","Momen sisi pertama = momen sisi kedua: F₁ × l₁ = F₂ × l₂.","100 × 20 = F₂ × 50 (lengan sama-sama dalam cm).","F₂ = (100 × 20)/50 = 40 N."],"symbol":"lever"},"deepConcept":"Gaya adalah besaran vektor; resultan harus mempertimbangkan arah. Benda bermassa m mengalami percepatan a menurut ΣF = ma. Gaya gesek yang melawan gerak dikurangkan dari gaya dorong.","conceptName":"gaya","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Gaya 20 N pada lengan 50 cm menghasilkan momen 1.000 N·cm, sementara momen sisi lain 2.000 N·cm. Momen belum seimbang.","B":"Gaya 100 N pada lengan 50 cm menghasilkan momen 5.000 N·cm, sementara momen sisi lain 2.000 N·cm. Momen belum seimbang.","D":"Gaya 250 N pada lengan 50 cm menghasilkan momen 12.500 N·cm, sementara momen sisi lain 2.000 N·cm. Momen belum seimbang."}},{"id":"p1q27","package":1,"number":27,"question":"Pergantian musim tahunan di banyak wilayah Bumi terutama diakibatkan oleh ...","options":{"A":"perubahan arah gravitasi Bumi setiap malam","B":"kemiringan sumbu rotasi Bumi dan revolusinya mengelilingi Matahari","C":"rotasi Bulan mengelilingi dirinya","D":"perubahan jarak Bumi–Bulan harian saja"},"answer":"B","answerText":"kemiringan sumbu rotasi Bumi dan revolusinya mengelilingi Matahari","modul":12,"moduleName":"Bumi, Tata Surya, dan Antariksa","difficulty":"Sulit","explain":"Kemiringan sumbu mengubah sudut dan durasi penyinaran musiman.","deepConcept":"Rotasi Bumi menghasilkan siang–malam; revolusi Bumi bersama kemiringan sumbu rotasi menghasilkan musim. Orbit planet dan fase Bulan berbeda dari rotasi Bumi.","conceptName":"orbit","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q28","package":1,"number":28,"question":"Kucing rumah dan harimau berada dalam famili Felidae. Hal itu menunjukkan ...","options":{"A":"keduanya memiliki jumlah kromosom selalu sama","B":"keduanya memiliki habitat identik","C":"keduanya pasti satu spesies","D":"kekerabatan lebih dekat daripada dengan hewan yang berbeda famili"},"answer":"D","answerText":"kekerabatan lebih dekat daripada dengan hewan yang berbeda famili","modul":2,"moduleName":"Keanekaragaman dan Klasifikasi","difficulty":"Mudah","explain":"Satu famili mengindikasikan kekerabatan taksonomis.","deepConcept":"Urutan takson dari luas ke sempit ialah kingdom–filum–kelas–ordo–famili–genus–spesies. Makin dekat nenek moyang bersama suatu pasangan organisme, makin dekat pula hubungan evolusionernya.","conceptName":"taksonomi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q29","package":1,"number":29,"question":"Dua resistor 6 Ω dan 3 Ω dipasang paralel. Hambatan penggantinya adalah ...","options":{"A":"9 Ω","B":"2 Ω","C":"3 Ω","D":"18 Ω"},"answer":"B","answerText":"2 Ω","modul":8,"moduleName":"Listrik dan Magnet","difficulty":"Sulit","explain":"1/R=1/6+1/3=1/2.","math":{"title":"Mengapa rumus paralel berupa kebalikan?","foundation":"Tegangan V sama pada setiap cabang paralel; arus total adalah penjumlahan arus cabang: I = V/R₁+V/R₂. Karena I=V/R total, pembagian dengan V menghasilkan 1/R total = 1/R₁+1/R₂.","steps":["Tegangan pada setiap cabang paralel sama, sedangkan arus total adalah jumlah arus cabang.","Karena I total = Σ(V/Rᵢ) = V/R total, maka 1/R total = Σ(1/Rᵢ).","Untuk dua resistor, R total = (R₁ × R₂)/(R₁ + R₂) = (6 × 3)/(6 + 3) = 2 Ω."],"symbol":"parallel"},"deepConcept":"Rangkaian seri memiliki arus yang sama dan tegangan terbagi, sehingga R total dijumlahkan. Rangkaian paralel memiliki tegangan yang sama dan arus terbagi, sehingga kebalikan hambatan dijumlahkan.","conceptName":"rangkaian","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Hambatan 9 Ω berbeda dari (R₁R₂)/(R₁+R₂) = 2 Ω; hambatan paralel juga harus lebih kecil daripada setiap cabang.","C":"Hambatan 3 Ω berbeda dari (R₁R₂)/(R₁+R₂) = 2 Ω; hambatan paralel juga harus lebih kecil daripada setiap cabang.","D":"Hambatan 18 Ω berbeda dari (R₁R₂)/(R₁+R₂) = 2 Ω; hambatan paralel juga harus lebih kecil daripada setiap cabang."}},{"id":"p1q30","package":1,"number":30,"question":"Sendok logam menjadi panas ketika ujungnya dimasukkan ke teh panas. Perpindahan kalor terutama ...","options":{"A":"sublimasi","B":"konduksi","C":"radiasi","D":"konveksi"},"answer":"B","answerText":"konduksi","modul":10,"moduleName":"Suhu dan Kalor","difficulty":"Sedang","explain":"Konduksi terjadi melalui bahan logam.","deepConcept":"Kalor adalah energi yang berpindah karena beda suhu. Saat tidak terjadi perubahan wujud, Q = mcΔT; makin besar massa, kalor jenis, atau selisih suhu, makin besar energi yang diperlukan.","conceptName":"kalor","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q31","package":1,"number":31,"question":"Pembuatan yoghurt memanfaatkan mikroorganisme untuk menghasilkan ...","options":{"A":"asam laktat melalui fermentasi","B":"logam berat melalui pembakaran","C":"oksigen murni dari susu","D":"garam dapur dari cahaya"},"answer":"A","answerText":"asam laktat melalui fermentasi","modul":14,"moduleName":"Kesehatan, Lingkungan, dan Teknologi","difficulty":"Sedang","explain":"Bakteri asam laktat memfermentasi gula susu.","deepConcept":"Bioteknologi memanfaatkan sel atau proses biologis untuk menghasilkan produk. Fermentasi adalah proses metabolik mikroba; teknik DNA rekombinan memungkinkan produksi protein seperti insulin.","conceptName":"biotek","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q32","package":1,"number":32,"question":"Lebah mendapat nektar, sementara bunga terbantu penyerbukannya. Hubungannya adalah ...","options":{"A":"kompetisi","B":"amensalisme","C":"mutualisme","D":"parasitisme"},"answer":"C","answerText":"mutualisme","modul":13,"moduleName":"Ekologi dan Pelestarian Lingkungan","difficulty":"Sedang","explain":"Kedua organisme mendapat keuntungan.","deepConcept":"Mutualisme menguntungkan kedua pihak; komensalisme menguntungkan satu pihak tanpa dampak berarti pada pihak lain; parasitisme merugikan inang; predasi membunuh/memakan mangsa; kompetisi terjadi ketika organisme memperebutkan sumber terbatas.","conceptName":"interaksi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q33","package":1,"number":33,"question":"Benda 2 kg bergerak dengan kecepatan 3 m/s. Energi kinetiknya adalah ...","options":{"A":"18 J","B":"6 J","C":"9 J","D":"3 J"},"answer":"C","answerText":"9 J","modul":11,"moduleName":"Bentuk Energi dan Perubahannya","difficulty":"Sulit","explain":"Ek=½mv²=½×2×9=9 J.","math":{"title":"Asal rumus energi kinetik","foundation":"Usaha W = Fs = mas. Untuk benda mulai dari diam dengan percepatan tetap, v² = 2as, maka as = v²/2. Jadi W = m(v²/2) = ½mv², yaitu energi kinetik akhir.","steps":["Usaha untuk mempercepat benda dari diam menjadi energi kinetiknya: W = ½ m v².","Kuadratkan kecepatan terlebih dahulu: v² = 3² = 9 (m/s)².","Eₖ = ½ × 2 × 9 = 9 J.","Perhatikan: energi kinetik berbanding lurus dengan kuadrat kecepatan."],"symbol":"kinetic"},"deepConcept":"Energi kinetik bergantung pada massa dan kuadrat kelajuan: Eₖ = ½mv². Jika kecepatan menjadi dua kali, energi kinetik menjadi empat kali.","conceptName":"mekanik","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Dengan energi 18 J dan massa 2 kg, kelajuan seharusnya v = √(2E/m) ≈ 4,24264 m/s, bukan 3 m/s.","B":"Dengan energi 6 J dan massa 2 kg, kelajuan seharusnya v = √(2E/m) ≈ 2,44949 m/s, bukan 3 m/s.","D":"Dengan energi 3 J dan massa 2 kg, kelajuan seharusnya v = √(2E/m) ≈ 1,73205 m/s, bukan 3 m/s."}},{"id":"p1q34","package":1,"number":34,"question":"Gerhana Matahari dapat terjadi ketika urutan benda hampir segaris adalah ...","options":{"A":"Bulan–Matahari–Bumi","B":"Bumi–Matahari–Bulan","C":"Matahari–Bumi–Bulan","D":"Matahari–Bulan–Bumi"},"answer":"D","answerText":"Matahari–Bulan–Bumi","modul":12,"moduleName":"Bumi, Tata Surya, dan Antariksa","difficulty":"Sedang","explain":"Bulan menutupi cahaya Matahari ke Bumi.","deepConcept":"Gerhana Matahari terjadi ketika Bulan berada di antara Matahari–Bumi; gerhana Bulan ketika Bumi berada di antara Matahari–Bulan. Umbra merupakan bagian bayangan paling gelap.","conceptName":"gerhana","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q35","package":1,"number":35,"question":"Dalam mitosis sel tubuh, jumlah kromosom pada sel anak umumnya ...","options":{"A":"selalu hilang seluruhnya","B":"menjadi setengah tanpa pengecualian","C":"menjadi empat kali","D":"sama dengan sel induk"},"answer":"D","answerText":"sama dengan sel induk","modul":5,"moduleName":"Sistem Organ, Sel, dan Genetika","difficulty":"Sedang","explain":"Mitosis mempertahankan jumlah kromosom.","deepConcept":"Mitosis menghasilkan sel anak dengan jumlah kromosom umumnya sama, sedangkan meiosis mengurangi jumlah kromosom menjadi separuh. Sebelum pembelahan, DNA direplikasi pada fase S; kromosom sejajar pada metafase dan kromatid saudara berpisah pada anafase mitosis.","conceptName":"pembelahan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q36","package":1,"number":36,"question":"Pembuluh darah yang mengalirkan darah kaya oksigen dari paru-paru menuju jantung adalah ...","options":{"A":"vena kava","B":"vena pulmonalis","C":"aorta","D":"arteri pulmonalis"},"answer":"B","answerText":"vena pulmonalis","modul":3,"moduleName":"Fisiologi Hewan","difficulty":"Mudah","explain":"Vena pulmonalis membawa darah beroksigen ke serambi kiri.","deepConcept":"Aliran darah sistemik: bilik kiri → aorta → jaringan → vena kava → serambi kanan. Aliran pulmonal: bilik kanan → arteri pulmonalis → paru-paru → vena pulmonalis → serambi kiri. Katup menjaga aliran satu arah.","conceptName":"peredaran","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q37","package":1,"number":37,"question":"Resistor 2 Ω, 3 Ω, dan 5 Ω disusun seri. Hambatan total adalah ...","options":{"A":"1 Ω","B":"30 Ω","C":"3 Ω","D":"10 Ω"},"answer":"D","answerText":"10 Ω","modul":8,"moduleName":"Listrik dan Magnet","difficulty":"Sedang","explain":"R seri =2+3+5=10 Ω.","math":{"title":"Mengapa hambatan seri dijumlahkan?","foundation":"Arus I sama melalui setiap resistor seri; tegangan sumber terbagi: V total = V₁+V₂+… = IR₁+IR₂+… = I(R₁+R₂+…). Membagi kedua ruas dengan I menghasilkan R total = ΣR.","steps":["Arus pada semua resistor seri sama.","Tegangan total V = Σ(IRᵢ) = I ΣRᵢ → R total = ΣRᵢ.","R total = 2 + 3 + 5 = 10 Ω."],"symbol":"series"},"deepConcept":"Rangkaian seri memiliki arus yang sama dan tegangan terbagi, sehingga R total dijumlahkan. Rangkaian paralel memiliki tegangan yang sama dan arus terbagi, sehingga kebalikan hambatan dijumlahkan.","conceptName":"rangkaian","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Hambatan 1 Ω tidak sama dengan jumlah hambatan seri = 2 + 3 + 5 = 10 Ω.","B":"Hambatan 30 Ω tidak sama dengan jumlah hambatan seri = 2 + 3 + 5 = 10 Ω.","C":"Hambatan 3 Ω tidak sama dengan jumlah hambatan seri = 2 + 3 + 5 = 10 Ω."}},{"id":"p1q38","package":1,"number":38,"question":"Pensil terlihat seolah-olah bengkok saat sebagian masuk ke air karena ...","options":{"A":"pensil benar-benar patah karena air","B":"air selalu memancarkan cahaya sendiri","C":"cahaya mengalami pembiasan pada batas dua medium","D":"cahaya tidak dapat merambat di udara"},"answer":"C","answerText":"cahaya mengalami pembiasan pada batas dua medium","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sulit","explain":"Perubahan kecepatan cahaya menyebabkan pembiasan.","deepConcept":"Pembiasan terjadi karena kecepatan rambat cahaya berubah ketika indeks bias medium berbeda. Dari medium indeks rendah ke tinggi, sinar mendekati normal; dari tinggi ke rendah, sinar menjauhi normal.","conceptName":"bias","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q39","package":1,"number":39,"question":"Organel yang menghasilkan sebagian besar ATP melalui respirasi aerob pada sel eukariotik adalah ...","options":{"A":"nukleolus","B":"lisosom","C":"mitokondria","D":"ribosom"},"answer":"C","answerText":"mitokondria","modul":5,"moduleName":"Sistem Organ, Sel, dan Genetika","difficulty":"Mudah","explain":"Mitokondria melakukan fosforilasi oksidatif.","deepConcept":"Kloroplas menangkap energi cahaya; mitokondria menghasilkan banyak ATP melalui respirasi aerob; ribosom menyusun protein; badan Golgi memodifikasi dan mengemas produk. DNA sel eukariotik sebagian besar berada di nukleus, sedangkan bakteri memiliki nukleoid.","conceptName":"organel","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q40","package":1,"number":40,"question":"Cermin cembung dipasang di tikungan jalan karena menghasilkan ...","options":{"A":"bayangan nyata terbalik pada semua posisi","B":"berkas cahaya tidak mengalami pemantulan","C":"bidang pandang sempit dan bayangan selalu diperbesar","D":"bidang pandang luas dengan bayangan maya yang diperkecil"},"answer":"D","answerText":"bidang pandang luas dengan bayangan maya yang diperkecil","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sulit","explain":"Cermin cembung divergen memperluas cakupan pandang.","deepConcept":"Pada cermin datar, sudut datang sama dengan sudut pantul jika diukur dari garis normal. Pada cermin cembung, sinar pantul menyebar sehingga bidang pandang menjadi luas.","conceptName":"pantul","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q41","package":1,"number":41,"question":"Seseorang digigit hewan yang diduga rabies. Tindakan awal yang tepat adalah ...","options":{"A":"menunggu gejala muncul sebelum bertindak","B":"segera mencuci luka dan mencari pertolongan medis untuk evaluasi profilaksis pascapajanan","C":"meminum antibiotik tanpa pemeriksaan","D":"menutup luka dengan tanah"},"answer":"B","answerText":"segera mencuci luka dan mencari pertolongan medis untuk evaluasi profilaksis pascapajanan","modul":14,"moduleName":"Kesehatan, Lingkungan, dan Teknologi","difficulty":"Sulit","explain":"Paparan rabies memerlukan penanganan segera sebelum gejala.","deepConcept":"Pencegahan penyakit mencakup pengendalian pajanan, sanitasi, vaksinasi, dan perawatan yang tepat. Vaksin merangsang respons imun adaptif dan memori; antibiotik hanya bermanfaat untuk infeksi yang sesuai, bukan semua penyakit.","conceptName":"kesehatan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q42","package":1,"number":42,"question":"Ikan asing pemangsa dilepas ke danau dan memangsa ikan endemik. Dampak ekologis yang perlu diwaspadai adalah ...","options":{"A":"hilangnya semua proses predasi","B":"bertambahnya habitat alami secara pasti","C":"kenaikan otomatis semua spesies asli","D":"penurunan populasi spesies asli"},"answer":"D","answerText":"penurunan populasi spesies asli","modul":13,"moduleName":"Ekologi dan Pelestarian Lingkungan","difficulty":"Sulit","explain":"Spesies invasif dapat menekan biota asli.","deepConcept":"Konservasi in situ melindungi spesies di habitat aslinya, sementara ex situ menjaga populasi atau plasma nutfah di luar habitat. Gangguan dan fragmentasi habitat dapat mengurangi keterhubungan populasi asli.","conceptName":"konservasi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q43","package":1,"number":43,"question":"Hewan bertulang belakang yang memiliki bulu sejati, paruh, dan berkembang biak dengan telur termasuk kelas ...","options":{"A":"Reptilia","B":"Mammalia","C":"Amphibia","D":"Aves"},"answer":"D","answerText":"Aves","modul":2,"moduleName":"Keanekaragaman dan Klasifikasi","difficulty":"Sedang","explain":"Bulu sejati merupakan ciri khas burung.","deepConcept":"Pengelompokan organisme didasarkan pada kumpulan karakter diagnostik, bukan satu ciri acak. Contohnya bulu sejati pada Aves, eksoskeleton kitin dan ruas kaki pada Arthropoda, serta klorofil pada tumbuhan hijau.","conceptName":"kelompok","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q44","package":1,"number":44,"question":"Gelombang memiliki frekuensi 5 Hz dan panjang gelombang 2 m. Cepat rambatnya adalah ...","options":{"A":"5 m/s","B":"20 m/s","C":"10 m/s","D":"2,5 m/s"},"answer":"C","answerText":"10 m/s","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sedang","explain":"v=fλ=5×2=10 m/s.","math":{"title":"Hubungan panjang gelombang, frekuensi, dan cepat rambat","foundation":"Dalam satu periode T, gelombang menempuh satu panjang gelombang λ. Karena v = jarak/waktu = λ/T dan f=1/T, diperoleh v = fλ; bentuk lainnya f = v/λ dan λ = v/f.","steps":["Dalam satu periode, gelombang menempuh λ sehingga v = λ/T.","Karena f = 1/T, diperoleh v = fλ.","v = 5 × 2 = 10 m/s."],"symbol":"wave"},"deepConcept":"Frekuensi menyatakan banyak siklus per detik; periode menyatakan durasi satu siklus, dengan f = 1/T. Kecepatan gelombang terhubung ke frekuensi dan panjang gelombang melalui v = fλ.","conceptName":"gelombang","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Cepat rambat 5 m/s tidak cocok dengan f×λ = 5×2 = 10 m/s.","B":"Cepat rambat 20 m/s tidak cocok dengan f×λ = 5×2 = 10 m/s.","D":"Cepat rambat 2,5 m/s tidak cocok dengan f×λ = 5×2 = 10 m/s."}},{"id":"p1q45","package":1,"number":45,"question":"Instrumen pencatat getaran akibat gempa bumi disebut ...","options":{"A":"barometer","B":"seismograf","C":"anemometer","D":"higrometer"},"answer":"B","answerText":"seismograf","modul":12,"moduleName":"Bumi, Tata Surya, dan Antariksa","difficulty":"Sedang","explain":"Seismograf merekam gerakan tanah.","deepConcept":"Litosfer tersusun dari lempeng yang bergerak; zona subduksi muncul saat satu lempeng menunjam. Cuaca terutama berlangsung di troposfer; aktivitas geotermal terjadi akibat panas dari dalam Bumi.","conceptName":"bumi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q46","package":1,"number":46,"question":"Es yang berubah menjadi air merupakan proses ...","options":{"A":"mengembun","B":"mencair","C":"membeku","D":"menyublim"},"answer":"B","answerText":"mencair","modul":7,"moduleName":"Wujud Benda dan Fluida","difficulty":"Sedang","explain":"Padat ke cair disebut mencair.","deepConcept":"Perubahan wujud dibedakan berdasarkan arah: padat→cair mencair; gas→cair mengembun; padat→gas menyublim; gas→padat deposisi. Titik didih turun ketika tekanan luar turun.","conceptName":"wujud","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q47","package":1,"number":47,"question":"Ketika tangan menyentuh benda panas, tangan segera ditarik sebelum kita sepenuhnya menyadarinya. Jalur respons awal itu melalui ...","options":{"A":"pencernaan di lambung","B":"kerja ginjal","C":"proses fotosintesis","D":"lengkung refleks pada sumsum tulang belakang"},"answer":"D","answerText":"lengkung refleks pada sumsum tulang belakang","modul":3,"moduleName":"Fisiologi Hewan","difficulty":"Sulit","explain":"Refleks dapat dimediasi oleh sumsum tulang belakang.","deepConcept":"Lengkung refleks memungkinkan respons cepat melalui neuron sensorik, interneuron pada sistem saraf pusat, dan neuron motorik. Kesadaran dapat muncul setelah sinyal telah memicu gerak refleks.","conceptName":"saraf","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q48","package":1,"number":48,"question":"Sinar datang membentuk sudut 30° terhadap garis normal pada cermin datar. Sudut pantulnya adalah ...","options":{"A":"90°","B":"15°","C":"60°","D":"30°"},"answer":"D","answerText":"30°","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sedang","explain":"Hukum pemantulan: sudut datang sama dengan sudut pantul.","math":{"title":"Hukum pemantulan pada cermin datar","foundation":"Sudut datang dan sudut pantul selalu diukur terhadap garis normal (tegak lurus cermin). Hukum pemantulan: i = r. Jika sudut diberikan terhadap permukaan cermin, ubah menjadi i = 90° − sudut permukaan.","steps":["Garis normal selalu tegak lurus permukaan cermin.","Hukum pemantulan: sudut datang i sama dengan sudut pantul r, keduanya terhadap normal.","Sudut pantul r = i (atau sudut datang i = r).","Hasil = 30°."],"symbol":"reflect"},"deepConcept":"Pada cermin datar, sudut datang sama dengan sudut pantul jika diukur dari garis normal. Pada cermin cembung, sinar pantul menyebar sehingga bidang pandang menjadi luas.","conceptName":"pantul","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Sudut 90° tidak sesuai dengan hukum pemantulan untuk sudut terhadap normal 30°. Hubungan sudut yang diminta menghasilkan 30°.","B":"Sudut 15° tidak sesuai dengan hukum pemantulan untuk sudut terhadap normal 30°. Hubungan sudut yang diminta menghasilkan 30°.","C":"Sudut 60° tidak sesuai dengan hukum pemantulan untuk sudut terhadap normal 30°. Hubungan sudut yang diminta menghasilkan 30°."}},{"id":"p1q49","package":1,"number":49,"question":"Dua spesies ikan mirip bentuk tubuhnya, tetapi analisis DNA memperlihatkan perbedaan genetik konsisten. Kesimpulan ilmiah paling tepat adalah ...","options":{"A":"DNA tidak boleh digunakan dalam taksonomi","B":"dua ikan pasti berasal dari kingdom berbeda","C":"pasti sama spesies hanya karena bentuknya mirip","D":"perlu mempertimbangkan keduanya sebagai spesies berbeda setelah verifikasi tambahan"},"answer":"D","answerText":"perlu mempertimbangkan keduanya sebagai spesies berbeda setelah verifikasi tambahan","modul":2,"moduleName":"Keanekaragaman dan Klasifikasi","difficulty":"Sulit","explain":"Identifikasi spesies mempertimbangkan bukti morfologi dan molekuler.","deepConcept":"Keanekaragaman genetik terjadi dalam satu spesies akibat kombinasi alel yang berbeda. Perbedaan gen tidak otomatis berarti spesies baru; pemisahan spesies membutuhkan bukti biologis dan evolusioner yang memadai.","conceptName":"genetik","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p1q50","package":1,"number":50,"question":"Bunga ungu dominan (U) terhadap putih (u). Persilangan Uu × Uu menghasilkan peluang keturunan berbunga putih sebesar ...","options":{"A":"25%","B":"50%","C":"0%","D":"75%"},"answer":"A","answerText":"25%","modul":5,"moduleName":"Sistem Organ, Sel, dan Genetika","difficulty":"Sedang","explain":"Rasio genotipe 1 UU : 2 Uu : 1 uu.","math":{"title":"Menurunkan peluang dengan kotak Punnett","foundation":"Tiap induk menurunkan satu alel dalam gamet. Daftar semua gamet kedua induk, gabungkan semua pasangan yang sama mungkin, lalu hitung jumlah genotipe/fenotipe sesuai pertanyaan dibagi semua kombinasi.","steps":["Hukum segregasi Mendel: setiap gamet membawa satu dari dua alel induk.","Gamet induk pertama (Uu): U dan u; gamet induk kedua (Uu): U dan u.","Empat kotak Punnett yang sama peluangnya: UU, Uu, Uu, uu.","Keturunan yang memenuhi target = 1 dari 4 kemungkinan → 1/4 × 100% = 25%."],"symbol":"genetics"},"deepConcept":"Pada dominansi lengkap, alel dominan muncul pada genotipe heterozigot; fenotipe resesif membutuhkan dua alel resesif. Rasio dihitung dari probabilitas gamet dan kotak Punnett, bukan menebak dari tampilan induk.","conceptName":"genetika","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"B":"Peluang tersebut tidak sesuai dengan menghitung semua kombinasi gamet pada kotak Punnett. Keturunan yang memenuhi target = 1 dari 4 kemungkinan → 1/4 × 100% = 25%.","C":"Peluang tersebut tidak sesuai dengan menghitung semua kombinasi gamet pada kotak Punnett. Keturunan yang memenuhi target = 1 dari 4 kemungkinan → 1/4 × 100% = 25%.","D":"Peluang tersebut tidak sesuai dengan menghitung semua kombinasi gamet pada kotak Punnett. Keturunan yang memenuhi target = 1 dari 4 kemungkinan → 1/4 × 100% = 25%."}},{"id":"p2q1","package":2,"number":1,"question":"Beban 80 N ditempatkan 30 cm dari titik tumpu. Kuasa bekerja 60 cm di sisi lainnya. Gaya untuk seimbang adalah ...","options":{"A":"160 N","B":"20 N","C":"40 N","D":"80 N"},"answer":"C","answerText":"40 N","modul":6,"moduleName":"Mekanika","difficulty":"Sulit","explain":"80×30 = F×60, sehingga F=40 N.","math":{"title":"Keseimbangan momen gaya","foundation":"Momen gaya terhadap titik tumpu adalah τ = F × l (lengan tegak lurus). Tuas seimbang apabila momen searah jarum jam sama dengan momen berlawanan arah: F₁l₁ = F₂l₂.","steps":["Abaikan gesekan dan massa tuas; jumlah momen terhadap titik tumpu = 0.","Momen sisi pertama = momen sisi kedua: F₁ × l₁ = F₂ × l₂.","80 × 30 = F₂ × 60 (lengan sama-sama dalam cm).","F₂ = (80 × 30)/60 = 40 N."],"symbol":"lever"},"deepConcept":"Gaya adalah besaran vektor; resultan harus mempertimbangkan arah. Benda bermassa m mengalami percepatan a menurut ΣF = ma. Gaya gesek yang melawan gerak dikurangkan dari gaya dorong.","conceptName":"gaya","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Gaya 160 N pada lengan 60 cm menghasilkan momen 9.600 N·cm, sementara momen sisi lain 2.400 N·cm. Momen belum seimbang.","B":"Gaya 20 N pada lengan 60 cm menghasilkan momen 1.200 N·cm, sementara momen sisi lain 2.400 N·cm. Momen belum seimbang.","D":"Gaya 80 N pada lengan 60 cm menghasilkan momen 4.800 N·cm, sementara momen sisi lain 2.400 N·cm. Momen belum seimbang."}},{"id":"p2q2","package":2,"number":2,"question":"Virus tidak dikategorikan sebagai sel hidup mandiri karena ...","options":{"A":"mampu melakukan metabolisme sendiri secara lengkap","B":"memiliki ribosom yang sangat banyak","C":"memerlukan sel inang untuk memperbanyak diri","D":"selalu melakukan fotosintesis"},"answer":"C","answerText":"memerlukan sel inang untuk memperbanyak diri","modul":5,"moduleName":"Sistem Organ, Sel, dan Genetika","difficulty":"Sulit","explain":"Virus bereplikasi menggunakan mesin molekuler inang.","deepConcept":"Virus bukan sel dan tidak memiliki ribosom atau metabolisme mandiri penuh; virus perlu sel inang untuk reproduksi. Antibiotik dengan target struktur bakteri tidak bekerja terhadap virus yang tidak memiliki struktur tersebut.","conceptName":"virus","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q3","package":2,"number":3,"question":"Peningkatan bakteri resisten antibiotik dapat dipicu oleh ...","options":{"A":"vaksinasi yang benar","B":"penggunaan antibiotik yang tidak tepat dan berlebihan","C":"mencuci tangan setelah beraktivitas","D":"penggunaan antibiotik sesuai resep secara tepat"},"answer":"B","answerText":"penggunaan antibiotik yang tidak tepat dan berlebihan","modul":14,"moduleName":"Kesehatan, Lingkungan, dan Teknologi","difficulty":"Sulit","explain":"Penyalahgunaan antibiotik menyeleksi strain resisten.","deepConcept":"Pencegahan penyakit mencakup pengendalian pajanan, sanitasi, vaksinasi, dan perawatan yang tepat. Vaksin merangsang respons imun adaptif dan memori; antibiotik hanya bermanfaat untuk infeksi yang sesuai, bukan semua penyakit.","conceptName":"kesehatan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q4","package":2,"number":4,"question":"Dua lampu dengan hambatan 4 Ω dan 6 Ω dipasang seri. Hambatan penggantinya ...","options":{"A":"10 Ω","B":"5 Ω","C":"2,4 Ω","D":"24 Ω"},"answer":"A","answerText":"10 Ω","modul":8,"moduleName":"Listrik dan Magnet","difficulty":"Sedang","explain":"R seri dijumlahkan: 4+6=10.","math":{"title":"Mengapa hambatan seri dijumlahkan?","foundation":"Arus I sama melalui setiap resistor seri; tegangan sumber terbagi: V total = V₁+V₂+… = IR₁+IR₂+… = I(R₁+R₂+…). Membagi kedua ruas dengan I menghasilkan R total = ΣR.","steps":["Arus pada semua resistor seri sama.","Tegangan total V = Σ(IRᵢ) = I ΣRᵢ → R total = ΣRᵢ.","R total = 4 + 6 = 10 Ω."],"symbol":"series"},"deepConcept":"Rangkaian seri memiliki arus yang sama dan tegangan terbagi, sehingga R total dijumlahkan. Rangkaian paralel memiliki tegangan yang sama dan arus terbagi, sehingga kebalikan hambatan dijumlahkan.","conceptName":"rangkaian","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"B":"Hambatan 5 Ω tidak sama dengan jumlah hambatan seri = 4 + 6 = 10 Ω.","C":"Hambatan 2,4 Ω tidak sama dengan jumlah hambatan seri = 4 + 6 = 10 Ω.","D":"Hambatan 24 Ω tidak sama dengan jumlah hambatan seri = 4 + 6 = 10 Ω."}},{"id":"p2q5","package":2,"number":5,"question":"Tempat utama fotosintesis pada sel tumbuhan adalah ...","options":{"A":"sentriol","B":"kloroplas","C":"mitokondria","D":"badan Golgi"},"answer":"B","answerText":"kloroplas","modul":5,"moduleName":"Sistem Organ, Sel, dan Genetika","difficulty":"Mudah","explain":"Kloroplas memiliki klorofil dan tilakoid.","deepConcept":"Kloroplas menangkap energi cahaya; mitokondria menghasilkan banyak ATP melalui respirasi aerob; ribosom menyusun protein; badan Golgi memodifikasi dan mengemas produk. DNA sel eukariotik sebagian besar berada di nukleus, sedangkan bakteri memiliki nukleoid.","conceptName":"organel","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q6","package":2,"number":6,"question":"Benda 5 kg didorong gaya 30 N, tetapi gaya gesek melawannya 10 N. Percepatan benda adalah ...","options":{"A":"4 m/s²","B":"8 m/s²","C":"2 m/s²","D":"6 m/s²"},"answer":"A","answerText":"4 m/s²","modul":6,"moduleName":"Mekanika","difficulty":"Sedang","explain":"F net=30−10=20 N; a=20/5=4.","math":{"title":"Hukum II Newton dan resultan gaya","foundation":"Hukum II Newton menyatakan ΣF = m a. Gaya berlawanan arah diberi tanda berlawanan sehingga ΣF = F dorong − F gesek; akibatnya a = ΣF/m.","steps":["Pilih arah dorong/tarik sebagai arah positif.","Dari Hukum II Newton: ΣF = ma, sehingga a = ΣF/m.","Gaya bersih ΣF = 30 − 10 = 20 N.","a = 20/5 = 4 m/s²."],"symbol":"newton"},"deepConcept":"Gaya adalah besaran vektor; resultan harus mempertimbangkan arah. Benda bermassa m mengalami percepatan a menurut ΣF = ma. Gaya gesek yang melawan gerak dikurangkan dari gaya dorong.","conceptName":"gaya","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"B":"Jika percepatan 8 m/s², gaya bersih yang dibutuhkan m×a = 5×8 = 40 N, padahal soal menetapkan gaya bersih 20 N.","C":"Jika percepatan 2 m/s², gaya bersih yang dibutuhkan m×a = 5×2 = 10 N, padahal soal menetapkan gaya bersih 20 N.","D":"Jika percepatan 6 m/s², gaya bersih yang dibutuhkan m×a = 5×6 = 30 N, padahal soal menetapkan gaya bersih 20 N."}},{"id":"p2q7","package":2,"number":7,"question":"Bank benih yang menyimpan biji tumbuhan langka merupakan konservasi ...","options":{"A":"in situ murni","B":"pemangsaan","C":"pencemaran","D":"ex situ"},"answer":"D","answerText":"ex situ","modul":13,"moduleName":"Ekologi dan Pelestarian Lingkungan","difficulty":"Sedang","explain":"Ex situ dilakukan di luar habitat alami.","deepConcept":"Konservasi in situ melindungi spesies di habitat aslinya, sementara ex situ menjaga populasi atau plasma nutfah di luar habitat. Gangguan dan fragmentasi habitat dapat mengurangi keterhubungan populasi asli.","conceptName":"konservasi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q8","package":2,"number":8,"question":"Daun tumbuhan hijau ditempatkan dalam ruang gelap lama. Pembentukan pati dari fotosintesis biasanya ...","options":{"A":"menghasilkan oksigen lebih banyak daripada saat bercahaya","B":"meningkat terus tanpa cahaya","C":"tidak dapat berubah dalam kondisi apa pun","D":"menurun karena energi cahaya tidak tersedia"},"answer":"D","answerText":"menurun karena energi cahaya tidak tersedia","modul":4,"moduleName":"Fisiologi Tumbuhan","difficulty":"Sedang","explain":"Reaksi terang memerlukan energi cahaya.","deepConcept":"Fotosintesis memerlukan cahaya, CO₂, air, pigmen, dan enzim. Laju fotosintesis dibatasi faktor yang paling tidak mencukupi; peningkatan cahaya tidak lagi menaikkan laju jika faktor lain menjadi batas.","conceptName":"fotosintesis","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q9","package":2,"number":9,"question":"Tekanan yang sama diteruskan pada piston 10 cm² dan 200 cm². Jika gaya pada piston kecil 40 N, gaya pada piston besar adalah ...","options":{"A":"1.600 N","B":"80 N","C":"400 N","D":"800 N"},"answer":"D","answerText":"800 N","modul":7,"moduleName":"Wujud Benda dan Fluida","difficulty":"Sulit","explain":"F2=40×200/10=800 N.","math":{"title":"Penurunan hukum Pascal","foundation":"Dalam fluida tertutup yang ideal, tambahan tekanan diteruskan sama besar: p₁ = p₂. Karena p = F/A, diperoleh F₁/A₁ = F₂/A₂. Piston berluas lebih besar menghasilkan gaya lebih besar.","steps":["Tekanan sama: F₁/A₁ = F₂/A₂.","Susun ulang sesuai gaya yang dicari: F₂ = F₁ × (A₂/A₁), atau F₁ = F₂ × (A₁/A₂).","F₂ = 40 × (200/10) = 800 N.","Perbandingan luas bebas satuan karena pembilang dan penyebut memakai cm² yang sama."],"symbol":"pascal"},"deepConcept":"Hukum Pascal menghubungkan kenaikan tekanan yang sama dalam fluida tertutup. Karena p = F/A, perbandingan gaya piston sebanding perbandingan luasnya; hasil ideal mengabaikan gesekan.","conceptName":"hidrolik","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Gaya keluaran 1.600 N memberi tekanan di piston besar F₂/A₂ = 1.600/200 = 8 N/cm², berbeda dari tekanan masuk 4 N/cm².","B":"Gaya keluaran 80 N memberi tekanan di piston besar F₂/A₂ = 80/200 = 0,4 N/cm², berbeda dari tekanan masuk 4 N/cm².","C":"Gaya keluaran 400 N memberi tekanan di piston besar F₂/A₂ = 400/200 = 2 N/cm², berbeda dari tekanan masuk 4 N/cm²."}},{"id":"p2q10","package":2,"number":10,"question":"Lensa cembung digunakan pada kaca pembesar. Ketika objek berada di dalam jarak fokus, bayangan bersifat ...","options":{"A":"nyata, tegak, dan sama besar","B":"maya, tegak, dan diperbesar","C":"tidak terbentuk cahaya sama sekali","D":"nyata, terbalik, dan diperkecil"},"answer":"B","answerText":"maya, tegak, dan diperbesar","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sulit","explain":"Lensa konvergen membentuk bayangan maya bila objek berada di dalam fokus.","deepConcept":"Lensa cembung (konvergen) memusatkan berkas, sedangkan lensa cekung (divergen) menyebarkan berkas. Kamera membentuk bayangan nyata pada sensor, kaca pembesar dapat membentuk bayangan maya diperbesar.","conceptName":"lensa","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q11","package":2,"number":11,"question":"Hewan dengan tubuh lunak dan delapan keping cangkang di punggung adalah kelompok ...","options":{"A":"Mollusca","B":"Echinodermata","C":"Cnidaria","D":"Annelida"},"answer":"A","answerText":"Mollusca","modul":2,"moduleName":"Keanekaragaman dan Klasifikasi","difficulty":"Sedang","explain":"Chiton merupakan moluska dengan delapan keping cangkang.","deepConcept":"Pengelompokan organisme didasarkan pada kumpulan karakter diagnostik, bukan satu ciri acak. Contohnya bulu sejati pada Aves, eksoskeleton kitin dan ruas kaki pada Arthropoda, serta klorofil pada tumbuhan hijau.","conceptName":"kelompok","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q12","package":2,"number":12,"question":"Peneliti menguji pengaruh suhu terhadap waktu perkecambahan. Variabel terikat adalah ...","options":{"A":"jenis biji yang disamakan","B":"waktu perkecambahan","C":"suhu perlakuan","D":"volume air yang disamakan"},"answer":"B","answerText":"waktu perkecambahan","modul":1,"moduleName":"Keterampilan dan Metode Ilmiah","difficulty":"Sedang","explain":"Variabel terikat merupakan hasil yang diukur.","deepConcept":"Variabel bebas adalah faktor yang sengaja diubah; variabel terikat adalah hasil yang diukur; variabel kontrol adalah faktor lain yang dibuat tetap. Perbandingan bermakna jika perlakuan berbeda pada satu faktor utama saja.","conceptName":"variabel","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q13","package":2,"number":13,"question":"Ikan menyerap oksigen terlarut terutama melalui ...","options":{"A":"insang","B":"sirip ekor","C":"sisik","D":"gelembung renang pada semua ikan"},"answer":"A","answerText":"insang","modul":3,"moduleName":"Fisiologi Hewan","difficulty":"Sedang","explain":"Insang memiliki luas permukaan untuk difusi gas.","deepConcept":"Pertukaran gas terjadi lewat difusi dari tekanan parsial tinggi ke rendah. Permukaan alveolus luas dan dinding tipis mempercepat difusi; peningkatan CO₂ memicu ventilasi sebagai mekanisme homeostasis.","conceptName":"napas","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q14","package":2,"number":14,"question":"Mobil menempuh 180 km dalam 3 jam dengan kelajuan tetap. Kelajuannya adalah ...","options":{"A":"90 km/jam","B":"60 km/jam","C":"30 km/jam","D":"540 km/jam"},"answer":"B","answerText":"60 km/jam","modul":6,"moduleName":"Mekanika","difficulty":"Sedang","explain":"Kelajuan = 180/3 = 60 km/jam.","math":{"title":"Kelajuan dari definisi gerak","foundation":"Kelajuan rata-rata didefinisikan sebagai total jarak dibagi total waktu: v = s/t. Jika jarak dan waktu memakai satuan yang tidak cocok, konversikan terlebih dahulu.","steps":["Besaran diketahui: jarak s = 180 km; waktu t = 3 jam.","Definisi kelajuan rata-rata: v = s/t.","Satuan jarak dan waktu sudah sepadan.","v = 180/3 = 60 km/jam."],"symbol":"speed"},"deepConcept":"Kelajuan rata-rata memakai jarak tempuh total dibagi durasi total. Untuk memperoleh m/s, pakai meter dan detik; 1 km = 1.000 m dan 1 menit = 60 detik.","conceptName":"kelajuan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Nilai 90 km/jam tidak sama dengan s/t = 180/3 = 60 km/jam untuk data pada soal.","C":"Nilai 30 km/jam tidak sama dengan s/t = 180/3 = 60 km/jam untuk data pada soal.","D":"Nilai 540 km/jam tidak sama dengan s/t = 180/3 = 60 km/jam untuk data pada soal."}},{"id":"p2q15","package":2,"number":15,"question":"Antibiotik tidak efektif untuk menyembuhkan flu biasa karena flu umumnya disebabkan oleh ...","options":{"A":"bakteri penyebab tuberkulosis","B":"jamur tempe","C":"protozoa malaria","D":"virus"},"answer":"D","answerText":"virus","modul":14,"moduleName":"Kesehatan, Lingkungan, dan Teknologi","difficulty":"Sedang","explain":"Antibiotik menarget proses biologis bakteri, bukan virus flu.","deepConcept":"Pencegahan penyakit mencakup pengendalian pajanan, sanitasi, vaksinasi, dan perawatan yang tepat. Vaksin merangsang respons imun adaptif dan memori; antibiotik hanya bermanfaat untuk infeksi yang sesuai, bukan semua penyakit.","conceptName":"kesehatan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q16","package":2,"number":16,"question":"Cahaya merambat dari udara ke kaca dengan sudut datang tidak nol. Arah pembiasan umumnya ...","options":{"A":"selalu menjauhi garis normal","B":"selalu sejajar bidang batas","C":"mendekati garis normal","D":"selalu kembali ke sumber tanpa masuk kaca"},"answer":"C","answerText":"mendekati garis normal","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sulit","explain":"Kaca memiliki indeks bias lebih tinggi daripada udara.","deepConcept":"Pada cermin datar, sudut datang sama dengan sudut pantul jika diukur dari garis normal. Pada cermin cembung, sinar pantul menyebar sehingga bidang pandang menjadi luas.","conceptName":"pantul","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q17","package":2,"number":17,"question":"Motor menerima energi listrik 800 J dan menghasilkan energi mekanik berguna 600 J. Efisiensinya ...","options":{"A":"25%","B":"60%","C":"133%","D":"75%"},"answer":"D","answerText":"75%","modul":11,"moduleName":"Bentuk Energi dan Perubahannya","difficulty":"Sedang","explain":"Efisiensi=600/800×100%=75%.","math":{"title":"Efisiensi dari konservasi energi","foundation":"Energi masuk tidak seluruhnya berubah menjadi keluaran yang diinginkan. Secara definisi, efisiensi η = (E berguna/E masuk)×100%. Pada alat biasa, sisanya terbuang sebagai kalor, suara, dll.","steps":["Efisiensi adalah proporsi energi masuk yang benar-benar menjadi energi berguna.","Dari definisi bagian = keluaran/masukan, sehingga η = E berguna/E masuk × 100%.","η = (600/800) × 100% = 75%.","Energi yang tidak menjadi keluaran berguna = 200 J (misalnya terdisipasi sebagai kalor)."],"symbol":"efficiency"},"deepConcept":"Energi tidak diciptakan dari ketiadaan. Efisiensi adalah persentase energi masuk yang menjadi keluaran berguna; tidak mengukur energi yang “hilang”, tetapi energi yang berpindah ke bentuk tak diinginkan.","conceptName":"energi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Efisiensi 25% menyatakan energi berguna 200 J dari masukan 800 J, padahal keluaran soal 600 J.","B":"Efisiensi 60% menyatakan energi berguna 480 J dari masukan 800 J, padahal keluaran soal 600 J.","C":"Efisiensi 133% menyatakan energi berguna 1.064 J dari masukan 800 J, padahal keluaran soal 600 J."}},{"id":"p2q18","package":2,"number":18,"question":"Gerhana Bulan terjadi ketika ...","options":{"A":"Matahari berada di antara Bulan dan Bumi","B":"Bulan tidak menerima cahaya sepanjang bulan","C":"Bulan berada di antara Matahari dan Bumi","D":"Bumi berada di antara Matahari dan Bulan"},"answer":"D","answerText":"Bumi berada di antara Matahari dan Bulan","modul":12,"moduleName":"Bumi, Tata Surya, dan Antariksa","difficulty":"Sedang","explain":"Bayangan Bumi jatuh pada Bulan.","deepConcept":"Gerhana Matahari terjadi ketika Bulan berada di antara Matahari–Bumi; gerhana Bulan ketika Bumi berada di antara Matahari–Bulan. Umbra merupakan bagian bayangan paling gelap.","conceptName":"gerhana","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q19","package":2,"number":19,"question":"Pada bunga, setelah pembuahan, bakal biji terutama berkembang menjadi ...","options":{"A":"mahkota bunga","B":"biji","C":"akar adventif","D":"stomata"},"answer":"B","answerText":"biji","modul":4,"moduleName":"Fisiologi Tumbuhan","difficulty":"Sulit","explain":"Bakal biji tumbuh menjadi biji setelah fertilisasi.","deepConcept":"Kambium vaskular membentuk xilem/floem sekunder sehingga batang menebal. Setelah pembuahan bunga, bakal buah berkembang menjadi buah dan bakal biji menjadi biji.","conceptName":"struktur","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q20","package":2,"number":20,"question":"Biji bulat (B) dominan terhadap keriput (b). Persilangan Bb × bb menghasilkan keturunan keriput sebesar ...","options":{"A":"100%","B":"50%","C":"25%","D":"0%"},"answer":"B","answerText":"50%","modul":5,"moduleName":"Sistem Organ, Sel, dan Genetika","difficulty":"Sedang","explain":"Bb dan bb masing-masing 50%.","math":{"title":"Menurunkan peluang dengan kotak Punnett","foundation":"Tiap induk menurunkan satu alel dalam gamet. Daftar semua gamet kedua induk, gabungkan semua pasangan yang sama mungkin, lalu hitung jumlah genotipe/fenotipe sesuai pertanyaan dibagi semua kombinasi.","steps":["Hukum segregasi Mendel: setiap gamet membawa satu dari dua alel induk.","Gamet induk pertama (Bb): B dan b; gamet induk kedua (bb): b dan b.","Empat kotak Punnett yang sama peluangnya: Bb, Bb, bb, bb.","Keturunan yang memenuhi target = 2 dari 4 kemungkinan → 2/4 × 100% = 50%."],"symbol":"genetics"},"deepConcept":"Pada dominansi lengkap, alel dominan muncul pada genotipe heterozigot; fenotipe resesif membutuhkan dua alel resesif. Rasio dihitung dari probabilitas gamet dan kotak Punnett, bukan menebak dari tampilan induk.","conceptName":"genetika","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Peluang tersebut tidak sesuai dengan menghitung semua kombinasi gamet pada kotak Punnett. Keturunan yang memenuhi target = 2 dari 4 kemungkinan → 2/4 × 100% = 50%.","C":"Peluang tersebut tidak sesuai dengan menghitung semua kombinasi gamet pada kotak Punnett. Keturunan yang memenuhi target = 2 dari 4 kemungkinan → 2/4 × 100% = 50%.","D":"Peluang tersebut tidak sesuai dengan menghitung semua kombinasi gamet pada kotak Punnett. Keturunan yang memenuhi target = 2 dari 4 kemungkinan → 2/4 × 100% = 50%."}},{"id":"p2q21","package":2,"number":21,"question":"Hasil fotosintesis diangkut dari daun menuju organ penyimpan melalui ...","options":{"A":"stomata","B":"lentisel","C":"floem","D":"xilem saja"},"answer":"C","answerText":"floem","modul":4,"moduleName":"Fisiologi Tumbuhan","difficulty":"Mudah","explain":"Floem mentranslokasikan gula hasil fotosintesis.","deepConcept":"Xilem mengalirkan air/mineral dari akar; floem mentranslokasikan gula dari bagian sumber ke bagian pemakai/penyimpan. Sel penjaga mengubah turgor untuk membuka atau menutup stomata.","conceptName":"transport","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q22","package":2,"number":22,"question":"Sebuah senar bergetar 120 kali dalam 3 s. Frekuensinya adalah ...","options":{"A":"40 Hz","B":"30 Hz","C":"360 Hz","D":"3 Hz"},"answer":"A","answerText":"40 Hz","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sedang","explain":"f=120/3=40 Hz.","math":{"title":"Frekuensi dan periode dari definisi","foundation":"Frekuensi f adalah banyaknya getaran n dalam waktu t, maka f = n/t. Periode T adalah waktu satu getaran, sehingga T = t/n = 1/f. Satuan f = hertz (Hz), T = detik (s).","steps":["Frekuensi adalah getaran per detik: f = n/t.","Periode adalah detik per getaran: T = t/n = 1/f.","Diketahui n = 120 dan t = 3 s, jadi f = 120/3 = 40 Hz."],"symbol":"frequency"},"deepConcept":"Frekuensi menyatakan banyak siklus per detik; periode menyatakan durasi satu siklus, dengan f = 1/T. Kecepatan gelombang terhubung ke frekuensi dan panjang gelombang melalui v = fλ.","conceptName":"gelombang","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"B":"Frekuensi 30 Hz akan menghasilkan n = f×t = 90 getaran selama 3 s, bukan 120 getaran.","C":"Frekuensi 360 Hz akan menghasilkan n = f×t = 1.080 getaran selama 3 s, bukan 120 getaran.","D":"Frekuensi 3 Hz akan menghasilkan n = f×t = 9 getaran selama 3 s, bukan 120 getaran."}},{"id":"p2q23","package":2,"number":23,"question":"Untuk menguji apakah cahaya memengaruhi pertumbuhan kecambah, rancangan paling tepat adalah ...","options":{"A":"dua tanaman dengan pupuk dan cahaya sekaligus diubah","B":"dua kelompok kecambah sejenis dengan air sama, tetapi intensitas cahaya berbeda","C":"dua jenis tanaman dengan air dan cahaya berbeda","D":"satu kecambah diamati sekali tanpa pembanding"},"answer":"B","answerText":"dua kelompok kecambah sejenis dengan air sama, tetapi intensitas cahaya berbeda","modul":1,"moduleName":"Keterampilan dan Metode Ilmiah","difficulty":"Sulit","explain":"Percobaan mengubah satu variabel bebas sambil mengontrol yang lain.","deepConcept":"Variabel bebas adalah faktor yang sengaja diubah; variabel terikat adalah hasil yang diukur; variabel kontrol adalah faktor lain yang dibuat tetap. Perbandingan bermakna jika perlakuan berbeda pada satu faktor utama saja.","conceptName":"variabel","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q24","package":2,"number":24,"question":"Arteri pulmonalis membawa darah dari ...","options":{"A":"bilik kiri ke seluruh tubuh","B":"bilik kanan ke paru-paru","C":"paru-paru ke serambi kiri","D":"serambi kanan ke seluruh tubuh"},"answer":"B","answerText":"bilik kanan ke paru-paru","modul":3,"moduleName":"Fisiologi Hewan","difficulty":"Mudah","explain":"Arteri pulmonalis membawa darah dari jantung menuju paru-paru.","deepConcept":"Aliran darah sistemik: bilik kiri → aorta → jaringan → vena kava → serambi kanan. Aliran pulmonal: bilik kanan → arteri pulmonalis → paru-paru → vena pulmonalis → serambi kiri. Katup menjaga aliran satu arah.","conceptName":"peredaran","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q25","package":2,"number":25,"question":"Tegangan baterai 9 V dipasang pada hambatan 3 Ω. Arusnya adalah ...","options":{"A":"27 A","B":"3 A","C":"6 A","D":"0,33 A"},"answer":"B","answerText":"3 A","modul":8,"moduleName":"Listrik dan Magnet","difficulty":"Sedang","explain":"I=9/3=3 A.","math":{"title":"Hukum Ohm","foundation":"Untuk resistor ohmik pada kondisi tetap, tegangan V sebanding dengan arus I: V = I R. Dengan membagi kedua ruas, I = V/R atau R = V/I sesuai besaran yang ditanyakan.","steps":["Mulai dari Hukum Ohm: V = I × R.","Bagi kedua ruas dengan R → I = V/R.","I = 9/3 = 3 A."],"symbol":"ohm"},"deepConcept":"Rangkaian seri memiliki arus yang sama dan tegangan terbagi, sehingga R total dijumlahkan. Rangkaian paralel memiliki tegangan yang sama dan arus terbagi, sehingga kebalikan hambatan dijumlahkan.","conceptName":"rangkaian","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Arus 27 A pada hambatan 3 Ω memerlukan V = IR = 81 V, tidak sama dengan sumber 9 V.","C":"Arus 6 A pada hambatan 3 Ω memerlukan V = IR = 18 V, tidak sama dengan sumber 9 V.","D":"Arus 0,33 A pada hambatan 3 Ω memerlukan V = IR = 0,99 V, tidak sama dengan sumber 9 V."}},{"id":"p2q26","package":2,"number":26,"question":"Benda 0,5 kg memiliki kalor jenis 400 J/kg°C dan naik suhu 20 °C. Kalor yang diperlukan ...","options":{"A":"8.000 J","B":"400 J","C":"4.000 J","D":"40.000 J"},"answer":"C","answerText":"4.000 J","modul":10,"moduleName":"Suhu dan Kalor","difficulty":"Sulit","explain":"Q=0,5×400×20=4.000 J.","math":{"title":"Kalor jenis dan perubahan suhu","foundation":"Kalor jenis c didefinisikan sebagai energi kalor yang dibutuhkan per satuan massa untuk menaikkan suhu sebesar satu derajat: c = Q/(mΔT). Susun ulang menjadi Q = mcΔT, berlaku selama tidak ada perubahan wujud.","steps":["Definisi kalor jenis: c = Q/(mΔT).","Kalikan kedua ruas dengan mΔT → Q = mcΔT.","Massa m = 0,5 kg; kalor jenis c = 400 J/(kg·°C); perubahan suhu ΔT = 20 °C.","Q = 0,5 × 400 × 20 = 4.000 J. Satuan kg dan °C saling habis."],"symbol":"heat"},"deepConcept":"Kalor adalah energi yang berpindah karena beda suhu. Saat tidak terjadi perubahan wujud, Q = mcΔT; makin besar massa, kalor jenis, atau selisih suhu, makin besar energi yang diperlukan.","conceptName":"kalor","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Kalor 8.000 J menghasilkan ΔT = Q/(mc) = 8.000/(0,5×400), berbeda dari ΔT soal 20 °C. Yang memenuhi Q = mcΔT adalah 4.000 J.","B":"Kalor 400 J menghasilkan ΔT = Q/(mc) = 400/(0,5×400), berbeda dari ΔT soal 20 °C. Yang memenuhi Q = mcΔT adalah 4.000 J.","D":"Kalor 40.000 J menghasilkan ΔT = Q/(mc) = 40.000/(0,5×400), berbeda dari ΔT soal 20 °C. Yang memenuhi Q = mcΔT adalah 4.000 J."}},{"id":"p2q27","package":2,"number":27,"question":"Jarum kompas di dekat kawat berarus menyimpang. Fenomena tersebut menunjukkan ...","options":{"A":"gaya gravitasi hilang","B":"arus tidak berpengaruh pada medan magnet","C":"suhu kompas pasti turun","D":"hubungan antara listrik dan magnetisme"},"answer":"D","answerText":"hubungan antara listrik dan magnetisme","modul":8,"moduleName":"Listrik dan Magnet","difficulty":"Sedang","explain":"Percobaan Oersted menunjukkan medan magnet akibat arus.","deepConcept":"Hukum Ohm V = IR memberi hubungan antara beda potensial, arus, dan hambatan untuk resistor ohmik. Ampere adalah satuan arus, volt satuan beda potensial, dan ohm satuan hambatan.","conceptName":"ohm","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q28","package":2,"number":28,"question":"Tetes air terbentuk di sisi luar gelas berisi es karena uap air udara ...","options":{"A":"menyublim","B":"mengalami sublimasi terbalik saja","C":"mengembun","D":"membeku langsung menjadi gas"},"answer":"C","answerText":"mengembun","modul":7,"moduleName":"Wujud Benda dan Fluida","difficulty":"Sedang","explain":"Uap air menjadi cair pada permukaan dingin.","deepConcept":"Perubahan wujud dibedakan berdasarkan arah: padat→cair mencair; gas→cair mengembun; padat→gas menyublim; gas→padat deposisi. Titik didih turun ketika tekanan luar turun.","conceptName":"wujud","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q29","package":2,"number":29,"question":"Ragi membuat adonan roti mengembang karena fermentasi menghasilkan ...","options":{"A":"belerang padat","B":"oksigen murni","C":"nitrogen cair","D":"karbon dioksida"},"answer":"D","answerText":"karbon dioksida","modul":14,"moduleName":"Kesehatan, Lingkungan, dan Teknologi","difficulty":"Sedang","explain":"Gas CO2 terperangkap dalam adonan.","deepConcept":"Bioteknologi memanfaatkan sel atau proses biologis untuk menghasilkan produk. Fermentasi adalah proses metabolik mikroba; teknik DNA rekombinan memungkinkan produksi protein seperti insulin.","conceptName":"biotek","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q30","package":2,"number":30,"question":"Ciri bersayap pada dua hewan belum tentu menandakan kekerabatan terdekat karena ...","options":{"A":"struktur mirip dapat muncul akibat evolusi konvergen","B":"taksonomi tidak memakai anatomi","C":"hewan bersayap pasti satu filum","D":"setiap sayap selalu terbentuk dari gen identik"},"answer":"A","answerText":"struktur mirip dapat muncul akibat evolusi konvergen","modul":2,"moduleName":"Keanekaragaman dan Klasifikasi","difficulty":"Sulit","explain":"Kesamaan fungsi dapat muncul secara independen.","deepConcept":"Urutan takson dari luas ke sempit ialah kingdom–filum–kelas–ordo–famili–genus–spesies. Makin dekat nenek moyang bersama suatu pasangan organisme, makin dekat pula hubungan evolusionernya.","conceptName":"taksonomi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q31","package":2,"number":31,"question":"Batuan panas cair yang telah keluar melalui gunung api disebut ...","options":{"A":"lava","B":"sedimen lempung","C":"magma di dalam bumi","D":"humus"},"answer":"A","answerText":"lava","modul":12,"moduleName":"Bumi, Tata Surya, dan Antariksa","difficulty":"Sedang","explain":"Magma yang mencapai permukaan disebut lava.","deepConcept":"Litosfer tersusun dari lempeng yang bergerak; zona subduksi muncul saat satu lempeng menunjam. Cuaca terutama berlangsung di troposfer; aktivitas geotermal terjadi akibat panas dari dalam Bumi.","conceptName":"bumi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q32","package":2,"number":32,"question":"Pada ketinggian dengan tekanan oksigen lebih rendah, salah satu adaptasi jangka panjang tubuh adalah ...","options":{"A":"menurunkan kemampuan darah membawa oksigen","B":"menghilangkan hemoglobin dari darah","C":"meningkatkan produksi eritrosit melalui mekanisme hormonal","D":"menghentikan pembentukan sel darah"},"answer":"C","answerText":"meningkatkan produksi eritrosit melalui mekanisme hormonal","modul":3,"moduleName":"Fisiologi Hewan","difficulty":"Sulit","explain":"Eritropoiesis meningkat sebagai respons hipoksia berkepanjangan.","deepConcept":"Pertukaran gas terjadi lewat difusi dari tekanan parsial tinggi ke rendah. Permukaan alveolus luas dan dinding tipis mempercepat difusi; peningkatan CO₂ memicu ventilasi sebagai mekanisme homeostasis.","conceptName":"napas","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q33","package":2,"number":33,"question":"Sinar datang membentuk sudut 40° terhadap permukaan cermin datar. Sudut pantul terhadap garis normal adalah ...","options":{"A":"80°","B":"40°","C":"50°","D":"90°"},"answer":"C","answerText":"50°","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sedang","explain":"Sudut terhadap normal =90°−40°=50°.","math":{"title":"Hukum pemantulan pada cermin datar","foundation":"Sudut datang dan sudut pantul selalu diukur terhadap garis normal (tegak lurus cermin). Hukum pemantulan: i = r. Jika sudut diberikan terhadap permukaan cermin, ubah menjadi i = 90° − sudut permukaan.","steps":["Garis normal selalu tegak lurus permukaan cermin.","Hukum pemantulan: sudut datang i sama dengan sudut pantul r, keduanya terhadap normal.","Sudut ke permukaan = 40°, maka sudut terhadap normal i = 90° − 40° = 50°.","Sudut pantul r = i (atau sudut datang i = r).","Hasil = 50°."],"symbol":"reflect"},"deepConcept":"Pada cermin datar, sudut datang sama dengan sudut pantul jika diukur dari garis normal. Pada cermin cembung, sinar pantul menyebar sehingga bidang pandang menjadi luas.","conceptName":"pantul","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Sudut 80° tidak sesuai dengan hukum pemantulan untuk sudut terhadap normal 50°. Hubungan sudut yang diminta menghasilkan 50°.","B":"Sudut 40° tidak sesuai dengan hukum pemantulan untuk sudut terhadap normal 50°. Hubungan sudut yang diminta menghasilkan 50°.","D":"Sudut 90° tidak sesuai dengan hukum pemantulan untuk sudut terhadap normal 50°. Hubungan sudut yang diminta menghasilkan 50°."}},{"id":"p2q34","package":2,"number":34,"question":"Gelombang pada tali merambat 12 m/s dengan frekuensi 3 Hz. Panjang gelombangnya adalah ...","options":{"A":"9 m","B":"36 m","C":"3 m","D":"4 m"},"answer":"D","answerText":"4 m","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sedang","explain":"λ=v/f=12/3=4 m.","math":{"title":"Hubungan panjang gelombang, frekuensi, dan cepat rambat","foundation":"Dalam satu periode T, gelombang menempuh satu panjang gelombang λ. Karena v = jarak/waktu = λ/T dan f=1/T, diperoleh v = fλ; bentuk lainnya f = v/λ dan λ = v/f.","steps":["Dalam satu periode, gelombang menempuh λ sehingga v = λ/T.","Karena f = 1/T, diperoleh v = fλ.","Ubah susunan: λ = v/f.","λ = 12/3 = 4 m."],"symbol":"wave"},"deepConcept":"Frekuensi menyatakan banyak siklus per detik; periode menyatakan durasi satu siklus, dengan f = 1/T. Kecepatan gelombang terhubung ke frekuensi dan panjang gelombang melalui v = fλ.","conceptName":"gelombang","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Panjang gelombang 9 m akan menghasilkan v = fλ = 27 m/s, bukan 12 m/s.","B":"Panjang gelombang 36 m akan menghasilkan v = fλ = 108 m/s, bukan 12 m/s.","C":"Panjang gelombang 3 m akan menghasilkan v = fλ = 9 m/s, bukan 12 m/s."}},{"id":"p2q35","package":2,"number":35,"question":"Anggrek menempel pada batang pohon tanpa mengambil sari makanan dari pohon. Hubungan yang paling sesuai adalah ...","options":{"A":"komensalisme","B":"predasi","C":"parasitisme wajib","D":"kompetisi langsung"},"answer":"A","answerText":"komensalisme","modul":13,"moduleName":"Ekologi dan Pelestarian Lingkungan","difficulty":"Sedang","explain":"Anggrek mendapat tempat sedangkan pohon umumnya tidak dirugikan.","deepConcept":"Mutualisme menguntungkan kedua pihak; komensalisme menguntungkan satu pihak tanpa dampak berarti pada pihak lain; parasitisme merugikan inang; predasi membunuh/memakan mangsa; kompetisi terjadi ketika organisme memperebutkan sumber terbatas.","conceptName":"interaksi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q36","package":2,"number":36,"question":"Benda 4 kg diangkat setinggi 5 m, g=10 m/s². Energi potensial gravitasi bertambah ...","options":{"A":"20 J","B":"200 J","C":"400 J","D":"40 J"},"answer":"B","answerText":"200 J","modul":11,"moduleName":"Bentuk Energi dan Perubahannya","difficulty":"Sulit","explain":"Ep=mgh=4×10×5=200 J.","math":{"title":"Asal rumus energi potensial gravitasi","foundation":"Untuk mengangkat benda perlahan melawan gravitasi dengan gaya F = mg sejauh tinggi h, usaha W = Fh = mgh. Energi yang tersimpan akibat ketinggian adalah Eₚ = mgh (g dianggap konstan).","steps":["Besar gaya berat W = mg.","Usaha menaikkan benda perlahan = gaya × perpindahan vertikal: Eₚ = W h = mgh.","Eₚ = 4 × 10 × 5 = 200 J."],"symbol":"potential"},"deepConcept":"Energi potensial gravitasi Eₚ = mgh terhadap acuan ketinggian. Bertambah linier terhadap massa dan kenaikan tinggi untuk medan gravitasi yang dianggap konstan.","conceptName":"potensial","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Energi 20 J akan membutuhkan tinggi h = E/(mg) = 0,5 m, bukan 5 m.","C":"Energi 400 J akan membutuhkan tinggi h = E/(mg) = 10 m, bukan 5 m.","D":"Energi 40 J akan membutuhkan tinggi h = E/(mg) = 1 m, bukan 5 m."}},{"id":"p2q37","package":2,"number":37,"question":"Pada sistem katrol ideal, beban 240 N ditopang empat segmen tali. Besar gaya tariknya adalah ...","options":{"A":"960 N","B":"30 N","C":"120 N","D":"60 N"},"answer":"D","answerText":"60 N","modul":6,"moduleName":"Mekanika","difficulty":"Sulit","explain":"F=240/4=60 N.","math":{"title":"Keuntungan mekanik katrol ideal","foundation":"Pada katrol ideal, tegangan tali sama di setiap ruas. Jika n ruas tali menopang beban W, maka nF = W. Ini menghemat gaya, tetapi jarak tali yang ditarik menjadi n kali kenaikan beban.","steps":["Jumlah ruas tali penopang beban = 4.","Tegangan pada setiap ruas = F, sehingga jumlah gaya penopang = nF.","Untuk beban setimbang: nF = W, lalu F = W/n.","F = 240/4 = 60 N."],"symbol":"pulley"},"deepConcept":"Gaya adalah besaran vektor; resultan harus mempertimbangkan arah. Benda bermassa m mengalami percepatan a menurut ΣF = ma. Gaya gesek yang melawan gerak dikurangkan dari gaya dorong.","conceptName":"gaya","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Jika setiap ruas menarik 960 N, total gaya penopang = 4×960 = 3.840 N, tidak sama dengan beban 240 N.","B":"Jika setiap ruas menarik 30 N, total gaya penopang = 4×30 = 120 N, tidak sama dengan beban 240 N.","C":"Jika setiap ruas menarik 120 N, total gaya penopang = 4×120 = 480 N, tidak sama dengan beban 240 N."}},{"id":"p2q38","package":2,"number":38,"question":"Enzim pepsin di lambung terutama berperan mencerna ...","options":{"A":"protein","B":"lemak menjadi gliserol saja","C":"vitamin","D":"selulosa"},"answer":"A","answerText":"protein","modul":3,"moduleName":"Fisiologi Hewan","difficulty":"Sedang","explain":"Pepsin adalah enzim protease lambung.","deepConcept":"Pencernaan memecah molekul besar agar dapat diserap. Amilase memecah pati, pepsin memecah protein, lipase memecah trigliserida; empedu bukan enzim, tetapi mengemulsikan lemak. Vili usus memperluas luas penyerapan.","conceptName":"pencernaan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q39","package":2,"number":39,"question":"Air memiliki ρ=1.000 kg/m³. Selisih tekanan pada dua titik dengan beda kedalaman 0,5 m (g=10 m/s²) adalah ...","options":{"A":"50.000 Pa","B":"10.000 Pa","C":"5.000 Pa","D":"500 Pa"},"answer":"C","answerText":"5.000 Pa","modul":7,"moduleName":"Wujud Benda dan Fluida","difficulty":"Sedang","explain":"Δp=ρgΔh=5.000 Pa.","math":{"title":"Penurunan tekanan hidrostatis","foundation":"Bayangkan kolom cairan berluas A dan tinggi h. Volumenya V = Ah, massanya m = ρAh, beratnya F = mg = ρAhg. Tekanan p = F/A sehingga p = ρgh. Untuk dua titik, Δp = ρgΔh.","steps":["Tekanan kolom cairan: p = F/A. Dengan F = mg = ρAhg, maka p = ρgh.","Karena yang ditanya selisih, gunakan Δp = ρgΔh; tekanan atmosfer yang sama di kedua titik saling meniadakan.","ρ = 1.000 kg/m³, g = 10 m/s², Δh = 0,5 m.","Δp = 1.000 × 10 × 0,5 = 5.000 Pa."],"symbol":"hydro"},"deepConcept":"Tekanan hidrostatis adalah tekanan akibat berat kolom fluida di atas titik. Tekanan bertambah jika massa jenis, percepatan gravitasi, atau kedalaman meningkat.","conceptName":"hidrostatis","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Tekanan 50.000 Pa mengharuskan beda kedalaman h = p/(ρg) = 5 m, bukan 0,5 m.","B":"Tekanan 10.000 Pa mengharuskan beda kedalaman h = p/(ρg) = 1 m, bukan 0,5 m.","D":"Tekanan 500 Pa mengharuskan beda kedalaman h = p/(ρg) = 0,05 m, bukan 0,5 m."}},{"id":"p2q40","package":2,"number":40,"question":"Keberadaan hutan mangrove, padang rumput, dan terumbu karang mencerminkan keanekaragaman tingkat ...","options":{"A":"gen dalam satu spesies","B":"ekosistem","C":"satu genotipe","D":"individu satu populasi"},"answer":"B","answerText":"ekosistem","modul":2,"moduleName":"Keanekaragaman dan Klasifikasi","difficulty":"Sedang","explain":"Ketiganya merupakan ekosistem berbeda.","deepConcept":"Keanekaragaman hayati dibedakan menjadi tingkat gen, spesies, dan ekosistem. Kekayaan spesies adalah banyaknya jenis; kemerataan memperhatikan perbandingan jumlah individu tiap jenis.","conceptName":"keanekaragaman","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q41","package":2,"number":41,"question":"Dua resistor 4 Ω dan 4 Ω disusun paralel. Hambatan total adalah ...","options":{"A":"16 Ω","B":"2 Ω","C":"4 Ω","D":"8 Ω"},"answer":"B","answerText":"2 Ω","modul":8,"moduleName":"Listrik dan Magnet","difficulty":"Sulit","explain":"Dua hambatan sama besar secara paralel menjadi setengah.","math":{"title":"Mengapa rumus paralel berupa kebalikan?","foundation":"Tegangan V sama pada setiap cabang paralel; arus total adalah penjumlahan arus cabang: I = V/R₁+V/R₂. Karena I=V/R total, pembagian dengan V menghasilkan 1/R total = 1/R₁+1/R₂.","steps":["Tegangan pada setiap cabang paralel sama, sedangkan arus total adalah jumlah arus cabang.","Karena I total = Σ(V/Rᵢ) = V/R total, maka 1/R total = Σ(1/Rᵢ).","Untuk dua resistor, R total = (R₁ × R₂)/(R₁ + R₂) = (4 × 4)/(4 + 4) = 2 Ω."],"symbol":"parallel"},"deepConcept":"Rangkaian seri memiliki arus yang sama dan tegangan terbagi, sehingga R total dijumlahkan. Rangkaian paralel memiliki tegangan yang sama dan arus terbagi, sehingga kebalikan hambatan dijumlahkan.","conceptName":"rangkaian","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Hambatan 16 Ω berbeda dari (R₁R₂)/(R₁+R₂) = 2 Ω; hambatan paralel juga harus lebih kecil daripada setiap cabang.","C":"Hambatan 4 Ω berbeda dari (R₁R₂)/(R₁+R₂) = 2 Ω; hambatan paralel juga harus lebih kecil daripada setiap cabang.","D":"Hambatan 8 Ω berbeda dari (R₁R₂)/(R₁+R₂) = 2 Ω; hambatan paralel juga harus lebih kecil daripada setiap cabang."}},{"id":"p2q42","package":2,"number":42,"question":"Sebuah balok bermassa 0,8 kg bervolume 1.000 cm³. Massa jenisnya adalah ...","options":{"A":"800 kg/m³","B":"80 kg/m³","C":"1.000 kg/m³","D":"8.000 kg/m³"},"answer":"A","answerText":"800 kg/m³","modul":7,"moduleName":"Wujud Benda dan Fluida","difficulty":"Sedang","explain":"1.000 cm³=0,001 m³; 0,8/0,001=800.","math":{"title":"Definisi massa jenis","foundation":"Massa jenis menyatakan berapa massa yang terdapat dalam setiap satuan volume: ρ = m/V. Satuan harus konsisten: 1.000 cm³ = 0,001 m³ dan 1 g/cm³ = 1.000 kg/m³.","steps":["Dari definisi, massa jenis ρ = massa/volume = m/V.","Ubah volume: 1.000 cm³ × (1 m³/1.000.000 cm³) = 0,001 m³.","Gunakan satuan konsisten: m = 0,8 kg; V = 0,001 m³.","ρ = 0,8/0,001 = 800 kg/m³."],"symbol":"density"},"deepConcept":"Massa jenis ρ = m/V; benda bebas dalam fluida yang massa jenisnya lebih kecil dari benda cenderung tenggelam, sebaliknya dapat terapung. Untuk benda terapung, gaya apung mengimbangi berat benda.","conceptName":"massa","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"B":"Jika massa jenis 80 kg/m³, massa yang sesuai pada volume soal menjadi m = ρV = 0,08 kg, sedangkan massa benda sebenarnya 0,8.","C":"Jika massa jenis 1.000 kg/m³, massa yang sesuai pada volume soal menjadi m = ρV = 1 kg, sedangkan massa benda sebenarnya 0,8.","D":"Jika massa jenis 8.000 kg/m³, massa yang sesuai pada volume soal menjadi m = ρV = 8 kg, sedangkan massa benda sebenarnya 0,8."}},{"id":"p2q43","package":2,"number":43,"question":"Fragmentasi hutan oleh jalan dapat meningkatkan risiko ...","options":{"A":"semua hewan berpindah tanpa hambatan","B":"hilangnya seluruh gangguan manusia","C":"bertambahnya luas hutan inti secara otomatis","D":"isolasi populasi satwa dan terputusnya koridor migrasi"},"answer":"D","answerText":"isolasi populasi satwa dan terputusnya koridor migrasi","modul":13,"moduleName":"Ekologi dan Pelestarian Lingkungan","difficulty":"Sulit","explain":"Jalan membatasi konektivitas habitat.","deepConcept":"Konservasi in situ melindungi spesies di habitat aslinya, sementara ex situ menjaga populasi atau plasma nutfah di luar habitat. Gangguan dan fragmentasi habitat dapat mengurangi keterhubungan populasi asli.","conceptName":"konservasi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q44","package":2,"number":44,"question":"Rantai makanan fitoplankton → zooplankton → ikan kecil → ikan besar memiliki produsen ...","options":{"A":"fitoplankton","B":"zooplankton","C":"ikan besar","D":"ikan kecil"},"answer":"A","answerText":"fitoplankton","modul":13,"moduleName":"Ekologi dan Pelestarian Lingkungan","difficulty":"Sedang","explain":"Fitoplankton melakukan fotosintesis.","deepConcept":"Dalam rantai makanan, produsen membentuk bahan organik melalui fotosintesis, konsumen I memakan produsen, konsumen II memakan konsumen I, dan pengurai mendaur ulang unsur hara.","conceptName":"rantai","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q45","package":2,"number":45,"question":"Mangifera indica dan Mangifera odorata sama-sama memiliki nama awal Mangifera. Keduanya berada pada ...","options":{"A":"famili yang berbeda secara pasti","B":"spesies yang sama","C":"genus yang sama","D":"kingdom yang berbeda"},"answer":"C","answerText":"genus yang sama","modul":2,"moduleName":"Keanekaragaman dan Klasifikasi","difficulty":"Mudah","explain":"Kata pertama nama ilmiah adalah genus.","deepConcept":"Urutan takson dari luas ke sempit ialah kingdom–filum–kelas–ordo–famili–genus–spesies. Makin dekat nenek moyang bersama suatu pasangan organisme, makin dekat pula hubungan evolusionernya.","conceptName":"taksonomi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q46","package":2,"number":46,"question":"Akar kecambah umumnya tumbuh menuju pusat bumi. Fenomena ini adalah ...","options":{"A":"niktinasti","B":"fototropisme positif","C":"tigmotropisme negatif","D":"gravitropisme positif"},"answer":"D","answerText":"gravitropisme positif","modul":4,"moduleName":"Fisiologi Tumbuhan","difficulty":"Sedang","explain":"Arah tumbuh dipengaruhi gravitasi.","deepConcept":"Tropisme adalah respons pertumbuhan yang arahnya bergantung arah rangsangan. Respons positif tumbuh mendekati rangsangan; respons negatif menjauhinya. Cahaya, air, gravitasi, dan sentuhan memunculkan jenis tropisme berbeda.","conceptName":"tropisme","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q47","package":2,"number":47,"question":"Filter berpori halus pada pengolahan air bekerja terutama berdasarkan ...","options":{"A":"perubahan massa jenis gravitasi semua molekul menjadi nol","B":"peningkatan radioaktivitas polutan","C":"pemisahan partikel menurut ukuran","D":"penciptaan air baru"},"answer":"C","answerText":"pemisahan partikel menurut ukuran","modul":14,"moduleName":"Kesehatan, Lingkungan, dan Teknologi","difficulty":"Sulit","explain":"Filtrasi menyaring partikel sesuai ukuran pori.","deepConcept":"Teknologi lingkungan bekerja melalui proses fisika (filtrasi), biologi (bioremediasi/digesti anaerob), dan pengendalian sumber. Pencegahan di sumber umumnya mengurangi beban pengolahan hilir.","conceptName":"lingkungan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q48","package":2,"number":48,"question":"Air dalam panci yang dipanaskan mengalami aliran naik-turun karena perbedaan massa jenis. Proses itu adalah ...","options":{"A":"konduksi murni tanpa aliran","B":"deposisi","C":"radiasi saja","D":"konveksi"},"answer":"D","answerText":"konveksi","modul":10,"moduleName":"Suhu dan Kalor","difficulty":"Sedang","explain":"Konveksi melibatkan pergerakan massa fluida.","deepConcept":"Kalor adalah energi yang berpindah karena beda suhu. Saat tidak terjadi perubahan wujud, Q = mcΔT; makin besar massa, kalor jenis, atau selisih suhu, makin besar energi yang diperlukan.","conceptName":"kalor","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q49","package":2,"number":49,"question":"Proses yang menghasilkan sel kelamin dengan jumlah kromosom setengah sel induk disebut ...","options":{"A":"mitosis","B":"osmosis","C":"difusi","D":"meiosis"},"answer":"D","answerText":"meiosis","modul":5,"moduleName":"Sistem Organ, Sel, dan Genetika","difficulty":"Sedang","explain":"Meiosis merupakan pembelahan reduksi.","deepConcept":"Mitosis menghasilkan sel anak dengan jumlah kromosom umumnya sama, sedangkan meiosis mengurangi jumlah kromosom menjadi separuh. Sebelum pembelahan, DNA direplikasi pada fase S; kromosom sejajar pada metafase dan kromatid saudara berpisah pada anafase mitosis.","conceptName":"pembelahan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p2q50","package":2,"number":50,"question":"Planet yang lebih dekat ke Matahari secara umum memiliki periode revolusi lebih ...","options":{"A":"tidak terukur","B":"sama persis dengan planet jauh","C":"singkat","D":"panjang untuk semua planet"},"answer":"C","answerText":"singkat","modul":12,"moduleName":"Bumi, Tata Surya, dan Antariksa","difficulty":"Sulit","explain":"Hukum Kepler III mengaitkan orbit lebih kecil dengan periode lebih singkat.","deepConcept":"Rotasi Bumi menghasilkan siang–malam; revolusi Bumi bersama kemiringan sumbu rotasi menghasilkan musim. Orbit planet dan fase Bulan berbeda dari rotasi Bumi.","conceptName":"orbit","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q1","package":3,"number":1,"question":"Pada uji jenis pupuk A dan B, volume air dijaga sama. Fungsi pengaturan volume air tersebut adalah ...","options":{"A":"menggantikan pengukuran tinggi tanaman","B":"menentukan hasil sejak awal","C":"mengendalikan variabel lain","D":"meningkatkan jumlah sampel secara otomatis"},"answer":"C","answerText":"mengendalikan variabel lain","modul":1,"moduleName":"Keterampilan dan Metode Ilmiah","difficulty":"Sedang","explain":"Volume air dibuat konstan untuk mengisolasi pengaruh pupuk.","deepConcept":"Variabel bebas adalah faktor yang sengaja diubah; variabel terikat adalah hasil yang diukur; variabel kontrol adalah faktor lain yang dibuat tetap. Perbandingan bermakna jika perlakuan berbeda pada satu faktor utama saja.","conceptName":"variabel","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q2","package":3,"number":2,"question":"Gelombang berfrekuensi 4 Hz memiliki periode ...","options":{"A":"0,4 s","B":"4 s","C":"0,25 s","D":"16 s"},"answer":"C","answerText":"0,25 s","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sedang","explain":"T=1/f=0,25 s.","math":{"title":"Frekuensi dan periode dari definisi","foundation":"Frekuensi f adalah banyaknya getaran n dalam waktu t, maka f = n/t. Periode T adalah waktu satu getaran, sehingga T = t/n = 1/f. Satuan f = hertz (Hz), T = detik (s).","steps":["Frekuensi adalah getaran per detik: f = n/t.","Periode adalah detik per getaran: T = t/n = 1/f.","Diketahui f = 4 Hz. Maka T = 1/4 = 0,25 s."],"symbol":"frequency"},"deepConcept":"Frekuensi menyatakan banyak siklus per detik; periode menyatakan durasi satu siklus, dengan f = 1/T. Kecepatan gelombang terhubung ke frekuensi dan panjang gelombang melalui v = fλ.","conceptName":"gelombang","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Periode 0,4 s akan menghasilkan frekuensi 1/T = 2,5 Hz, bukan frekuensi 4 Hz dalam soal.","B":"Periode 4 s akan menghasilkan frekuensi 1/T = 0,25 Hz, bukan frekuensi 4 Hz dalam soal.","D":"Periode 16 s akan menghasilkan frekuensi 1/T = 0,0625 Hz, bukan frekuensi 4 Hz dalam soal."}},{"id":"p3q3","package":3,"number":3,"question":"Pada hari terik dan kering, stomata menutup untuk menghemat air. Konsekuensi langsungnya adalah ...","options":{"A":"xilem langsung berubah menjadi floem","B":"seluruh klorofil hilang seketika","C":"masuknya CO2 untuk fotosintesis dapat berkurang","D":"CO2 selalu masuk lebih banyak"},"answer":"C","answerText":"masuknya CO2 untuk fotosintesis dapat berkurang","modul":4,"moduleName":"Fisiologi Tumbuhan","difficulty":"Sedang","explain":"Stomata yang menutup membatasi difusi CO2.","deepConcept":"Xilem mengalirkan air/mineral dari akar; floem mentranslokasikan gula dari bagian sumber ke bagian pemakai/penyimpan. Sel penjaga mengubah turgor untuk membuka atau menutup stomata.","conceptName":"transport","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q4","package":3,"number":4,"question":"Rotasi Bumi merupakan penyebab utama ...","options":{"A":"pergantian musim tahunan secara mandiri","B":"gerhana Bulan setiap malam","C":"perubahan massa Bumi harian","D":"pergantian siang dan malam"},"answer":"D","answerText":"pergantian siang dan malam","modul":12,"moduleName":"Bumi, Tata Surya, dan Antariksa","difficulty":"Sulit","explain":"Perputaran Bumi membuat wilayah bergantian menghadap Matahari.","deepConcept":"Rotasi Bumi menghasilkan siang–malam; revolusi Bumi bersama kemiringan sumbu rotasi menghasilkan musim. Orbit planet dan fase Bulan berbeda dari rotasi Bumi.","conceptName":"orbit","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q5","package":3,"number":5,"question":"Panel surya pada instalasi air bersih terutama mengubah ...","options":{"A":"energi inti bumi menjadi gelombang suara","B":"energi bunyi menjadi klorofil","C":"energi kimia plastik menjadi gravitasi","D":"energi cahaya menjadi listrik untuk menggerakkan pompa"},"answer":"D","answerText":"energi cahaya menjadi listrik untuk menggerakkan pompa","modul":14,"moduleName":"Kesehatan, Lingkungan, dan Teknologi","difficulty":"Sulit","explain":"Sel fotovoltaik mengonversi cahaya ke listrik.","deepConcept":"Sel fotovoltaik mengubah sebagian energi cahaya yang diserap menjadi energi listrik. Motor listrik pompa kemudian mengubah energi listrik menjadi energi mekanik untuk mengangkat atau memindahkan air. Tiap tahap memiliki efisiensi kurang dari 100% pada sistem nyata.","conceptName":"konversi energi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q6","package":3,"number":6,"question":"Darah dari seluruh tubuh kembali ke jantung melalui ...","options":{"A":"arteri koroner","B":"vena kava","C":"aorta","D":"vena pulmonalis saja"},"answer":"B","answerText":"vena kava","modul":3,"moduleName":"Fisiologi Hewan","difficulty":"Mudah","explain":"Vena kava membawa darah sistemik ke serambi kanan.","deepConcept":"Aliran darah sistemik: bilik kiri → aorta → jaringan → vena kava → serambi kanan. Aliran pulmonal: bilik kanan → arteri pulmonalis → paru-paru → vena pulmonalis → serambi kiri. Katup menjaga aliran satu arah.","conceptName":"peredaran","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q7","package":3,"number":7,"question":"Siswa ingin membandingkan kualitas air dua sungai. Pemilihan sampel paling representatif adalah ...","options":{"A":"mengambil sampel beberapa titik dan waktu dengan prosedur seragam","B":"memilih sampel dari satu tepi sungai saja","C":"memanaskan seluruh sampel sebelum diuji tanpa alasan","D":"mengambil hanya sampel paling jernih"},"answer":"A","answerText":"mengambil sampel beberapa titik dan waktu dengan prosedur seragam","modul":1,"moduleName":"Keterampilan dan Metode Ilmiah","difficulty":"Sulit","explain":"Replikasi spasial dan temporal meningkatkan representativitas.","deepConcept":"Sampel representatif menangkap variasi lokasi dan waktu. Replikasi memberikan gambaran variasi alami dan mengurangi pengaruh pengamatan yang kebetulan ekstrem.","conceptName":"sampel","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q8","package":3,"number":8,"question":"Jika permukaan alveolus rusak luas, akibat fisiologis utamanya adalah ...","options":{"A":"darah langsung berubah menjadi getah bening","B":"efisiensi pertukaran gas menurun","C":"enzim amilase menjadi tidak aktif","D":"penyerapan makanan meningkat"},"answer":"B","answerText":"efisiensi pertukaran gas menurun","modul":3,"moduleName":"Fisiologi Hewan","difficulty":"Sulit","explain":"Luas permukaan difusi gas menjadi berkurang.","deepConcept":"Pertukaran gas terjadi lewat difusi dari tekanan parsial tinggi ke rendah. Permukaan alveolus luas dan dinding tipis mempercepat difusi; peningkatan CO₂ memicu ventilasi sebagai mekanisme homeostasis.","conceptName":"napas","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q9","package":3,"number":9,"question":"Alat mengonsumsi energi 1.000 J, dengan keluaran berguna 400 J. Efisiensinya ...","options":{"A":"40%","B":"60%","C":"4%","D":"250%"},"answer":"A","answerText":"40%","modul":11,"moduleName":"Bentuk Energi dan Perubahannya","difficulty":"Sedang","explain":"Efisiensi=400/1.000×100%=40%.","math":{"title":"Efisiensi dari konservasi energi","foundation":"Energi masuk tidak seluruhnya berubah menjadi keluaran yang diinginkan. Secara definisi, efisiensi η = (E berguna/E masuk)×100%. Pada alat biasa, sisanya terbuang sebagai kalor, suara, dll.","steps":["Efisiensi adalah proporsi energi masuk yang benar-benar menjadi energi berguna.","Dari definisi bagian = keluaran/masukan, sehingga η = E berguna/E masuk × 100%.","η = (400/1.000) × 100% = 40%.","Energi yang tidak menjadi keluaran berguna = 600 J (misalnya terdisipasi sebagai kalor)."],"symbol":"efficiency"},"deepConcept":"Energi tidak diciptakan dari ketiadaan. Efisiensi adalah persentase energi masuk yang menjadi keluaran berguna; tidak mengukur energi yang “hilang”, tetapi energi yang berpindah ke bentuk tak diinginkan.","conceptName":"energi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"B":"Efisiensi 60% menyatakan energi berguna 600 J dari masukan 1.000 J, padahal keluaran soal 400 J.","C":"Efisiensi 4% menyatakan energi berguna 40 J dari masukan 1.000 J, padahal keluaran soal 400 J.","D":"Efisiensi 250% menyatakan energi berguna 2.500 J dari masukan 1.000 J, padahal keluaran soal 400 J."}},{"id":"p3q10","package":3,"number":10,"question":"Kotak bermassa 4 kg mendapat gaya 28 N ke kanan dan gesekan 12 N ke kiri. Percepatannya adalah ...","options":{"A":"7 m/s²","B":"4 m/s²","C":"3 m/s²","D":"10 m/s²"},"answer":"B","answerText":"4 m/s²","modul":6,"moduleName":"Mekanika","difficulty":"Sedang","explain":"a=(28−12)/4=4 m/s².","math":{"title":"Hukum II Newton dan resultan gaya","foundation":"Hukum II Newton menyatakan ΣF = m a. Gaya berlawanan arah diberi tanda berlawanan sehingga ΣF = F dorong − F gesek; akibatnya a = ΣF/m.","steps":["Pilih arah dorong/tarik sebagai arah positif.","Dari Hukum II Newton: ΣF = ma, sehingga a = ΣF/m.","Gaya bersih ΣF = 28 − 12 = 16 N.","a = 16/4 = 4 m/s²."],"symbol":"newton"},"deepConcept":"Gaya adalah besaran vektor; resultan harus mempertimbangkan arah. Benda bermassa m mengalami percepatan a menurut ΣF = ma. Gaya gesek yang melawan gerak dikurangkan dari gaya dorong.","conceptName":"gaya","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Jika percepatan 7 m/s², gaya bersih yang dibutuhkan m×a = 4×7 = 28 N, padahal soal menetapkan gaya bersih 16 N.","C":"Jika percepatan 3 m/s², gaya bersih yang dibutuhkan m×a = 4×3 = 12 N, padahal soal menetapkan gaya bersih 16 N.","D":"Jika percepatan 10 m/s², gaya bersih yang dibutuhkan m×a = 4×10 = 40 N, padahal soal menetapkan gaya bersih 16 N."}},{"id":"p3q11","package":3,"number":11,"question":"Anak berlari sejauh 150 m dalam 30 detik. Kelajuan rata-ratanya adalah ...","options":{"A":"15 m/s","B":"3 m/s","C":"10 m/s","D":"5 m/s"},"answer":"D","answerText":"5 m/s","modul":6,"moduleName":"Mekanika","difficulty":"Sedang","explain":"Kelajuan = 150/30 = 5 m/s.","math":{"title":"Kelajuan dari definisi gerak","foundation":"Kelajuan rata-rata didefinisikan sebagai total jarak dibagi total waktu: v = s/t. Jika jarak dan waktu memakai satuan yang tidak cocok, konversikan terlebih dahulu.","steps":["Besaran diketahui: jarak s = 150 m; waktu t = 30 s.","Definisi kelajuan rata-rata: v = s/t.","Satuan jarak dan waktu sudah sepadan.","v = 150/30 = 5 m/s."],"symbol":"speed"},"deepConcept":"Kelajuan rata-rata memakai jarak tempuh total dibagi durasi total. Untuk memperoleh m/s, pakai meter dan detik; 1 km = 1.000 m dan 1 menit = 60 detik.","conceptName":"kelajuan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Nilai 15 m/s tidak sama dengan s/t = 150/30 = 5 m/s untuk data pada soal.","B":"Nilai 3 m/s tidak sama dengan s/t = 150/30 = 5 m/s untuk data pada soal.","C":"Nilai 10 m/s tidak sama dengan s/t = 150/30 = 5 m/s untuk data pada soal."}},{"id":"p3q12","package":3,"number":12,"question":"Sinar datang membentuk sudut 25° terhadap normal. Sudut antara sinar datang dan sinar pantul adalah ...","options":{"A":"25°","B":"65°","C":"50°","D":"90°"},"answer":"C","answerText":"50°","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sedang","explain":"Kedua sudut terhadap normal 25° sehingga total 50°.","math":{"title":"Hukum pemantulan pada cermin datar","foundation":"Sudut datang dan sudut pantul selalu diukur terhadap garis normal (tegak lurus cermin). Hukum pemantulan: i = r. Jika sudut diberikan terhadap permukaan cermin, ubah menjadi i = 90° − sudut permukaan.","steps":["Garis normal selalu tegak lurus permukaan cermin.","Hukum pemantulan: sudut datang i sama dengan sudut pantul r, keduanya terhadap normal.","Sudut antara sinar datang dan sinar pantul = i + r = 2i.","Hasil = 50°."],"symbol":"reflect"},"deepConcept":"Pada cermin datar, sudut datang sama dengan sudut pantul jika diukur dari garis normal. Pada cermin cembung, sinar pantul menyebar sehingga bidang pandang menjadi luas.","conceptName":"pantul","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Sudut 25° tidak sesuai dengan hukum pemantulan untuk sudut terhadap normal 25°. Hubungan sudut yang diminta menghasilkan 50°.","B":"Sudut 65° tidak sesuai dengan hukum pemantulan untuk sudut terhadap normal 25°. Hubungan sudut yang diminta menghasilkan 50°.","D":"Sudut 90° tidak sesuai dengan hukum pemantulan untuk sudut terhadap normal 25°. Hubungan sudut yang diminta menghasilkan 50°."}},{"id":"p3q13","package":3,"number":13,"question":"Lapisan atmosfer tempat berlangsungnya sebagian besar cuaca adalah ...","options":{"A":"stratosfer bagian atas","B":"termosfer","C":"eksosfer","D":"troposfer"},"answer":"D","answerText":"troposfer","modul":12,"moduleName":"Bumi, Tata Surya, dan Antariksa","difficulty":"Sedang","explain":"Cuaca terjadi terutama di troposfer.","deepConcept":"Litosfer tersusun dari lempeng yang bergerak; zona subduksi muncul saat satu lempeng menunjam. Cuaca terutama berlangsung di troposfer; aktivitas geotermal terjadi akibat panas dari dalam Bumi.","conceptName":"bumi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q14","package":3,"number":14,"question":"Dalam urutan kingdom, filum, kelas, ordo, famili, genus, spesies, tingkatan paling khusus adalah ...","options":{"A":"kelas","B":"filum","C":"kingdom","D":"spesies"},"answer":"D","answerText":"spesies","modul":2,"moduleName":"Keanekaragaman dan Klasifikasi","difficulty":"Mudah","explain":"Spesies merupakan unit klasifikasi paling khusus dalam daftar ini.","deepConcept":"Urutan takson dari luas ke sempit ialah kingdom–filum–kelas–ordo–famili–genus–spesies. Makin dekat nenek moyang bersama suatu pasangan organisme, makin dekat pula hubungan evolusionernya.","conceptName":"taksonomi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q15","package":3,"number":15,"question":"Tanaman tinggi (T) dominan terhadap pendek (t). Persilangan TT × tt menghasilkan fenotipe keturunan F1 ...","options":{"A":"100% pendek","B":"25% tinggi","C":"100% tinggi","D":"50% tinggi"},"answer":"C","answerText":"100% tinggi","modul":5,"moduleName":"Sistem Organ, Sel, dan Genetika","difficulty":"Sedang","explain":"Seluruh F1 genotip Tt sehingga tinggi.","math":{"title":"Menurunkan peluang dengan kotak Punnett","foundation":"Tiap induk menurunkan satu alel dalam gamet. Daftar semua gamet kedua induk, gabungkan semua pasangan yang sama mungkin, lalu hitung jumlah genotipe/fenotipe sesuai pertanyaan dibagi semua kombinasi.","steps":["Hukum segregasi Mendel: setiap gamet membawa satu dari dua alel induk.","Gamet induk pertama (TT): T dan T; gamet induk kedua (tt): t dan t.","Empat kotak Punnett yang sama peluangnya: Tt, Tt, Tt, Tt.","Keturunan yang memenuhi target = 4 dari 4 kemungkinan → 4/4 × 100% = 100%.","Seluruh keturunan memiliki alel dominan T → semuanya berfenotipe tinggi."],"symbol":"genetics"},"deepConcept":"Pada dominansi lengkap, alel dominan muncul pada genotipe heterozigot; fenotipe resesif membutuhkan dua alel resesif. Rasio dihitung dari probabilitas gamet dan kotak Punnett, bukan menebak dari tampilan induk.","conceptName":"genetika","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Peluang tersebut tidak sesuai dengan menghitung semua kombinasi gamet pada kotak Punnett. Seluruh keturunan memiliki alel dominan T → semuanya berfenotipe tinggi.","B":"Peluang tersebut tidak sesuai dengan menghitung semua kombinasi gamet pada kotak Punnett. Seluruh keturunan memiliki alel dominan T → semuanya berfenotipe tinggi.","D":"Peluang tersebut tidak sesuai dengan menghitung semua kombinasi gamet pada kotak Punnett. Seluruh keturunan memiliki alel dominan T → semuanya berfenotipe tinggi."}},{"id":"p3q16","package":3,"number":16,"question":"Untuk menjaga keberlanjutan stok ikan, kebijakan penting adalah ...","options":{"A":"mematikan seluruh daerah pemijahan","B":"mengatur jumlah dan ukuran tangkapan sesuai daya pulih populasi","C":"membuang alat tangkap ke laut","D":"menangkap seluruh induk saat bertelur"},"answer":"B","answerText":"mengatur jumlah dan ukuran tangkapan sesuai daya pulih populasi","modul":13,"moduleName":"Ekologi dan Pelestarian Lingkungan","difficulty":"Sedang","explain":"Pemanfaatan berkelanjutan mempertahankan reproduksi.","deepConcept":"Konservasi in situ melindungi spesies di habitat aslinya, sementara ex situ menjaga populasi atau plasma nutfah di luar habitat. Gangguan dan fragmentasi habitat dapat mengurangi keterhubungan populasi asli.","conceptName":"konservasi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q17","package":3,"number":17,"question":"Dalam pohon filogenetik, spesies A dan B berbagi nenek moyang yang lebih baru daripada A dan C. Hubungan yang tepat adalah ...","options":{"A":"B adalah nenek moyang langsung A","B":"A tidak berkerabat dengan C","C":"A dan C pasti satu spesies","D":"A lebih dekat kekerabatannya dengan B"},"answer":"D","answerText":"A lebih dekat kekerabatannya dengan B","modul":2,"moduleName":"Keanekaragaman dan Klasifikasi","difficulty":"Sulit","explain":"Nenek moyang bersama yang lebih baru menandakan kekerabatan lebih dekat.","deepConcept":"Keanekaragaman genetik terjadi dalam satu spesies akibat kombinasi alel yang berbeda. Perbedaan gen tidak otomatis berarti spesies baru; pemisahan spesies membutuhkan bukti biologis dan evolusioner yang memadai.","conceptName":"genetik","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q18","package":3,"number":18,"question":"Piston kecil luasnya 4 cm² dan piston besar 80 cm². Untuk mengangkat beban 400 N, gaya minimal pada piston kecil adalah ...","options":{"A":"40 N","B":"20 N","C":"80 N","D":"4 N"},"answer":"B","answerText":"20 N","modul":7,"moduleName":"Wujud Benda dan Fluida","difficulty":"Sulit","explain":"F1=400×4/80=20 N.","math":{"title":"Penurunan hukum Pascal","foundation":"Dalam fluida tertutup yang ideal, tambahan tekanan diteruskan sama besar: p₁ = p₂. Karena p = F/A, diperoleh F₁/A₁ = F₂/A₂. Piston berluas lebih besar menghasilkan gaya lebih besar.","steps":["Tekanan sama: F₁/A₁ = F₂/A₂.","Susun ulang sesuai gaya yang dicari: F₂ = F₁ × (A₂/A₁), atau F₁ = F₂ × (A₁/A₂).","F₁ = 400 × (4/80) = 20 N.","Perbandingan luas bebas satuan karena pembilang dan penyebut memakai cm² yang sama."],"symbol":"pascal"},"deepConcept":"Hukum Pascal menghubungkan kenaikan tekanan yang sama dalam fluida tertutup. Karena p = F/A, perbandingan gaya piston sebanding perbandingan luasnya; hasil ideal mengabaikan gesekan.","conceptName":"hidrolik","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Gaya masuk 40 N memberi tekanan F₁/A₁ = 10 N/cm², berbeda dari tekanan yang diperlukan F₂/A₂ = 5 N/cm².","C":"Gaya masuk 80 N memberi tekanan F₁/A₁ = 20 N/cm², berbeda dari tekanan yang diperlukan F₂/A₂ = 5 N/cm².","D":"Gaya masuk 4 N memberi tekanan F₁/A₁ = 1 N/cm², berbeda dari tekanan yang diperlukan F₂/A₂ = 5 N/cm²."}},{"id":"p3q19","package":3,"number":19,"question":"Pemanfaatan mikroorganisme untuk menguraikan polutan di lingkungan disebut ...","options":{"A":"ekstraksi minyak bumi","B":"destilasi fraksionasi","C":"fotosintesis buatan tanpa organisme","D":"bioremediasi"},"answer":"D","answerText":"bioremediasi","modul":14,"moduleName":"Kesehatan, Lingkungan, dan Teknologi","difficulty":"Sedang","explain":"Bioremediasi menggunakan aktivitas biologis membersihkan cemaran.","deepConcept":"Teknologi lingkungan bekerja melalui proses fisika (filtrasi), biologi (bioremediasi/digesti anaerob), dan pengendalian sumber. Pencegahan di sumber umumnya mengurangi beban pengolahan hilir.","conceptName":"lingkungan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q20","package":3,"number":20,"question":"Sintesis protein berlangsung pada ...","options":{"A":"ribosom","B":"vakuola saja","C":"dinding sel","D":"membran nukleus tanpa ribosom"},"answer":"A","answerText":"ribosom","modul":5,"moduleName":"Sistem Organ, Sel, dan Genetika","difficulty":"Mudah","explain":"Ribosom menerjemahkan mRNA menjadi polipeptida.","deepConcept":"Kloroplas menangkap energi cahaya; mitokondria menghasilkan banyak ATP melalui respirasi aerob; ribosom menyusun protein; badan Golgi memodifikasi dan mengemas produk. DNA sel eukariotik sebagian besar berada di nukleus, sedangkan bakteri memiliki nukleoid.","conceptName":"organel","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q21","package":3,"number":21,"question":"Ketika arah arus pada kumparan elektromagnet dibalik, arah kutub elektromagnet umumnya ...","options":{"A":"tetap selalu sama","B":"bertukar","C":"berubah menjadi kutub listrik","D":"menghilang secara permanen"},"answer":"B","answerText":"bertukar","modul":8,"moduleName":"Listrik dan Magnet","difficulty":"Sedang","explain":"Polaritas elektromagnet bergantung arah arus.","deepConcept":"Hukum Ohm V = IR memberi hubungan antara beda potensial, arus, dan hambatan untuk resistor ohmik. Ampere adalah satuan arus, volt satuan beda potensial, dan ohm satuan hambatan.","conceptName":"ohm","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q22","package":3,"number":22,"question":"Pada katrol bergerak ideal yang ditopang dua segmen tali, beban 160 N diangkat dengan gaya ...","options":{"A":"160 N","B":"320 N","C":"80 N","D":"40 N"},"answer":"C","answerText":"80 N","modul":6,"moduleName":"Mekanika","difficulty":"Sulit","explain":"Gaya ideal setengah berat beban.","math":{"title":"Keuntungan mekanik katrol ideal","foundation":"Pada katrol ideal, tegangan tali sama di setiap ruas. Jika n ruas tali menopang beban W, maka nF = W. Ini menghemat gaya, tetapi jarak tali yang ditarik menjadi n kali kenaikan beban.","steps":["Jumlah ruas tali penopang beban = 2.","Tegangan pada setiap ruas = F, sehingga jumlah gaya penopang = nF.","Untuk beban setimbang: nF = W, lalu F = W/n.","F = 160/2 = 80 N."],"symbol":"pulley"},"deepConcept":"Gaya adalah besaran vektor; resultan harus mempertimbangkan arah. Benda bermassa m mengalami percepatan a menurut ΣF = ma. Gaya gesek yang melawan gerak dikurangkan dari gaya dorong.","conceptName":"gaya","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Jika setiap ruas menarik 160 N, total gaya penopang = 2×160 = 320 N, tidak sama dengan beban 160 N.","B":"Jika setiap ruas menarik 320 N, total gaya penopang = 2×320 = 640 N, tidak sama dengan beban 160 N.","D":"Jika setiap ruas menarik 40 N, total gaya penopang = 2×40 = 80 N, tidak sama dengan beban 160 N."}},{"id":"p3q23","package":3,"number":23,"question":"Dalam rantai padi → tikus → ular → elang, ular menempati tingkat ...","options":{"A":"konsumen II","B":"pengurai","C":"konsumen I","D":"produsen"},"answer":"A","answerText":"konsumen II","modul":13,"moduleName":"Ekologi dan Pelestarian Lingkungan","difficulty":"Sedang","explain":"Tikus konsumen I dan ular konsumen II.","deepConcept":"Dalam rantai makanan, produsen membentuk bahan organik melalui fotosintesis, konsumen I memakan produsen, konsumen II memakan konsumen I, dan pengurai mendaur ulang unsur hara.","conceptName":"rantai","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q24","package":3,"number":24,"question":"Sulur mentimun melilit penyangga setelah menyentuhnya. Respons tumbuh itu disebut ...","options":{"A":"kemotaksis","B":"tigmotropisme","C":"fototropisme negatif","D":"termoregulasi"},"answer":"B","answerText":"tigmotropisme","modul":4,"moduleName":"Fisiologi Tumbuhan","difficulty":"Sedang","explain":"Tigmotropisme dipicu kontak mekanik.","deepConcept":"Tropisme adalah respons pertumbuhan yang arahnya bergantung arah rangsangan. Respons positif tumbuh mendekati rangsangan; respons negatif menjauhinya. Cahaya, air, gravitasi, dan sentuhan memunculkan jenis tropisme berbeda.","conceptName":"tropisme","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q25","package":3,"number":25,"question":"Hewan dengan rangka luar kitin, kaki berbuku-buku, dan mengalami ekdisis termasuk filum ...","options":{"A":"Arthropoda","B":"Platyhelminthes","C":"Porifera","D":"Chordata"},"answer":"A","answerText":"Arthropoda","modul":2,"moduleName":"Keanekaragaman dan Klasifikasi","difficulty":"Sedang","explain":"Arthropoda berkaki beruas dan memiliki eksoskeleton.","deepConcept":"Pengelompokan organisme didasarkan pada kumpulan karakter diagnostik, bukan satu ciri acak. Contohnya bulu sejati pada Aves, eksoskeleton kitin dan ruas kaki pada Arthropoda, serta klorofil pada tumbuhan hijau.","conceptName":"kelompok","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q26","package":3,"number":26,"question":"Panas Matahari mencapai Bumi melalui ruang hampa terutama dengan ...","options":{"A":"osmosis","B":"konveksi udara antariksa","C":"konduksi","D":"radiasi"},"answer":"D","answerText":"radiasi","modul":10,"moduleName":"Suhu dan Kalor","difficulty":"Sedang","explain":"Radiasi elektromagnetik tidak memerlukan medium.","deepConcept":"Konduksi memindahkan energi tanpa aliran massa secara keseluruhan; konveksi mengikutsertakan aliran fluida; radiasi merambat sebagai gelombang elektromagnetik bahkan dalam ruang hampa.","conceptName":"mekanisme","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q27","package":3,"number":27,"question":"Dalam hutan ditemukan rusa, gajah, rangkong, dan harimau. Perbedaan antarorganisme tersebut menunjukkan keanekaragaman tingkat ...","options":{"A":"individu satu spesies","B":"genetik saja","C":"molekuler saja","D":"spesies"},"answer":"D","answerText":"spesies","modul":2,"moduleName":"Keanekaragaman dan Klasifikasi","difficulty":"Sedang","explain":"Jenis organisme yang berbeda merupakan keanekaragaman spesies.","deepConcept":"Urutan takson dari luas ke sempit ialah kingdom–filum–kelas–ordo–famili–genus–spesies. Makin dekat nenek moyang bersama suatu pasangan organisme, makin dekat pula hubungan evolusionernya.","conceptName":"taksonomi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q28","package":3,"number":28,"question":"Pembukaan dan penutupan stomata terutama dikendalikan oleh ...","options":{"A":"bakteri akar saja","B":"sel penjaga","C":"sel otot","D":"sel darah merah"},"answer":"B","answerText":"sel penjaga","modul":4,"moduleName":"Fisiologi Tumbuhan","difficulty":"Mudah","explain":"Turgor sel penjaga mengatur celah stomata.","deepConcept":"Xilem mengalirkan air/mineral dari akar; floem mentranslokasikan gula dari bagian sumber ke bagian pemakai/penyimpan. Sel penjaga mengubah turgor untuk membuka atau menutup stomata.","conceptName":"transport","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q29","package":3,"number":29,"question":"Fase Bulan purnama terjadi saat ...","options":{"A":"Bulan selalu berada tepat di depan Matahari","B":"permukaan Bulan memancarkan cahaya sendiri","C":"Bulan tidak mendapat sinar Matahari","D":"Bumi kira-kira berada di antara Matahari dan Bulan"},"answer":"D","answerText":"Bumi kira-kira berada di antara Matahari dan Bulan","modul":12,"moduleName":"Bumi, Tata Surya, dan Antariksa","difficulty":"Sedang","explain":"Sisi Bulan yang menghadap Bumi tampak terang penuh.","deepConcept":"Rotasi Bumi menghasilkan siang–malam; revolusi Bumi bersama kemiringan sumbu rotasi menghasilkan musim. Orbit planet dan fase Bulan berbeda dari rotasi Bumi.","conceptName":"orbit","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q30","package":3,"number":30,"question":"Air 1 kg dipanaskan 5 °C dengan c=4.200 J/kg°C. Kalor yang dibutuhkan ...","options":{"A":"42.000 J","B":"4.200 J","C":"840 J","D":"21.000 J"},"answer":"D","answerText":"21.000 J","modul":10,"moduleName":"Suhu dan Kalor","difficulty":"Sulit","explain":"Q=1×4.200×5.","math":{"title":"Kalor jenis dan perubahan suhu","foundation":"Kalor jenis c didefinisikan sebagai energi kalor yang dibutuhkan per satuan massa untuk menaikkan suhu sebesar satu derajat: c = Q/(mΔT). Susun ulang menjadi Q = mcΔT, berlaku selama tidak ada perubahan wujud.","steps":["Definisi kalor jenis: c = Q/(mΔT).","Kalikan kedua ruas dengan mΔT → Q = mcΔT.","Massa m = 1 kg; kalor jenis c = 4.200 J/(kg·°C); perubahan suhu ΔT = 5 °C.","Q = 1 × 4.200 × 5 = 21.000 J. Satuan kg dan °C saling habis."],"symbol":"heat"},"deepConcept":"Kalor adalah energi yang berpindah karena beda suhu. Saat tidak terjadi perubahan wujud, Q = mcΔT; makin besar massa, kalor jenis, atau selisih suhu, makin besar energi yang diperlukan.","conceptName":"kalor","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Kalor 42.000 J menghasilkan ΔT = Q/(mc) = 42.000/(1×4.200), berbeda dari ΔT soal 5 °C. Yang memenuhi Q = mcΔT adalah 21.000 J.","B":"Kalor 4.200 J menghasilkan ΔT = Q/(mc) = 4.200/(1×4.200), berbeda dari ΔT soal 5 °C. Yang memenuhi Q = mcΔT adalah 21.000 J.","C":"Kalor 840 J menghasilkan ΔT = Q/(mc) = 840/(1×4.200), berbeda dari ΔT soal 5 °C. Yang memenuhi Q = mcΔT adalah 21.000 J."}},{"id":"p3q31","package":3,"number":31,"question":"Cairan empedu membantu pencernaan lemak dengan cara ...","options":{"A":"menyerap semua protein","B":"mengubah lemak menjadi glukosa","C":"memecah DNA secara langsung","D":"mengemulsikan lemak menjadi tetesan kecil"},"answer":"D","answerText":"mengemulsikan lemak menjadi tetesan kecil","modul":3,"moduleName":"Fisiologi Hewan","difficulty":"Sedang","explain":"Emulsifikasi memperluas permukaan lemak bagi lipase.","deepConcept":"Pencernaan memecah molekul besar agar dapat diserap. Amilase memecah pati, pepsin memecah protein, lipase memecah trigliserida; empedu bukan enzim, tetapi mengemulsikan lemak. Vili usus memperluas luas penyerapan.","conceptName":"pencernaan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q32","package":3,"number":32,"question":"Panjang gelombang 0,5 m dan frekuensi 20 Hz. Cepat rambat adalah ...","options":{"A":"0,025 m/s","B":"40 m/s","C":"10 m/s","D":"20,5 m/s"},"answer":"C","answerText":"10 m/s","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sedang","explain":"v=0,5×20=10 m/s.","math":{"title":"Hubungan panjang gelombang, frekuensi, dan cepat rambat","foundation":"Dalam satu periode T, gelombang menempuh satu panjang gelombang λ. Karena v = jarak/waktu = λ/T dan f=1/T, diperoleh v = fλ; bentuk lainnya f = v/λ dan λ = v/f.","steps":["Dalam satu periode, gelombang menempuh λ sehingga v = λ/T.","Karena f = 1/T, diperoleh v = fλ.","v = 20 × 0,5 = 10 m/s."],"symbol":"wave"},"deepConcept":"Frekuensi menyatakan banyak siklus per detik; periode menyatakan durasi satu siklus, dengan f = 1/T. Kecepatan gelombang terhubung ke frekuensi dan panjang gelombang melalui v = fλ.","conceptName":"gelombang","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Cepat rambat 0,025 m/s tidak cocok dengan f×λ = 20×0,5 = 10 m/s.","B":"Cepat rambat 40 m/s tidak cocok dengan f×λ = 20×0,5 = 10 m/s.","D":"Cepat rambat 20,5 m/s tidak cocok dengan f×λ = 20×0,5 = 10 m/s."}},{"id":"p3q33","package":3,"number":33,"question":"Bola bermassa 1 kg bergerak 6 m/s. Energi kinetiknya adalah ...","options":{"A":"3 J","B":"18 J","C":"6 J","D":"36 J"},"answer":"B","answerText":"18 J","modul":11,"moduleName":"Bentuk Energi dan Perubahannya","difficulty":"Sulit","explain":"Ek=½×1×6²=18 J.","math":{"title":"Asal rumus energi kinetik","foundation":"Usaha W = Fs = mas. Untuk benda mulai dari diam dengan percepatan tetap, v² = 2as, maka as = v²/2. Jadi W = m(v²/2) = ½mv², yaitu energi kinetik akhir.","steps":["Usaha untuk mempercepat benda dari diam menjadi energi kinetiknya: W = ½ m v².","Kuadratkan kecepatan terlebih dahulu: v² = 6² = 36 (m/s)².","Eₖ = ½ × 1 × 36 = 18 J.","Perhatikan: energi kinetik berbanding lurus dengan kuadrat kecepatan."],"symbol":"kinetic"},"deepConcept":"Energi kinetik bergantung pada massa dan kuadrat kelajuan: Eₖ = ½mv². Jika kecepatan menjadi dua kali, energi kinetik menjadi empat kali.","conceptName":"mekanik","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Dengan energi 3 J dan massa 1 kg, kelajuan seharusnya v = √(2E/m) ≈ 2,44949 m/s, bukan 6 m/s.","C":"Dengan energi 6 J dan massa 1 kg, kelajuan seharusnya v = √(2E/m) ≈ 3,4641 m/s, bukan 6 m/s.","D":"Dengan energi 36 J dan massa 1 kg, kelajuan seharusnya v = √(2E/m) ≈ 8,48528 m/s, bukan 6 m/s."}},{"id":"p3q34","package":3,"number":34,"question":"Kamera digital membentuk citra pada sensor menggunakan ...","options":{"A":"prisma yang menghilangkan cahaya","B":"lensa cembung yang memfokuskan cahaya","C":"cermin datar tanpa lensa","D":"magnet tetap sebagai sensor optik"},"answer":"B","answerText":"lensa cembung yang memfokuskan cahaya","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sulit","explain":"Lensa mengumpulkan cahaya sehingga terbentuk citra nyata.","deepConcept":"Lensa cembung (konvergen) memusatkan berkas, sedangkan lensa cekung (divergen) menyebarkan berkas. Kamera membentuk bayangan nyata pada sensor, kaca pembesar dapat membentuk bayangan maya diperbesar.","conceptName":"lensa","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q35","package":3,"number":35,"question":"Pada tuas, gaya 25 N bekerja 80 cm dari tumpu. Beban diletakkan 20 cm dari tumpu. Besar beban setimbang adalah ...","options":{"A":"200 N","B":"50 N","C":"25 N","D":"100 N"},"answer":"D","answerText":"100 N","modul":6,"moduleName":"Mekanika","difficulty":"Sulit","explain":"25×80 = W×20; W=100 N.","math":{"title":"Keseimbangan momen gaya","foundation":"Momen gaya terhadap titik tumpu adalah τ = F × l (lengan tegak lurus). Tuas seimbang apabila momen searah jarum jam sama dengan momen berlawanan arah: F₁l₁ = F₂l₂.","steps":["Abaikan gesekan dan massa tuas; jumlah momen terhadap titik tumpu = 0.","Momen sisi pertama = momen sisi kedua: F₁ × l₁ = F₂ × l₂.","25 × 80 = F₂ × 20 (lengan sama-sama dalam cm).","F₂ = (25 × 80)/20 = 100 N."],"symbol":"lever"},"deepConcept":"Gaya adalah besaran vektor; resultan harus mempertimbangkan arah. Benda bermassa m mengalami percepatan a menurut ΣF = ma. Gaya gesek yang melawan gerak dikurangkan dari gaya dorong.","conceptName":"gaya","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Gaya 200 N pada lengan 20 cm menghasilkan momen 4.000 N·cm, sementara momen sisi lain 2.000 N·cm. Momen belum seimbang.","B":"Gaya 50 N pada lengan 20 cm menghasilkan momen 1.000 N·cm, sementara momen sisi lain 2.000 N·cm. Momen belum seimbang.","C":"Gaya 25 N pada lengan 20 cm menghasilkan momen 500 N·cm, sementara momen sisi lain 2.000 N·cm. Momen belum seimbang."}},{"id":"p3q36","package":3,"number":36,"question":"Hambatan 8 Ω dilalui arus 0,5 A. Tegangan pada ujungnya adalah ...","options":{"A":"0,0625 V","B":"16 V","C":"8,5 V","D":"4 V"},"answer":"D","answerText":"4 V","modul":8,"moduleName":"Listrik dan Magnet","difficulty":"Sedang","explain":"V=IR=0,5×8=4 V.","math":{"title":"Hukum Ohm","foundation":"Untuk resistor ohmik pada kondisi tetap, tegangan V sebanding dengan arus I: V = I R. Dengan membagi kedua ruas, I = V/R atau R = V/I sesuai besaran yang ditanyakan.","steps":["Mulai dari Hukum Ohm: V = I × R.","V sudah terisolasi, cukup kalikan arus dengan hambatan.","V = 0,5 × 8 = 4 V."],"symbol":"ohm"},"deepConcept":"Rangkaian seri memiliki arus yang sama dan tegangan terbagi, sehingga R total dijumlahkan. Rangkaian paralel memiliki tegangan yang sama dan arus terbagi, sehingga kebalikan hambatan dijumlahkan.","conceptName":"rangkaian","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Tegangan 0,0625 V tidak setara dengan hasil I×R = 0,5×8 = 4 V.","B":"Tegangan 16 V tidak setara dengan hasil I×R = 0,5×8 = 4 V.","C":"Tegangan 8,5 V tidak setara dengan hasil I×R = 0,5×8 = 4 V."}},{"id":"p3q37","package":3,"number":37,"question":"Benda dengan massa jenis 750 kg/m³ dimasukkan ke air dengan massa jenis 1.000 kg/m³. Benda cenderung ...","options":{"A":"melayang seluruhnya tanpa bagian muncul","B":"tenggelam ke dasar","C":"berubah menjadi air","D":"terapung"},"answer":"D","answerText":"terapung","modul":7,"moduleName":"Wujud Benda dan Fluida","difficulty":"Sedang","explain":"ρ benda lebih kecil daripada ρ air.","deepConcept":"Massa jenis ρ = m/V; benda bebas dalam fluida yang massa jenisnya lebih kecil dari benda cenderung tenggelam, sebaliknya dapat terapung. Untuk benda terapung, gaya apung mengimbangi berat benda.","conceptName":"massa","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain.","math":{"title":"Membandingkan massa jenis dan gaya apung","foundation":"Berat benda = ρ benda × V × g, sementara gaya apung maksimum saat seluruhnya tercelup = ρ fluida × V × g. Ketika ρ benda lebih kecil dari ρ fluida, gaya apung pada kondisi tercelup penuh lebih besar daripada berat, sehingga benda naik dan dapat terapung.","steps":["Diketahui ρ benda = 750 kg/m³ dan ρ air = 1.000 kg/m³.","Bandingkan ρ benda/ρ air = 750/1.000 = 0,75, lebih kecil dari 1.","Pada kondisi setimbang mengapung, fraksi volume tercelup ≈ ρ benda/ρ air = 0,75 (75%), dengan asumsi benda homogen dan tidak menyentuh dasar.","Karena massa jenis benda lebih rendah daripada air, keadaannya cenderung terapung."],"symbol":"density"}},{"id":"p3q38","package":3,"number":38,"question":"Pada tumbuhan berbunga, bakal buah setelah pembuahan lazimnya berkembang menjadi ...","options":{"A":"serbuk sari","B":"buah","C":"embrio saja","D":"xilem"},"answer":"B","answerText":"buah","modul":4,"moduleName":"Fisiologi Tumbuhan","difficulty":"Sulit","explain":"Dinding ovarium berkembang menjadi bagian buah.","deepConcept":"Kambium vaskular membentuk xilem/floem sekunder sehingga batang menebal. Setelah pembuahan bunga, bakal buah berkembang menjadi buah dan bakal biji menjadi biji.","conceptName":"struktur","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q39","package":3,"number":39,"question":"Pada tahap metafase mitosis, kromosom tersusun di ...","options":{"A":"nukleolus yang telah utuh","B":"bidang ekuator sel","C":"permukaan dinding sel saja","D":"dalam lisosom"},"answer":"B","answerText":"bidang ekuator sel","modul":5,"moduleName":"Sistem Organ, Sel, dan Genetika","difficulty":"Sedang","explain":"Metafase ditandai kromosom berjajar di tengah.","deepConcept":"Mitosis menghasilkan sel anak dengan jumlah kromosom umumnya sama, sedangkan meiosis mengurangi jumlah kromosom menjadi separuh. Sebelum pembelahan, DNA direplikasi pada fase S; kromosom sejajar pada metafase dan kromatid saudara berpisah pada anafase mitosis.","conceptName":"pembelahan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q40","package":3,"number":40,"question":"Kapur barus lama-kelamaan mengecil di lemari karena mengalami ...","options":{"A":"kondensasi","B":"pembekuan","C":"sublimasi","D":"pengembunan"},"answer":"C","answerText":"sublimasi","modul":7,"moduleName":"Wujud Benda dan Fluida","difficulty":"Sedang","explain":"Padat berubah menjadi gas tanpa fase cair yang tampak.","deepConcept":"Perubahan wujud dibedakan berdasarkan arah: padat→cair mencair; gas→cair mengembun; padat→gas menyublim; gas→padat deposisi. Titik didih turun ketika tekanan luar turun.","conceptName":"wujud","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q41","package":3,"number":41,"question":"Benalu menyerap air dan nutrien dari pohon inang sehingga merugikannya. Ini contoh ...","options":{"A":"komensalisme","B":"mutualisme","C":"netralisme","D":"parasitisme"},"answer":"D","answerText":"parasitisme","modul":13,"moduleName":"Ekologi dan Pelestarian Lingkungan","difficulty":"Sedang","explain":"Parasit mendapat manfaat dengan merugikan inang.","deepConcept":"Mutualisme menguntungkan kedua pihak; komensalisme menguntungkan satu pihak tanpa dampak berarti pada pihak lain; parasitisme merugikan inang; predasi membunuh/memakan mangsa; kompetisi terjadi ketika organisme memperebutkan sumber terbatas.","conceptName":"interaksi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q42","package":3,"number":42,"question":"Air minum yang tercemar tinja dapat menyebabkan peningkatan penyakit ...","options":{"A":"kelainan lensa","B":"rabun jauh","C":"diare infeksius","D":"patah tulang"},"answer":"C","answerText":"diare infeksius","modul":14,"moduleName":"Kesehatan, Lingkungan, dan Teknologi","difficulty":"Sulit","explain":"Patogen enterik dapat menyebar lewat air tercemar.","deepConcept":"Pencegahan penyakit mencakup pengendalian pajanan, sanitasi, vaksinasi, dan perawatan yang tepat. Vaksin merangsang respons imun adaptif dan memori; antibiotik hanya bermanfaat untuk infeksi yang sesuai, bukan semua penyakit.","conceptName":"kesehatan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q43","package":3,"number":43,"question":"Penyelam berada di kedalaman 3 m air (ρ=1.000 kg/m³; g=10 m/s²). Tekanan hidrostatisnya adalah ...","options":{"A":"30.000 Pa","B":"3.000 Pa","C":"13.000 Pa","D":"300.000 Pa"},"answer":"A","answerText":"30.000 Pa","modul":7,"moduleName":"Wujud Benda dan Fluida","difficulty":"Sedang","explain":"p=1.000×10×3.","math":{"title":"Penurunan tekanan hidrostatis","foundation":"Bayangkan kolom cairan berluas A dan tinggi h. Volumenya V = Ah, massanya m = ρAh, beratnya F = mg = ρAhg. Tekanan p = F/A sehingga p = ρgh. Untuk dua titik, Δp = ρgΔh.","steps":["Tekanan kolom cairan: p = F/A. Dengan F = mg = ρAhg, maka p = ρgh.","Yang dicari tekanan hidrostatis relatif terhadap permukaan, bukan tekanan absolut.","ρ = 1.000 kg/m³, g = 10 m/s², h = 3 m.","p = 1.000 × 10 × 3 = 30.000 Pa."],"symbol":"hydro"},"deepConcept":"Tekanan hidrostatis adalah tekanan akibat berat kolom fluida di atas titik. Tekanan bertambah jika massa jenis, percepatan gravitasi, atau kedalaman meningkat.","conceptName":"hidrostatis","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"B":"Tekanan 3.000 Pa mengharuskan kedalaman h = p/(ρg) = 0,3 m, bukan 3 m.","C":"Tekanan 13.000 Pa mengharuskan kedalaman h = p/(ρg) = 1,3 m, bukan 3 m.","D":"Tekanan 300.000 Pa mengharuskan kedalaman h = p/(ρg) = 30 m, bukan 3 m."}},{"id":"p3q44","package":3,"number":44,"question":"Cahaya merambat dari air ke udara dengan sudut datang kecil. Arah sinar bias umumnya ...","options":{"A":"membentuk sudut nol tanpa syarat","B":"tetap sama untuk semua sudut","C":"mendekati garis normal","D":"menjauhi garis normal"},"answer":"D","answerText":"menjauhi garis normal","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sulit","explain":"Indeks bias berkurang sehingga sinar membelok menjauhi normal.","deepConcept":"Pada cermin datar, sudut datang sama dengan sudut pantul jika diukur dari garis normal. Pada cermin cembung, sinar pantul menyebar sehingga bidang pandang menjadi luas.","conceptName":"pantul","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q45","package":3,"number":45,"question":"Hambatan 12 Ω dan 6 Ω dipasang paralel. Hambatan ekuivalen ...","options":{"A":"4 Ω","B":"6 Ω","C":"2 Ω","D":"18 Ω"},"answer":"A","answerText":"4 Ω","modul":8,"moduleName":"Listrik dan Magnet","difficulty":"Sulit","explain":"R=(12×6)/(12+6)=4 Ω.","math":{"title":"Mengapa rumus paralel berupa kebalikan?","foundation":"Tegangan V sama pada setiap cabang paralel; arus total adalah penjumlahan arus cabang: I = V/R₁+V/R₂. Karena I=V/R total, pembagian dengan V menghasilkan 1/R total = 1/R₁+1/R₂.","steps":["Tegangan pada setiap cabang paralel sama, sedangkan arus total adalah jumlah arus cabang.","Karena I total = Σ(V/Rᵢ) = V/R total, maka 1/R total = Σ(1/Rᵢ).","Untuk dua resistor, R total = (R₁ × R₂)/(R₁ + R₂) = (12 × 6)/(12 + 6) = 4 Ω."],"symbol":"parallel"},"deepConcept":"Rangkaian seri memiliki arus yang sama dan tegangan terbagi, sehingga R total dijumlahkan. Rangkaian paralel memiliki tegangan yang sama dan arus terbagi, sehingga kebalikan hambatan dijumlahkan.","conceptName":"rangkaian","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"B":"Hambatan 6 Ω berbeda dari (R₁R₂)/(R₁+R₂) = 4 Ω; hambatan paralel juga harus lebih kecil daripada setiap cabang.","C":"Hambatan 2 Ω berbeda dari (R₁R₂)/(R₁+R₂) = 4 Ω; hambatan paralel juga harus lebih kecil daripada setiap cabang.","D":"Hambatan 18 Ω berbeda dari (R₁R₂)/(R₁+R₂) = 4 Ω; hambatan paralel juga harus lebih kecil daripada setiap cabang."}},{"id":"p3q46","package":3,"number":46,"question":"Jika hutan mangrove dikonversi seluruhnya menjadi tambak, fungsi yang paling berisiko hilang adalah ...","options":{"A":"cahaya Matahari di laut","B":"habitat pembesaran ikan dan perlindungan pesisir","C":"pasang surut Bumi","D":"gravitasi air laut"},"answer":"B","answerText":"habitat pembesaran ikan dan perlindungan pesisir","modul":13,"moduleName":"Ekologi dan Pelestarian Lingkungan","difficulty":"Sulit","explain":"Mangrove menyediakan nurseri dan proteksi pantai.","deepConcept":"Konservasi in situ melindungi spesies di habitat aslinya, sementara ex situ menjaga populasi atau plasma nutfah di luar habitat. Gangguan dan fragmentasi habitat dapat mengurangi keterhubungan populasi asli.","conceptName":"konservasi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q47","package":3,"number":47,"question":"Hambatan 5 Ω, 7 Ω, dan 8 Ω disusun seri pada sumber 40 V. Arus rangkaian adalah ...","options":{"A":"1 A","B":"2 A","C":"20 A","D":"4 A"},"answer":"B","answerText":"2 A","modul":8,"moduleName":"Listrik dan Magnet","difficulty":"Sedang","explain":"R=20 Ω sehingga I=40/20=2 A.","math":{"title":"Mengapa hambatan seri dijumlahkan?","foundation":"Arus I sama melalui setiap resistor seri; tegangan sumber terbagi: V total = V₁+V₂+… = IR₁+IR₂+… = I(R₁+R₂+…). Membagi kedua ruas dengan I menghasilkan R total = ΣR.","steps":["Arus pada semua resistor seri sama.","Tegangan total V = Σ(IRᵢ) = I ΣRᵢ → R total = ΣRᵢ.","R total = 5 + 7 + 8 = 20 Ω.","I = V/R total = 40/20 = 2 A. Arus ini sama pada setiap resistor seri."],"symbol":"series"},"deepConcept":"Rangkaian seri memiliki arus yang sama dan tegangan terbagi, sehingga R total dijumlahkan. Rangkaian paralel memiliki tegangan yang sama dan arus terbagi, sehingga kebalikan hambatan dijumlahkan.","conceptName":"rangkaian","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Arus 1 A akan memerlukan tegangan V = IR = 1×20 = 20 V, tidak sama dengan baterai 40 V.","C":"Arus 20 A akan memerlukan tegangan V = IR = 20×20 = 400 V, tidak sama dengan baterai 40 V.","D":"Arus 4 A akan memerlukan tegangan V = IR = 4×20 = 80 V, tidak sama dengan baterai 40 V."}},{"id":"p3q48","package":3,"number":48,"question":"Antibiotik yang menghambat sintesis dinding sel bakteri biasanya tidak efektif melawan virus karena ...","options":{"A":"virus memiliki peptidoglikan lebih tebal","B":"virus tidak mempunyai dinding sel bakteri sebagai target","C":"virus adalah bakteri kecil","D":"virus menghasilkan antibiotik sendiri"},"answer":"B","answerText":"virus tidak mempunyai dinding sel bakteri sebagai target","modul":5,"moduleName":"Sistem Organ, Sel, dan Genetika","difficulty":"Sulit","explain":"Target antibiotik tertentu tidak ditemukan pada virus.","deepConcept":"Kloroplas menangkap energi cahaya; mitokondria menghasilkan banyak ATP melalui respirasi aerob; ribosom menyusun protein; badan Golgi memodifikasi dan mengemas produk. DNA sel eukariotik sebagian besar berada di nukleus, sedangkan bakteri memiliki nukleoid.","conceptName":"organel","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q49","package":3,"number":49,"question":"Pencegahan demam berdarah yang penting adalah ...","options":{"A":"memberantas tempat berkembang biak nyamuk Aedes","B":"menggunakan antibiotik tanpa indikasi","C":"membiarkan genangan air terbuka","D":"memelihara jentik nyamuk"},"answer":"A","answerText":"memberantas tempat berkembang biak nyamuk Aedes","modul":14,"moduleName":"Kesehatan, Lingkungan, dan Teknologi","difficulty":"Sedang","explain":"Aedes berkembang biak pada tempat air tergenang.","deepConcept":"Pencegahan penyakit mencakup pengendalian pajanan, sanitasi, vaksinasi, dan perawatan yang tepat. Vaksin merangsang respons imun adaptif dan memori; antibiotik hanya bermanfaat untuk infeksi yang sesuai, bukan semua penyakit.","conceptName":"kesehatan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p3q50","package":3,"number":50,"question":"Ketika suhu tubuh naik, berkeringat membantu tubuh karena ...","options":{"A":"air keringat membentuk energi baru","B":"keringat menghentikan aliran darah","C":"keringat menambah panas tubuh","D":"penguapan keringat menyerap kalor dari kulit"},"answer":"D","answerText":"penguapan keringat menyerap kalor dari kulit","modul":3,"moduleName":"Fisiologi Hewan","difficulty":"Sedang","explain":"Kalor laten penguapan membantu pendinginan tubuh.","deepConcept":"Ketika keringat menguap, air mengambil kalor laten dari kulit. Pendinginan terjadi karena perpindahan energi, bukan karena keringat sendiri pasti bersuhu lebih dingin.","conceptName":"suhu","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q1","package":4,"number":1,"question":"Balok 3 kg berada di ketinggian 2 m, g=10 m/s². Energi potensialnya adalah ...","options":{"A":"60 J","B":"120 J","C":"6 J","D":"30 J"},"answer":"A","answerText":"60 J","modul":11,"moduleName":"Bentuk Energi dan Perubahannya","difficulty":"Sulit","explain":"Ep=3×10×2=60 J.","math":{"title":"Asal rumus energi potensial gravitasi","foundation":"Untuk mengangkat benda perlahan melawan gravitasi dengan gaya F = mg sejauh tinggi h, usaha W = Fh = mgh. Energi yang tersimpan akibat ketinggian adalah Eₚ = mgh (g dianggap konstan).","steps":["Besar gaya berat W = mg.","Usaha menaikkan benda perlahan = gaya × perpindahan vertikal: Eₚ = W h = mgh.","Eₚ = 3 × 10 × 2 = 60 J."],"symbol":"potential"},"deepConcept":"Energi potensial gravitasi Eₚ = mgh terhadap acuan ketinggian. Bertambah linier terhadap massa dan kenaikan tinggi untuk medan gravitasi yang dianggap konstan.","conceptName":"potensial","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"B":"Energi 120 J akan membutuhkan tinggi h = E/(mg) = 4 m, bukan 2 m.","C":"Energi 6 J akan membutuhkan tinggi h = E/(mg) = 0,2 m, bukan 2 m.","D":"Energi 30 J akan membutuhkan tinggi h = E/(mg) = 1 m, bukan 2 m."}},{"id":"p4q2","package":4,"number":2,"question":"Ayunan menyelesaikan 15 getaran dalam 30 s. Periodenya adalah ...","options":{"A":"2 s","B":"45 s","C":"15 s","D":"0,5 s"},"answer":"A","answerText":"2 s","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sedang","explain":"T=30/15=2 s.","math":{"title":"Frekuensi dan periode dari definisi","foundation":"Frekuensi f adalah banyaknya getaran n dalam waktu t, maka f = n/t. Periode T adalah waktu satu getaran, sehingga T = t/n = 1/f. Satuan f = hertz (Hz), T = detik (s).","steps":["Frekuensi adalah getaran per detik: f = n/t.","Periode adalah detik per getaran: T = t/n = 1/f.","Diketahui n = 15 dan t = 30 s, jadi T = 30/15 = 2 s."],"symbol":"frequency"},"deepConcept":"Frekuensi menyatakan banyak siklus per detik; periode menyatakan durasi satu siklus, dengan f = 1/T. Kecepatan gelombang terhubung ke frekuensi dan panjang gelombang melalui v = fλ.","conceptName":"gelombang","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"B":"Periode 45 s berarti n = t/T = 0,66667 getaran pada waktu 30 s, tidak cocok dengan 15 getaran dalam soal.","C":"Periode 15 s berarti n = t/T = 2 getaran pada waktu 30 s, tidak cocok dengan 15 getaran dalam soal.","D":"Periode 0,5 s berarti n = t/T = 60 getaran pada waktu 30 s, tidak cocok dengan 15 getaran dalam soal."}},{"id":"p4q3","package":4,"number":3,"question":"Mikroplastik yang dimakan zooplankton kemudian dimangsa ikan dapat berpindah melalui ...","options":{"A":"rantai makanan","B":"konduksi listrik di air","C":"fotosintesis saja","D":"pelapukan batuan vulkanik"},"answer":"A","answerText":"rantai makanan","modul":13,"moduleName":"Ekologi dan Pelestarian Lingkungan","difficulty":"Sulit","explain":"Partikel dapat berpindah antar tingkat trofik.","deepConcept":"Dalam rantai makanan, produsen membentuk bahan organik melalui fotosintesis, konsumen I memakan produsen, konsumen II memakan konsumen I, dan pengurai mendaur ulang unsur hara.","conceptName":"rantai","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q4","package":4,"number":4,"question":"Dalam penyelidikan hubungan pupuk dengan tinggi tanaman, 10 pot diuji pada setiap perlakuan. Mengapa pot ulangan diperlukan?","options":{"A":"agar hasil pasti sesuai hipotesis","B":"agar semua tanaman pasti tumbuh sama","C":"untuk mengganti perlunya kelompok kontrol","D":"untuk mengukur variasi hasil dan meningkatkan keandalan"},"answer":"D","answerText":"untuk mengukur variasi hasil dan meningkatkan keandalan","modul":1,"moduleName":"Keterampilan dan Metode Ilmiah","difficulty":"Sulit","explain":"Pengulangan mengurangi ketergantungan pada satu pengamatan.","deepConcept":"Variabel bebas adalah faktor yang sengaja diubah; variabel terikat adalah hasil yang diukur; variabel kontrol adalah faktor lain yang dibuat tetap. Perbandingan bermakna jika perlakuan berbeda pada satu faktor utama saja.","conceptName":"variabel","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q5","package":4,"number":5,"question":"Akar cenderung tumbuh menuju daerah tanah yang lebih lembap. Respons tersebut disebut ...","options":{"A":"fototropisme negatif","B":"tigmonasti","C":"seismonasti","D":"hidrotropisme positif"},"answer":"D","answerText":"hidrotropisme positif","modul":4,"moduleName":"Fisiologi Tumbuhan","difficulty":"Sedang","explain":"Hidrotropisme terkait gradien ketersediaan air.","deepConcept":"Tropisme adalah respons pertumbuhan yang arahnya bergantung arah rangsangan. Respons positif tumbuh mendekati rangsangan; respons negatif menjauhinya. Cahaya, air, gravitasi, dan sentuhan memunculkan jenis tropisme berbeda.","conceptName":"tropisme","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q6","package":4,"number":6,"question":"Sensor kualitas udara yang melaporkan konsentrasi PM2,5 terutama mengukur ...","options":{"A":"suhu inti Matahari","B":"partikel halus berdiameter aerodinamis hingga 2,5 mikrometer","C":"ketinggian awan saja","D":"kadar klorofil di laut"},"answer":"B","answerText":"partikel halus berdiameter aerodinamis hingga 2,5 mikrometer","modul":14,"moduleName":"Kesehatan, Lingkungan, dan Teknologi","difficulty":"Sulit","explain":"PM2,5 adalah fraksi partikulat udara berukuran halus.","deepConcept":"Sensor mengubah besaran fisik/kimia/optik menjadi informasi terukur. Kamera multispektral memanfaatkan perbedaan pantulan spektral; PM2,5 mengacu pada partikel dengan diameter aerodinamis tidak lebih dari 2,5 μm.","conceptName":"sensor","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q7","package":4,"number":7,"question":"Benda bermassa 3 kg mengalami resultan gaya 15 N. Percepatannya adalah ...","options":{"A":"3 m/s²","B":"5 m/s²","C":"12 m/s²","D":"45 m/s²"},"answer":"B","answerText":"5 m/s²","modul":6,"moduleName":"Mekanika","difficulty":"Sedang","explain":"Hukum II Newton: a=15/3=5.","math":{"title":"Hukum II Newton dan resultan gaya","foundation":"Hukum II Newton menyatakan ΣF = m a. Gaya berlawanan arah diberi tanda berlawanan sehingga ΣF = F dorong − F gesek; akibatnya a = ΣF/m.","steps":["Pilih arah dorong/tarik sebagai arah positif.","Dari Hukum II Newton: ΣF = ma, sehingga a = ΣF/m.","Gaya bersih ΣF = 15 − 0 = 15 N.","a = 15/3 = 5 m/s²."],"symbol":"newton"},"deepConcept":"Gaya adalah besaran vektor; resultan harus mempertimbangkan arah. Benda bermassa m mengalami percepatan a menurut ΣF = ma. Gaya gesek yang melawan gerak dikurangkan dari gaya dorong.","conceptName":"gaya","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Jika percepatan 3 m/s², gaya bersih yang dibutuhkan m×a = 3×3 = 9 N, padahal soal menetapkan gaya bersih 15 N.","C":"Jika percepatan 12 m/s², gaya bersih yang dibutuhkan m×a = 3×12 = 36 N, padahal soal menetapkan gaya bersih 15 N.","D":"Jika percepatan 45 m/s², gaya bersih yang dibutuhkan m×a = 3×45 = 135 N, padahal soal menetapkan gaya bersih 15 N."}},{"id":"p4q8","package":4,"number":8,"question":"Logam 2 kg dengan kalor jenis 500 J/kg°C mengalami kenaikan 8 °C. Kalor yang diterima ...","options":{"A":"16.000 J","B":"8.000 J","C":"1.000 J","D":"4.000 J"},"answer":"B","answerText":"8.000 J","modul":10,"moduleName":"Suhu dan Kalor","difficulty":"Sulit","explain":"Q=2×500×8.","math":{"title":"Kalor jenis dan perubahan suhu","foundation":"Kalor jenis c didefinisikan sebagai energi kalor yang dibutuhkan per satuan massa untuk menaikkan suhu sebesar satu derajat: c = Q/(mΔT). Susun ulang menjadi Q = mcΔT, berlaku selama tidak ada perubahan wujud.","steps":["Definisi kalor jenis: c = Q/(mΔT).","Kalikan kedua ruas dengan mΔT → Q = mcΔT.","Massa m = 2 kg; kalor jenis c = 500 J/(kg·°C); perubahan suhu ΔT = 8 °C.","Q = 2 × 500 × 8 = 8.000 J. Satuan kg dan °C saling habis."],"symbol":"heat"},"deepConcept":"Kalor adalah energi yang berpindah karena beda suhu. Saat tidak terjadi perubahan wujud, Q = mcΔT; makin besar massa, kalor jenis, atau selisih suhu, makin besar energi yang diperlukan.","conceptName":"kalor","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Kalor 16.000 J menghasilkan ΔT = Q/(mc) = 16.000/(2×500), berbeda dari ΔT soal 8 °C. Yang memenuhi Q = mcΔT adalah 8.000 J.","C":"Kalor 1.000 J menghasilkan ΔT = Q/(mc) = 1.000/(2×500), berbeda dari ΔT soal 8 °C. Yang memenuhi Q = mcΔT adalah 8.000 J.","D":"Kalor 4.000 J menghasilkan ΔT = Q/(mc) = 4.000/(2×500), berbeda dari ΔT soal 8 °C. Yang memenuhi Q = mcΔT adalah 8.000 J."}},{"id":"p4q9","package":4,"number":9,"question":"Gelombang menempuh 60 m dalam 3 s. Jika panjang gelombangnya 4 m, frekuensi adalah ...","options":{"A":"2 Hz","B":"15 Hz","C":"5 Hz","D":"20 Hz"},"answer":"C","answerText":"5 Hz","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sedang","explain":"v=20 m/s; f=v/λ=5 Hz.","math":{"title":"Hubungan panjang gelombang, frekuensi, dan cepat rambat","foundation":"Dalam satu periode T, gelombang menempuh satu panjang gelombang λ. Karena v = jarak/waktu = λ/T dan f=1/T, diperoleh v = fλ; bentuk lainnya f = v/λ dan λ = v/f.","steps":["Dalam satu periode, gelombang menempuh λ sehingga v = λ/T.","Karena f = 1/T, diperoleh v = fλ.","Tentukan kecepatan lebih dahulu: v = s/t = 60/3 = 20 m/s.","Ubah susunan: f = v/λ.","f = 20/4 = 5 Hz."],"symbol":"wave"},"deepConcept":"Frekuensi menyatakan banyak siklus per detik; periode menyatakan durasi satu siklus, dengan f = 1/T. Kecepatan gelombang terhubung ke frekuensi dan panjang gelombang melalui v = fλ.","conceptName":"gelombang","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Frekuensi 2 Hz dengan panjang gelombang 4 m menghasilkan v = fλ = 8 m/s, bukan 20 m/s.","B":"Frekuensi 15 Hz dengan panjang gelombang 4 m menghasilkan v = fλ = 60 m/s, bukan 20 m/s.","D":"Frekuensi 20 Hz dengan panjang gelombang 4 m menghasilkan v = fλ = 80 m/s, bukan 20 m/s."}},{"id":"p4q10","package":4,"number":10,"question":"Batang berkayu menebal dari tahun ke tahun terutama karena aktivitas ...","options":{"A":"kambium vaskular","B":"jaringan palisade","C":"rambut akar","D":"stomata"},"answer":"A","answerText":"kambium vaskular","modul":4,"moduleName":"Fisiologi Tumbuhan","difficulty":"Sulit","explain":"Kambium menghasilkan xilem dan floem sekunder.","deepConcept":"Xilem mengalirkan air/mineral dari akar; floem mentranslokasikan gula dari bagian sumber ke bagian pemakai/penyimpan. Sel penjaga mengubah turgor untuk membuka atau menutup stomata.","conceptName":"transport","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q11","package":4,"number":11,"question":"Pada kolam air, kedalaman titik P adalah 1 m dan Q 4 m. Selisih tekanan hidrostatis P dan Q (g=10 m/s²) adalah ...","options":{"A":"40.000 Pa","B":"10.000 Pa","C":"30.000 Pa","D":"50.000 Pa"},"answer":"C","answerText":"30.000 Pa","modul":7,"moduleName":"Wujud Benda dan Fluida","difficulty":"Sedang","explain":"Δh=3 m; Δp=1.000×10×3.","math":{"title":"Penurunan tekanan hidrostatis","foundation":"Bayangkan kolom cairan berluas A dan tinggi h. Volumenya V = Ah, massanya m = ρAh, beratnya F = mg = ρAhg. Tekanan p = F/A sehingga p = ρgh. Untuk dua titik, Δp = ρgΔh.","steps":["Tekanan kolom cairan: p = F/A. Dengan F = mg = ρAhg, maka p = ρgh.","Karena yang ditanya selisih, gunakan Δp = ρgΔh; tekanan atmosfer yang sama di kedua titik saling meniadakan.","ρ = 1.000 kg/m³, g = 10 m/s², Δh = 3 m.","Δp = 1.000 × 10 × 3 = 30.000 Pa."],"symbol":"hydro"},"deepConcept":"Tekanan hidrostatis adalah tekanan akibat berat kolom fluida di atas titik. Tekanan bertambah jika massa jenis, percepatan gravitasi, atau kedalaman meningkat.","conceptName":"hidrostatis","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Tekanan 40.000 Pa mengharuskan beda kedalaman h = p/(ρg) = 4 m, bukan 3 m.","B":"Tekanan 10.000 Pa mengharuskan beda kedalaman h = p/(ρg) = 1 m, bukan 3 m.","D":"Tekanan 50.000 Pa mengharuskan beda kedalaman h = p/(ρg) = 5 m, bukan 3 m."}},{"id":"p4q12","package":4,"number":12,"question":"Sebuah batu bermassa 540 g menambah volume air dalam gelas ukur sebesar 200 cm³. Massa jenisnya adalah ...","options":{"A":"2,7 g/cm³","B":"1,8 g/cm³","C":"7,4 g/cm³","D":"0,37 g/cm³"},"answer":"A","answerText":"2,7 g/cm³","modul":7,"moduleName":"Wujud Benda dan Fluida","difficulty":"Sedang","explain":"ρ=540/200=2,7.","math":{"title":"Definisi massa jenis","foundation":"Massa jenis menyatakan berapa massa yang terdapat dalam setiap satuan volume: ρ = m/V. Satuan harus konsisten: 1.000 cm³ = 0,001 m³ dan 1 g/cm³ = 1.000 kg/m³.","steps":["Dari definisi, massa jenis ρ = massa/volume = m/V.","Gunakan satuan konsisten: m = 540 g; V = 200 cm³.","ρ = 540/200 = 2,7 g/cm³.","Bandingkan dengan massa jenis air ≈ 1 g/cm³: benda dengan ρ lebih kecil dapat terapung (jika bebas dan tidak ada faktor lain)."],"symbol":"density"},"deepConcept":"Massa jenis ρ = m/V; benda bebas dalam fluida yang massa jenisnya lebih kecil dari benda cenderung tenggelam, sebaliknya dapat terapung. Untuk benda terapung, gaya apung mengimbangi berat benda.","conceptName":"massa","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"B":"Jika massa jenis 1,8 g/cm³, massa yang sesuai pada volume soal menjadi m = ρV = 360 g, sedangkan massa benda sebenarnya 540.","C":"Jika massa jenis 7,4 g/cm³, massa yang sesuai pada volume soal menjadi m = ρV = 1.480 g, sedangkan massa benda sebenarnya 540.","D":"Jika massa jenis 0,37 g/cm³, massa yang sesuai pada volume soal menjadi m = ρV = 74 g, sedangkan massa benda sebenarnya 540."}},{"id":"p4q13","package":4,"number":13,"question":"Dua spesies burung menggunakan sumber serangga yang terbatas di satu habitat. Interaksi utama keduanya adalah ...","options":{"A":"dekomposisi","B":"mutualisme obligat","C":"kompetisi","D":"parasitisme dari kedua sisi"},"answer":"C","answerText":"kompetisi","modul":13,"moduleName":"Ekologi dan Pelestarian Lingkungan","difficulty":"Sedang","explain":"Kebutuhan sumber daya sama menimbulkan persaingan.","deepConcept":"Mutualisme menguntungkan kedua pihak; komensalisme menguntungkan satu pihak tanpa dampak berarti pada pihak lain; parasitisme merugikan inang; predasi membunuh/memakan mangsa; kompetisi terjadi ketika organisme memperebutkan sumber terbatas.","conceptName":"interaksi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q14","package":4,"number":14,"question":"Uap air berubah menjadi kristal es pada permukaan yang sangat dingin. Proses ini disebut ...","options":{"A":"mencair","B":"menguap","C":"deposisi/resublimasi","D":"mendidih"},"answer":"C","answerText":"deposisi/resublimasi","modul":7,"moduleName":"Wujud Benda dan Fluida","difficulty":"Sedang","explain":"Gas langsung menjadi padat.","deepConcept":"Perubahan wujud dibedakan berdasarkan arah: padat→cair mencair; gas→cair mengembun; padat→gas menyublim; gas→padat deposisi. Titik didih turun ketika tekanan luar turun.","conceptName":"wujud","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q15","package":4,"number":15,"question":"Jika populasi pemangsa ular meningkat sementara faktor lain sama, populasi mangsa tikus pada awalnya cenderung ...","options":{"A":"berubah menjadi predator","B":"meningkat tanpa batas","C":"tidak pernah berubah","D":"menurun"},"answer":"D","answerText":"menurun","modul":13,"moduleName":"Ekologi dan Pelestarian Lingkungan","difficulty":"Sedang","explain":"Predasi yang lebih besar dapat menekan populasi mangsa.","deepConcept":"Mutualisme menguntungkan kedua pihak; komensalisme menguntungkan satu pihak tanpa dampak berarti pada pihak lain; parasitisme merugikan inang; predasi membunuh/memakan mangsa; kompetisi terjadi ketika organisme memperebutkan sumber terbatas.","conceptName":"interaksi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q16","package":4,"number":16,"question":"Bilik kiri jantung terutama memompa darah menuju ...","options":{"A":"seluruh tubuh melalui aorta","B":"paru-paru melalui vena pulmonalis","C":"paru-paru melalui arteri pulmonalis","D":"serambi kanan melalui vena kava"},"answer":"A","answerText":"seluruh tubuh melalui aorta","modul":3,"moduleName":"Fisiologi Hewan","difficulty":"Mudah","explain":"Sirkulasi sistemik dipompa dari bilik kiri.","deepConcept":"Aliran darah sistemik: bilik kiri → aorta → jaringan → vena kava → serambi kanan. Aliran pulmonal: bilik kanan → arteri pulmonalis → paru-paru → vena pulmonalis → serambi kiri. Katup menjaga aliran satu arah.","conceptName":"peredaran","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q17","package":4,"number":17,"question":"Pada sifat dominan lengkap, individu Aa disilangkan dengan aa. Peluang keturunan homozigot resesif adalah ...","options":{"A":"0%","B":"75%","C":"25%","D":"50%"},"answer":"D","answerText":"50%","modul":5,"moduleName":"Sistem Organ, Sel, dan Genetika","difficulty":"Sedang","explain":"Gamet A/a dan a menghasilkan Aa/aa sama banyak.","math":{"title":"Menurunkan peluang dengan kotak Punnett","foundation":"Tiap induk menurunkan satu alel dalam gamet. Daftar semua gamet kedua induk, gabungkan semua pasangan yang sama mungkin, lalu hitung jumlah genotipe/fenotipe sesuai pertanyaan dibagi semua kombinasi.","steps":["Hukum segregasi Mendel: setiap gamet membawa satu dari dua alel induk.","Gamet induk pertama (Aa): A dan a; gamet induk kedua (aa): a dan a.","Empat kotak Punnett yang sama peluangnya: Aa, Aa, aa, aa.","Keturunan yang memenuhi target = 2 dari 4 kemungkinan → 2/4 × 100% = 50%."],"symbol":"genetics"},"deepConcept":"Pada dominansi lengkap, alel dominan muncul pada genotipe heterozigot; fenotipe resesif membutuhkan dua alel resesif. Rasio dihitung dari probabilitas gamet dan kotak Punnett, bukan menebak dari tampilan induk.","conceptName":"genetika","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Peluang tersebut tidak sesuai dengan menghitung semua kombinasi gamet pada kotak Punnett. Keturunan yang memenuhi target = 2 dari 4 kemungkinan → 2/4 × 100% = 50%.","B":"Peluang tersebut tidak sesuai dengan menghitung semua kombinasi gamet pada kotak Punnett. Keturunan yang memenuhi target = 2 dari 4 kemungkinan → 2/4 × 100% = 50%.","C":"Peluang tersebut tidak sesuai dengan menghitung semua kombinasi gamet pada kotak Punnett. Keturunan yang memenuhi target = 2 dari 4 kemungkinan → 2/4 × 100% = 50%."}},{"id":"p4q18","package":4,"number":18,"question":"Pada hewan ruminansia, selulosa dapat dicerna terutama karena ...","options":{"A":"mikroorganisme simbiotik menghasilkan enzim selulase","B":"semua lemak berubah menjadi selulosa","C":"air liur mengandung asam klorida kuat","D":"sel epitel lambung menghasilkan selulase dalam jumlah besar"},"answer":"A","answerText":"mikroorganisme simbiotik menghasilkan enzim selulase","modul":3,"moduleName":"Fisiologi Hewan","difficulty":"Sulit","explain":"Mikroba rumen menghidrolisis selulosa.","deepConcept":"Pencernaan memecah molekul besar agar dapat diserap. Amilase memecah pati, pepsin memecah protein, lipase memecah trigliserida; empedu bukan enzim, tetapi mengemulsikan lemak. Vili usus memperluas luas penyerapan.","conceptName":"pencernaan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q19","package":4,"number":19,"question":"Dasar kolam jernih tampak lebih dangkal daripada kedalaman sebenarnya karena ...","options":{"A":"air kehilangan massa saat dilihat","B":"dasar kolam bergerak naik","C":"pembiasan cahaya saat keluar dari air","D":"semua sinar terpantul sempurna"},"answer":"C","answerText":"pembiasan cahaya saat keluar dari air","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sulit","explain":"Sinar dari dasar kolam berubah arah di permukaan air.","deepConcept":"Pembiasan terjadi karena kecepatan rambat cahaya berubah ketika indeks bias medium berbeda. Dari medium indeks rendah ke tinggi, sinar mendekati normal; dari tinggi ke rendah, sinar menjauhi normal.","conceptName":"bias","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q20","package":4,"number":20,"question":"Teknik DNA barcoding membantu peneliti mengidentifikasi organisme melalui ...","options":{"A":"warna wadah sampel","B":"massa alat mikroskop","C":"urutan DNA penanda yang dibandingkan dengan referensi","D":"waktu pergantian siang malam"},"answer":"C","answerText":"urutan DNA penanda yang dibandingkan dengan referensi","modul":14,"moduleName":"Kesehatan, Lingkungan, dan Teknologi","difficulty":"Sedang","explain":"Perbandingan sekuens gen spesifik mendukung identifikasi.","deepConcept":"Sensor mengubah besaran fisik/kimia/optik menjadi informasi terukur. Kamera multispektral memanfaatkan perbedaan pantulan spektral; PM2,5 mengacu pada partikel dengan diameter aerodinamis tidak lebih dari 2,5 μm.","conceptName":"sensor","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q21","package":4,"number":21,"question":"Sebuah papan miring ideal panjang 4 m digunakan menaikkan beban setinggi 1 m. Keuntungan mekanik idealnya adalah ...","options":{"A":"8","B":"2","C":"4","D":"1"},"answer":"C","answerText":"4","modul":6,"moduleName":"Mekanika","difficulty":"Sulit","explain":"KM = panjang bidang / tinggi = 4.","math":{"title":"Usaha pada bidang miring tanpa gesekan","foundation":"Dengan mengabaikan gesekan dan perubahan energi kinetik, usaha masuk F × s sama dengan kenaikan energi potensial W × h. Jadi F = W h/s dan keuntungan mekanik ideal KM = W/F = s/h.","steps":["Pada bidang miring ideal berlaku usaha masuk = kenaikan energi potensial: F s = W h.","Membagi kedua ruas dengan s: F = W h/s.","Keuntungan mekanik ideal KM = W/F = s/h.","KM = 4/1 = 4 (tanpa satuan)."],"symbol":"incline"},"deepConcept":"Pesawat sederhana menukar besar gaya dengan jarak tempuh. Pada sistem ideal, pengurangan gaya tidak menciptakan energi; usaha masuk sama dengan usaha untuk menaikkan beban.","conceptName":"pesawat","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Nilai KM = 8 tidak sama dengan rasio panjang/tinggi = 4 / 1 = 4.","B":"Nilai KM = 2 tidak sama dengan rasio panjang/tinggi = 4 / 1 = 4.","D":"Nilai KM = 1 tidak sama dengan rasio panjang/tinggi = 4 / 1 = 4."}},{"id":"p4q22","package":4,"number":22,"question":"Organel yang memodifikasi serta mengemas protein untuk sekresi adalah ...","options":{"A":"badan Golgi","B":"vakuola kontraktil","C":"kloroplas","D":"sentrosom"},"answer":"A","answerText":"badan Golgi","modul":5,"moduleName":"Sistem Organ, Sel, dan Genetika","difficulty":"Mudah","explain":"Golgi memodifikasi dan menyortir produk sekretori.","deepConcept":"Kloroplas menangkap energi cahaya; mitokondria menghasilkan banyak ATP melalui respirasi aerob; ribosom menyusun protein; badan Golgi memodifikasi dan mengemas produk. DNA sel eukariotik sebagian besar berada di nukleus, sedangkan bakteri memiliki nukleoid.","conceptName":"organel","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q23","package":4,"number":23,"question":"Celah pada sambungan rel kereta dibuat untuk mengantisipasi ...","options":{"A":"pemuaian logam saat suhu naik","B":"hilangnya gaya gesek sama sekali","C":"berkurangnya gravitasi","D":"perubahan massa atom spontan"},"answer":"A","answerText":"pemuaian logam saat suhu naik","modul":10,"moduleName":"Suhu dan Kalor","difficulty":"Sedang","explain":"Pemuaian dapat membuat rel melengkung tanpa celah.","deepConcept":"Kalor adalah energi yang berpindah karena beda suhu. Saat tidak terjadi perubahan wujud, Q = mcΔT; makin besar massa, kalor jenis, atau selisih suhu, makin besar energi yang diperlukan.","conceptName":"kalor","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q24","package":4,"number":24,"question":"Pasang air laut maksimum cenderung terjadi ketika ...","options":{"A":"Bumi tidak berotasi","B":"Matahari tidak memiliki gaya gravitasi","C":"Bulan selalu tepat di atas kutub","D":"Matahari, Bumi, dan Bulan hampir segaris"},"answer":"D","answerText":"Matahari, Bumi, dan Bulan hampir segaris","modul":12,"moduleName":"Bumi, Tata Surya, dan Antariksa","difficulty":"Sedang","explain":"Gaya pasang Matahari dan Bulan saling memperkuat pada fase tertentu.","deepConcept":"Gerhana Matahari terjadi ketika Bulan berada di antara Matahari–Bumi; gerhana Bulan ketika Bumi berada di antara Matahari–Bulan. Umbra merupakan bagian bayangan paling gelap.","conceptName":"gerhana","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q25","package":4,"number":25,"question":"Mata minus (miopi) umumnya dikoreksi dengan lensa ...","options":{"A":"cembung/konvergen saja","B":"silinder untuk semua kasus","C":"datar tanpa daya optik","D":"cekung/divergen"},"answer":"D","answerText":"cekung/divergen","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sulit","explain":"Lensa divergen membantu memindahkan fokus ke retina.","deepConcept":"Lensa cembung (konvergen) memusatkan berkas, sedangkan lensa cekung (divergen) menyebarkan berkas. Kamera membentuk bayangan nyata pada sensor, kaca pembesar dapat membentuk bayangan maya diperbesar.","conceptName":"lensa","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q26","package":4,"number":26,"question":"Penggunaan masker partikulat yang sesuai saat polusi asap tinggi terutama bertujuan untuk ...","options":{"A":"meniadakan semua risiko tanpa batasan","B":"membuat udara tidak mengandung oksigen","C":"mengurangi partikel terhirup","D":"meningkatkan konsentrasi polutan di paru"},"answer":"C","answerText":"mengurangi partikel terhirup","modul":14,"moduleName":"Kesehatan, Lingkungan, dan Teknologi","difficulty":"Sulit","explain":"Filtrasi partikulat dapat menurunkan pajanan partikel.","deepConcept":"Pencegahan penyakit mencakup pengendalian pajanan, sanitasi, vaksinasi, dan perawatan yang tepat. Vaksin merangsang respons imun adaptif dan memori; antibiotik hanya bermanfaat untuk infeksi yang sesuai, bukan semua penyakit.","conceptName":"kesehatan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q27","package":4,"number":27,"question":"Seorang siswa memakai tuas untuk mengangkat beban 150 N pada jarak 10 cm dari tumpu. Kuasa bekerja pada jarak 75 cm. Gaya ideal adalah ...","options":{"A":"75 N","B":"10 N","C":"150 N","D":"20 N"},"answer":"D","answerText":"20 N","modul":6,"moduleName":"Mekanika","difficulty":"Sulit","explain":"150×10 = F×75; F=20 N.","math":{"title":"Keseimbangan momen gaya","foundation":"Momen gaya terhadap titik tumpu adalah τ = F × l (lengan tegak lurus). Tuas seimbang apabila momen searah jarum jam sama dengan momen berlawanan arah: F₁l₁ = F₂l₂.","steps":["Abaikan gesekan dan massa tuas; jumlah momen terhadap titik tumpu = 0.","Momen sisi pertama = momen sisi kedua: F₁ × l₁ = F₂ × l₂.","150 × 10 = F₂ × 75 (lengan sama-sama dalam cm).","F₂ = (150 × 10)/75 = 20 N."],"symbol":"lever"},"deepConcept":"Gaya adalah besaran vektor; resultan harus mempertimbangkan arah. Benda bermassa m mengalami percepatan a menurut ΣF = ma. Gaya gesek yang melawan gerak dikurangkan dari gaya dorong.","conceptName":"gaya","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Gaya 75 N pada lengan 75 cm menghasilkan momen 5.625 N·cm, sementara momen sisi lain 1.500 N·cm. Momen belum seimbang.","B":"Gaya 10 N pada lengan 75 cm menghasilkan momen 750 N·cm, sementara momen sisi lain 1.500 N·cm. Momen belum seimbang.","C":"Gaya 150 N pada lengan 75 cm menghasilkan momen 11.250 N·cm, sementara momen sisi lain 1.500 N·cm. Momen belum seimbang."}},{"id":"p4q28","package":4,"number":28,"question":"Pertemuan dua lempeng tektonik dengan satu lempeng menunjam di bawah lainnya dinamakan ...","options":{"A":"subduksi","B":"sublimasi","C":"evaporasi","D":"kondensasi"},"answer":"A","answerText":"subduksi","modul":12,"moduleName":"Bumi, Tata Surya, dan Antariksa","difficulty":"Sedang","explain":"Subduksi adalah penunjaman lempeng.","deepConcept":"Litosfer tersusun dari lempeng yang bergerak; zona subduksi muncul saat satu lempeng menunjam. Cuaca terutama berlangsung di troposfer; aktivitas geotermal terjadi akibat panas dari dalam Bumi.","conceptName":"bumi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q29","package":4,"number":29,"question":"Jamur dikelompokkan terpisah dari tumbuhan hijau karena jamur ...","options":{"A":"memiliki klorofil a dan b","B":"bersifat heterotrof dan tidak berklorofil","C":"tidak mempunyai sel","D":"selalu bergerak aktif"},"answer":"B","answerText":"bersifat heterotrof dan tidak berklorofil","modul":2,"moduleName":"Keanekaragaman dan Klasifikasi","difficulty":"Mudah","explain":"Jamur memerlukan bahan organik dari sumber lain.","deepConcept":"Pengelompokan organisme didasarkan pada kumpulan karakter diagnostik, bukan satu ciri acak. Contohnya bulu sejati pada Aves, eksoskeleton kitin dan ruas kaki pada Arthropoda, serta klorofil pada tumbuhan hijau.","conceptName":"kelompok","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q30","package":4,"number":30,"question":"Rangkaian seri berisi 3 Ω dan 9 Ω serta baterai 24 V. Arus yang melalui keduanya adalah ...","options":{"A":"8 A","B":"2 A","C":"6 A","D":"1 A"},"answer":"B","answerText":"2 A","modul":8,"moduleName":"Listrik dan Magnet","difficulty":"Sedang","explain":"R total=12 Ω; I=24/12=2 A dan sama di kedua resistor.","math":{"title":"Mengapa hambatan seri dijumlahkan?","foundation":"Arus I sama melalui setiap resistor seri; tegangan sumber terbagi: V total = V₁+V₂+… = IR₁+IR₂+… = I(R₁+R₂+…). Membagi kedua ruas dengan I menghasilkan R total = ΣR.","steps":["Arus pada semua resistor seri sama.","Tegangan total V = Σ(IRᵢ) = I ΣRᵢ → R total = ΣRᵢ.","R total = 3 + 9 = 12 Ω.","I = V/R total = 24/12 = 2 A. Arus ini sama pada setiap resistor seri."],"symbol":"series"},"deepConcept":"Rangkaian seri memiliki arus yang sama dan tegangan terbagi, sehingga R total dijumlahkan. Rangkaian paralel memiliki tegangan yang sama dan arus terbagi, sehingga kebalikan hambatan dijumlahkan.","conceptName":"rangkaian","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Arus 8 A akan memerlukan tegangan V = IR = 8×12 = 96 V, tidak sama dengan baterai 24 V.","C":"Arus 6 A akan memerlukan tegangan V = IR = 6×12 = 72 V, tidak sama dengan baterai 24 V.","D":"Arus 1 A akan memerlukan tegangan V = IR = 1×12 = 12 V, tidak sama dengan baterai 24 V."}},{"id":"p4q31","package":4,"number":31,"question":"Berdasarkan observasi, siswa menduga bahwa jumlah oksigen terlarut menurun pada pagi hari. Pernyataan ini adalah ...","options":{"A":"kesimpulan akhir","B":"variabel terikat","C":"hasil pengukuran langsung","D":"hipotesis"},"answer":"D","answerText":"hipotesis","modul":1,"moduleName":"Keterampilan dan Metode Ilmiah","difficulty":"Sedang","explain":"Dugaan sementara yang dapat diuji disebut hipotesis.","deepConcept":"Hipotesis adalah dugaan yang dapat diuji dengan data; observasi adalah hasil pengamatan. Kesimpulan dibuat setelah membandingkan bukti dengan prediksi.","conceptName":"hipotesis","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q32","package":4,"number":32,"question":"Imunitas aktif setelah vaksinasi berbeda dari antibodi suntikan karena tubuh ...","options":{"A":"membentuk respons imun dan memori sendiri","B":"menghentikan sintesis antibodi selamanya","C":"selalu memperoleh sel darah merah donor","D":"tidak memiliki sistem imun"},"answer":"A","answerText":"membentuk respons imun dan memori sendiri","modul":14,"moduleName":"Kesehatan, Lingkungan, dan Teknologi","difficulty":"Sedang","explain":"Vaksinasi menstimulasi imun aktif.","deepConcept":"Pencegahan penyakit mencakup pengendalian pajanan, sanitasi, vaksinasi, dan perawatan yang tepat. Vaksin merangsang respons imun adaptif dan memori; antibiotik hanya bermanfaat untuk infeksi yang sesuai, bukan semua penyakit.","conceptName":"kesehatan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q33","package":4,"number":33,"question":"Perahu menempuh 2,4 km dalam 8 menit. Kelajuan rata-ratanya dalam m/s adalah ...","options":{"A":"2 m/s","B":"5 m/s","C":"8 m/s","D":"30 m/s"},"answer":"B","answerText":"5 m/s","modul":6,"moduleName":"Mekanika","difficulty":"Sedang","explain":"2,4 km = 2.400 m; 8 menit = 480 s; v = 5 m/s.","math":{"title":"Kelajuan dari definisi gerak","foundation":"Kelajuan rata-rata didefinisikan sebagai total jarak dibagi total waktu: v = s/t. Jika jarak dan waktu memakai satuan yang tidak cocok, konversikan terlebih dahulu.","steps":["Besaran diketahui: jarak s = 2,4 km; waktu t = 8 menit.","Definisi kelajuan rata-rata: v = s/t.","Samakan satuan: s = 2.400 m dan t = 480 s.","v = 2.400/480 = 5 m/s."],"symbol":"speed"},"deepConcept":"Kelajuan rata-rata memakai jarak tempuh total dibagi durasi total. Untuk memperoleh m/s, pakai meter dan detik; 1 km = 1.000 m dan 1 menit = 60 detik.","conceptName":"kelajuan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Nilai 2 m/s tidak sama dengan s/t = 2.400/480 = 5 m/s untuk data pada soal.","C":"Nilai 8 m/s tidak sama dengan s/t = 2.400/480 = 5 m/s untuk data pada soal.","D":"Nilai 30 m/s tidak sama dengan s/t = 2.400/480 = 5 m/s untuk data pada soal."}},{"id":"p4q34","package":4,"number":34,"question":"Kincir air menerima energi aliran 250 J dan mengubah 150 J menjadi energi berguna. Efisiensinya ...","options":{"A":"150%","B":"50%","C":"40%","D":"60%"},"answer":"D","answerText":"60%","modul":11,"moduleName":"Bentuk Energi dan Perubahannya","difficulty":"Sedang","explain":"η=150/250×100%=60%.","math":{"title":"Efisiensi dari konservasi energi","foundation":"Energi masuk tidak seluruhnya berubah menjadi keluaran yang diinginkan. Secara definisi, efisiensi η = (E berguna/E masuk)×100%. Pada alat biasa, sisanya terbuang sebagai kalor, suara, dll.","steps":["Efisiensi adalah proporsi energi masuk yang benar-benar menjadi energi berguna.","Dari definisi bagian = keluaran/masukan, sehingga η = E berguna/E masuk × 100%.","η = (150/250) × 100% = 60%.","Energi yang tidak menjadi keluaran berguna = 100 J (misalnya terdisipasi sebagai kalor)."],"symbol":"efficiency"},"deepConcept":"Energi tidak diciptakan dari ketiadaan. Efisiensi adalah persentase energi masuk yang menjadi keluaran berguna; tidak mengukur energi yang “hilang”, tetapi energi yang berpindah ke bentuk tak diinginkan.","conceptName":"energi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Efisiensi 150% menyatakan energi berguna 375 J dari masukan 250 J, padahal keluaran soal 150 J.","B":"Efisiensi 50% menyatakan energi berguna 125 J dari masukan 250 J, padahal keluaran soal 150 J.","C":"Efisiensi 40% menyatakan energi berguna 100 J dari masukan 250 J, padahal keluaran soal 150 J."}},{"id":"p4q35","package":4,"number":35,"question":"Penanaman kembali kawasan hutan gundul dengan jenis tumbuhan lokal disebut ...","options":{"A":"biomagnifikasi","B":"eutrofikasi","C":"urbanisasi","D":"reboisasi/restorasi vegetasi"},"answer":"D","answerText":"reboisasi/restorasi vegetasi","modul":13,"moduleName":"Ekologi dan Pelestarian Lingkungan","difficulty":"Sedang","explain":"Reboisasi membantu pemulihan tutupan vegetasi.","deepConcept":"Konservasi in situ melindungi spesies di habitat aslinya, sementara ex situ menjaga populasi atau plasma nutfah di luar habitat. Gangguan dan fragmentasi habitat dapat mengurangi keterhubungan populasi asli.","conceptName":"konservasi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q36","package":4,"number":36,"question":"Penyebaran biji oleh angin lebih mungkin terjadi pada biji yang ...","options":{"A":"selalu sangat berat","B":"ringan serta memiliki sayap atau rambut","C":"terbenam di dasar perairan","D":"terbungkus tempurung batu"},"answer":"B","answerText":"ringan serta memiliki sayap atau rambut","modul":2,"moduleName":"Keanekaragaman dan Klasifikasi","difficulty":"Sedang","explain":"Bentuk biji membantu diangkut udara.","deepConcept":"Ciri fisik yang serupa dapat muncul akibat adaptasi serupa pada garis keturunan berbeda (evolusi konvergen). Data DNA menjadi bukti tambahan untuk memeriksa hubungan evolusi.","conceptName":"evolusi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q37","package":4,"number":37,"question":"Arus 2 A mengalir pada resistor 7 Ω. Beda potensial adalah ...","options":{"A":"3,5 V","B":"28 V","C":"14 V","D":"7 V"},"answer":"C","answerText":"14 V","modul":8,"moduleName":"Listrik dan Magnet","difficulty":"Sedang","explain":"V=2×7=14 V.","math":{"title":"Hukum Ohm","foundation":"Untuk resistor ohmik pada kondisi tetap, tegangan V sebanding dengan arus I: V = I R. Dengan membagi kedua ruas, I = V/R atau R = V/I sesuai besaran yang ditanyakan.","steps":["Mulai dari Hukum Ohm: V = I × R.","V sudah terisolasi, cukup kalikan arus dengan hambatan.","V = 2 × 7 = 14 V."],"symbol":"ohm"},"deepConcept":"Rangkaian seri memiliki arus yang sama dan tegangan terbagi, sehingga R total dijumlahkan. Rangkaian paralel memiliki tegangan yang sama dan arus terbagi, sehingga kebalikan hambatan dijumlahkan.","conceptName":"rangkaian","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Tegangan 3,5 V tidak setara dengan hasil I×R = 2×7 = 14 V.","B":"Tegangan 28 V tidak setara dengan hasil I×R = 2×7 = 14 V.","D":"Tegangan 7 V tidak setara dengan hasil I×R = 2×7 = 14 V."}},{"id":"p4q38","package":4,"number":38,"question":"Dua resistor 10 Ω dipasang paralel pada baterai 5 V. Arus totalnya adalah ...","options":{"A":"1 A","B":"0,25 A","C":"0,5 A","D":"2 A"},"answer":"A","answerText":"1 A","modul":8,"moduleName":"Listrik dan Magnet","difficulty":"Sulit","explain":"R ekuivalen=5 Ω dan I=5/5=1 A.","math":{"title":"Mengapa rumus paralel berupa kebalikan?","foundation":"Tegangan V sama pada setiap cabang paralel; arus total adalah penjumlahan arus cabang: I = V/R₁+V/R₂. Karena I=V/R total, pembagian dengan V menghasilkan 1/R total = 1/R₁+1/R₂.","steps":["Tegangan pada setiap cabang paralel sama, sedangkan arus total adalah jumlah arus cabang.","Karena I total = Σ(V/Rᵢ) = V/R total, maka 1/R total = Σ(1/Rᵢ).","Untuk dua resistor, R total = (R₁ × R₂)/(R₁ + R₂) = (10 × 10)/(10 + 10) = 5 Ω.","I total = V/R total = 5/5 = 1 A."],"symbol":"parallel"},"deepConcept":"Rangkaian seri memiliki arus yang sama dan tegangan terbagi, sehingga R total dijumlahkan. Rangkaian paralel memiliki tegangan yang sama dan arus terbagi, sehingga kebalikan hambatan dijumlahkan.","conceptName":"rangkaian","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"B":"Arus 0,25 A membutuhkan tegangan V = I×R total = 1,25 V, tidak cocok dengan baterai 5 V.","C":"Arus 0,5 A membutuhkan tegangan V = I×R total = 2,5 V, tidak cocok dengan baterai 5 V.","D":"Arus 2 A membutuhkan tegangan V = I×R total = 10 V, tidak cocok dengan baterai 5 V."}},{"id":"p4q39","package":4,"number":39,"question":"Enzim lipase dari pankreas memecah ...","options":{"A":"pati menjadi maltosa","B":"protein menjadi polipeptida","C":"trigliserida menjadi asam lemak dan monogliserida","D":"DNA menjadi RNA"},"answer":"C","answerText":"trigliserida menjadi asam lemak dan monogliserida","modul":3,"moduleName":"Fisiologi Hewan","difficulty":"Sedang","explain":"Lipase bekerja pada lipid.","deepConcept":"Pencernaan memecah molekul besar agar dapat diserap. Amilase memecah pati, pepsin memecah protein, lipase memecah trigliserida; empedu bukan enzim, tetapi mengemulsikan lemak. Vili usus memperluas luas penyerapan.","conceptName":"pencernaan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q40","package":4,"number":40,"question":"Satelit alami terbesar planet Jupiter yang ditemukan Galileo mencakup ...","options":{"A":"Phobos","B":"Ganimede","C":"Titan","D":"Triton"},"answer":"B","answerText":"Ganimede","modul":12,"moduleName":"Bumi, Tata Surya, dan Antariksa","difficulty":"Sulit","explain":"Ganimede adalah satelit terbesar Jupiter.","deepConcept":"Rotasi Bumi menghasilkan siang–malam; revolusi Bumi bersama kemiringan sumbu rotasi menghasilkan musim. Orbit planet dan fase Bulan berbeda dari rotasi Bumi.","conceptName":"orbit","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q41","package":4,"number":41,"question":"Mikroorganisme ragi digunakan dalam pembuatan roti karena menghasilkan ...","options":{"A":"nitrogen dari fotosintesis","B":"asam klorida sebagai gas pengembang","C":"oksigen dari pembelahan atom","D":"karbon dioksida selama fermentasi"},"answer":"D","answerText":"karbon dioksida selama fermentasi","modul":5,"moduleName":"Sistem Organ, Sel, dan Genetika","difficulty":"Sulit","explain":"CO2 dari fermentasi membuat adonan mengembang.","deepConcept":"Ragi mengubah gula melalui fermentasi yang menghasilkan CO₂. Gas yang terperangkap membentuk gelembung pada adonan sehingga roti mengembang.","conceptName":"mikroba","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q42","package":4,"number":42,"question":"Akar menyerap sebagian besar air dan mineral melalui ...","options":{"A":"rambut akar","B":"mahkota bunga","C":"kutikula daun","D":"serbuk sari"},"answer":"A","answerText":"rambut akar","modul":4,"moduleName":"Fisiologi Tumbuhan","difficulty":"Mudah","explain":"Rambut akar memperbesar luas penyerapan.","deepConcept":"Rambut akar adalah perpanjangan sel epidermis akar yang memperluas bidang kontak dengan air tanah. Air memasuki sel terutama melalui osmosis, sedangkan ion mineral dapat diambil melalui mekanisme transport membran; air kemudian masuk ke xilem untuk dialirkan ke bagian atas.","conceptName":"penyerapan akar","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q43","package":4,"number":43,"question":"Saat anafase mitosis, peristiwa utama adalah ...","options":{"A":"membran inti terbentuk sempurna","B":"kromatid saudara berpisah menuju kutub berlawanan","C":"DNA baru mulai mengalami replikasi","D":"kromosom tidak bergerak"},"answer":"B","answerText":"kromatid saudara berpisah menuju kutub berlawanan","modul":5,"moduleName":"Sistem Organ, Sel, dan Genetika","difficulty":"Sedang","explain":"Kromatid saudara ditarik ke kutub sel.","deepConcept":"Mitosis menghasilkan sel anak dengan jumlah kromosom umumnya sama, sedangkan meiosis mengurangi jumlah kromosom menjadi separuh. Sebelum pembelahan, DNA direplikasi pada fase S; kromosom sejajar pada metafase dan kromatid saudara berpisah pada anafase mitosis.","conceptName":"pembelahan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q44","package":4,"number":44,"question":"Tanaman kekurangan magnesium, unsur yang merupakan bagian molekul klorofil. Dampak yang mungkin terjadi adalah ...","options":{"A":"fotosintesis pasti meningkat tanpa batas","B":"daun menguning dan kapasitas fotosintesis menurun","C":"produksi klorofil bertambah otomatis","D":"batang langsung membentuk bunga"},"answer":"B","answerText":"daun menguning dan kapasitas fotosintesis menurun","modul":4,"moduleName":"Fisiologi Tumbuhan","difficulty":"Sedang","explain":"Mg penting untuk pembentukan klorofil.","deepConcept":"Fotosintesis memerlukan cahaya, CO₂, air, pigmen, dan enzim. Laju fotosintesis dibatasi faktor yang paling tidak mencukupi; peningkatan cahaya tidak lagi menaikkan laju jika faktor lain menjadi batas.","conceptName":"fotosintesis","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q45","package":4,"number":45,"question":"Sinar memantul pada cermin datar dengan sudut pantul 35° terhadap normal. Sudut datang adalah ...","options":{"A":"55°","B":"70°","C":"35°","D":"17,5°"},"answer":"C","answerText":"35°","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sedang","explain":"Sudut datang sama dengan sudut pantul.","math":{"title":"Hukum pemantulan pada cermin datar","foundation":"Sudut datang dan sudut pantul selalu diukur terhadap garis normal (tegak lurus cermin). Hukum pemantulan: i = r. Jika sudut diberikan terhadap permukaan cermin, ubah menjadi i = 90° − sudut permukaan.","steps":["Garis normal selalu tegak lurus permukaan cermin.","Hukum pemantulan: sudut datang i sama dengan sudut pantul r, keduanya terhadap normal.","Sudut pantul r = i (atau sudut datang i = r).","Hasil = 35°."],"symbol":"reflect"},"deepConcept":"Pada cermin datar, sudut datang sama dengan sudut pantul jika diukur dari garis normal. Pada cermin cembung, sinar pantul menyebar sehingga bidang pandang menjadi luas.","conceptName":"pantul","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Sudut 55° tidak sesuai dengan hukum pemantulan untuk sudut terhadap normal 35°. Hubungan sudut yang diminta menghasilkan 35°.","B":"Sudut 70° tidak sesuai dengan hukum pemantulan untuk sudut terhadap normal 35°. Hubungan sudut yang diminta menghasilkan 35°.","D":"Sudut 17,5° tidak sesuai dengan hukum pemantulan untuk sudut terhadap normal 35°. Hubungan sudut yang diminta menghasilkan 35°."}},{"id":"p4q46","package":4,"number":46,"question":"Dalam sistem hidrolik ideal, A1=6 cm² dan A2=90 cm². Jika F1=30 N, maka F2 adalah ...","options":{"A":"270 N","B":"900 N","C":"150 N","D":"450 N"},"answer":"D","answerText":"450 N","modul":7,"moduleName":"Wujud Benda dan Fluida","difficulty":"Sulit","explain":"F2=30×90/6=450.","math":{"title":"Penurunan hukum Pascal","foundation":"Dalam fluida tertutup yang ideal, tambahan tekanan diteruskan sama besar: p₁ = p₂. Karena p = F/A, diperoleh F₁/A₁ = F₂/A₂. Piston berluas lebih besar menghasilkan gaya lebih besar.","steps":["Tekanan sama: F₁/A₁ = F₂/A₂.","Susun ulang sesuai gaya yang dicari: F₂ = F₁ × (A₂/A₁), atau F₁ = F₂ × (A₁/A₂).","F₂ = 30 × (90/6) = 450 N.","Perbandingan luas bebas satuan karena pembilang dan penyebut memakai cm² yang sama."],"symbol":"pascal"},"deepConcept":"Hukum Pascal menghubungkan kenaikan tekanan yang sama dalam fluida tertutup. Karena p = F/A, perbandingan gaya piston sebanding perbandingan luasnya; hasil ideal mengabaikan gesekan.","conceptName":"hidrolik","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Gaya keluaran 270 N memberi tekanan di piston besar F₂/A₂ = 270/90 = 3 N/cm², berbeda dari tekanan masuk 5 N/cm².","B":"Gaya keluaran 900 N memberi tekanan di piston besar F₂/A₂ = 900/90 = 10 N/cm², berbeda dari tekanan masuk 5 N/cm².","C":"Gaya keluaran 150 N memberi tekanan di piston besar F₂/A₂ = 150/90 = 1,66667 N/cm², berbeda dari tekanan masuk 5 N/cm²."}},{"id":"p4q47","package":4,"number":47,"question":"Dua hewan berada dalam genus yang sama, tetapi berbeda spesies. Pernyataan yang dapat disimpulkan adalah ...","options":{"A":"keduanya pasti berada pada habitat sama","B":"keduanya pasti dapat menghasilkan keturunan fertil","C":"keduanya juga berada dalam famili yang sama","D":"keduanya memiliki warna tubuh sama"},"answer":"C","answerText":"keduanya juga berada dalam famili yang sama","modul":2,"moduleName":"Keanekaragaman dan Klasifikasi","difficulty":"Sulit","explain":"Genus merupakan bagian dari satu famili dalam klasifikasi bertingkat.","deepConcept":"Urutan takson dari luas ke sempit ialah kingdom–filum–kelas–ordo–famili–genus–spesies. Makin dekat nenek moyang bersama suatu pasangan organisme, makin dekat pula hubungan evolusionernya.","conceptName":"taksonomi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q48","package":4,"number":48,"question":"Organisme mikroskopis dengan inti sel sejati, sebagian hidup sebagai plankton, termasuk kelompok ...","options":{"A":"protista eukariotik","B":"bakteri prokariotik saja","C":"semua jamur multiseluler","D":"virus"},"answer":"A","answerText":"protista eukariotik","modul":2,"moduleName":"Keanekaragaman dan Klasifikasi","difficulty":"Sedang","explain":"Beragam protista adalah organisme eukariotik mikroskopis.","deepConcept":"Pengelompokan organisme didasarkan pada kumpulan karakter diagnostik, bukan satu ciri acak. Contohnya bulu sejati pada Aves, eksoskeleton kitin dan ruas kaki pada Arthropoda, serta klorofil pada tumbuhan hijau.","conceptName":"kelompok","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q49","package":4,"number":49,"question":"Fungsi utama nefron pada ginjal adalah ...","options":{"A":"menyaring darah dan mengatur reabsorpsi zat","B":"memompa darah ke seluruh tubuh","C":"menghasilkan empedu","D":"mengubah oksigen menjadi glukosa"},"answer":"A","answerText":"menyaring darah dan mengatur reabsorpsi zat","modul":3,"moduleName":"Fisiologi Hewan","difficulty":"Sedang","explain":"Nefron membentuk urine melalui filtrasi dan proses lanjutan.","deepConcept":"Aliran darah sistemik: bilik kiri → aorta → jaringan → vena kava → serambi kanan. Aliran pulmonal: bilik kanan → arteri pulmonalis → paru-paru → vena pulmonalis → serambi kiri. Katup menjaga aliran satu arah.","conceptName":"peredaran","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p4q50","package":4,"number":50,"question":"Agar elektromagnet pada kumparan lebih kuat, tindakan yang sesuai adalah ...","options":{"A":"mengurangi arus sampai nol","B":"mengganti inti besi dengan udara dan mengurangi lilitan","C":"memutus semua sambungan baterai","D":"menambah jumlah lilitan dengan kondisi lain tetap"},"answer":"D","answerText":"menambah jumlah lilitan dengan kondisi lain tetap","modul":8,"moduleName":"Listrik dan Magnet","difficulty":"Sedang","explain":"Lebih banyak lilitan dapat meningkatkan medan magnet.","deepConcept":"Muatan bergerak/arus membentuk medan magnet. Arah medan di kumparan ditentukan arah arus; membalik arus dapat menukar kutub, sedangkan memperbanyak lilitan dapat memperkuat medan dengan kondisi lain tetap.","conceptName":"magnet","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q1","package":5,"number":1,"question":"Jonjot usus halus berfungsi meningkatkan ...","options":{"A":"kecepatan denyut jantung secara langsung","B":"luas permukaan penyerapan nutrien","C":"kekuatan otot rangka","D":"produksi empedu oleh usus"},"answer":"B","answerText":"luas permukaan penyerapan nutrien","modul":3,"moduleName":"Fisiologi Hewan","difficulty":"Sedang","explain":"Vili memperbesar bidang absorpsi.","deepConcept":"Pencernaan memecah molekul besar agar dapat diserap. Amilase memecah pati, pepsin memecah protein, lipase memecah trigliserida; empedu bukan enzim, tetapi mengemulsikan lemak. Vili usus memperluas luas penyerapan.","conceptName":"pencernaan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q2","package":5,"number":2,"question":"Populasi herbivora meningkat sangat cepat saat predator berkurang. Dampak awal yang mungkin terjadi adalah ...","options":{"A":"tumbuhan pasti menjadi tak terbatas","B":"seluruh energi ekosistem meningkat tanpa sumber","C":"keanekaragaman otomatis meningkat selalu","D":"tekanan penggembalaan terhadap vegetasi bertambah"},"answer":"D","answerText":"tekanan penggembalaan terhadap vegetasi bertambah","modul":13,"moduleName":"Ekologi dan Pelestarian Lingkungan","difficulty":"Sulit","explain":"Lebih banyak herbivora dapat meningkatkan konsumsi tumbuhan.","deepConcept":"Ukuran populasi berubah oleh kelahiran, kematian, migrasi, ketersediaan sumber daya, dan tekanan pemangsaan. Dampak perubahan satu populasi dapat merambat ke tingkat trofik lain.","conceptName":"populasi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q3","package":5,"number":3,"question":"Daun putri malu mengatup cepat setelah disentuh. Gerak ini termasuk ...","options":{"A":"tigmonasti","B":"fototropisme","C":"kemotropisme","D":"gravitropisme"},"answer":"A","answerText":"tigmonasti","modul":4,"moduleName":"Fisiologi Tumbuhan","difficulty":"Sedang","explain":"Gerak nasti tidak ditentukan arah datangnya rangsang.","deepConcept":"Gerak nasti tidak ditentukan arah datangnya rangsang. Mengatupnya putri malu setelah disentuh terutama akibat perubahan tekanan turgor pada jaringan motorik, bukan pertumbuhan memanjang.","conceptName":"nasti","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q4","package":5,"number":4,"question":"Bidang miring licin panjang 6 m dan tinggi 2 m digunakan menaikkan beban 300 N. Besar kuasa ideal sejajar bidang adalah ...","options":{"A":"150 N","B":"100 N","C":"50 N","D":"900 N"},"answer":"B","answerText":"100 N","modul":6,"moduleName":"Mekanika","difficulty":"Sulit","explain":"W×h=F×s, jadi F=300×2/6=100 N.","math":{"title":"Usaha pada bidang miring tanpa gesekan","foundation":"Dengan mengabaikan gesekan dan perubahan energi kinetik, usaha masuk F × s sama dengan kenaikan energi potensial W × h. Jadi F = W h/s dan keuntungan mekanik ideal KM = W/F = s/h.","steps":["Pada bidang miring ideal berlaku usaha masuk = kenaikan energi potensial: F s = W h.","Membagi kedua ruas dengan s: F = W h/s.","Keuntungan mekanik ideal KM = W/F = s/h.","F = 300 × 2/6 = 100 N."],"symbol":"incline"},"deepConcept":"Pesawat sederhana menukar besar gaya dengan jarak tempuh. Pada sistem ideal, pengurangan gaya tidak menciptakan energi; usaha masuk sama dengan usaha untuk menaikkan beban.","conceptName":"pesawat","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Jika gaya 150 N digunakan sepanjang 6 m, usaha masuk = 900 J. Beban butuh usaha 600 J untuk naik setinggi 2 m.","C":"Jika gaya 50 N digunakan sepanjang 6 m, usaha masuk = 300 J. Beban butuh usaha 600 J untuk naik setinggi 2 m.","D":"Jika gaya 900 N digunakan sepanjang 6 m, usaha masuk = 5.400 J. Beban butuh usaha 600 J untuk naik setinggi 2 m."}},{"id":"p5q5","package":5,"number":5,"question":"Salah satu prinsip pengendalian vektor penyakit tanpa ketergantungan tunggal pada insektisida adalah ...","options":{"A":"menyimpan semua ban bekas berisi air","B":"manajemen lingkungan untuk mengurangi habitat perindukan","C":"membiarkan larva berkembang","D":"menambah tempat genangan di rumah"},"answer":"B","answerText":"manajemen lingkungan untuk mengurangi habitat perindukan","modul":14,"moduleName":"Kesehatan, Lingkungan, dan Teknologi","difficulty":"Sulit","explain":"Menghilangkan tempat perindukan mengendalikan populasi vektor.","deepConcept":"Pencegahan penyakit mencakup pengendalian pajanan, sanitasi, vaksinasi, dan perawatan yang tepat. Vaksin merangsang respons imun adaptif dan memori; antibiotik hanya bermanfaat untuk infeksi yang sesuai, bukan semua penyakit.","conceptName":"kesehatan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q6","package":5,"number":6,"question":"Tumbuhan gurun memiliki daun kecil atau duri serta kutikula tebal. Kombinasi ini terutama membantu ...","options":{"A":"menekan kehilangan air melalui transpirasi","B":"menghasilkan air dari tanah tanpa penyerapan","C":"menghilangkan kebutuhan cahaya","D":"mengubah akar menjadi bunga"},"answer":"A","answerText":"menekan kehilangan air melalui transpirasi","modul":4,"moduleName":"Fisiologi Tumbuhan","difficulty":"Sulit","explain":"Luas permukaan kecil dan kutikula mengurangi penguapan.","deepConcept":"Tumbuhan mengendalikan neraca air melalui akar, stomata, dan kutikula. Luas daun yang kecil serta kutikula tebal mengurangi kehilangan air; penutupan stomata juga dapat mengurangi masuknya CO₂.","conceptName":"air","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q7","package":5,"number":7,"question":"Saat berolahraga, denyut jantung cenderung meningkat untuk ...","options":{"A":"meningkatkan suplai oksigen dan nutrien ke jaringan","B":"menghentikan kerja otot","C":"mengurangi transportasi karbon dioksida","D":"mencegah darah mencapai otot"},"answer":"A","answerText":"meningkatkan suplai oksigen dan nutrien ke jaringan","modul":3,"moduleName":"Fisiologi Hewan","difficulty":"Sedang","explain":"Kebutuhan metabolik otot meningkat saat aktivitas.","deepConcept":"Aliran darah sistemik: bilik kiri → aorta → jaringan → vena kava → serambi kanan. Aliran pulmonal: bilik kanan → arteri pulmonalis → paru-paru → vena pulmonalis → serambi kiri. Katup menjaga aliran satu arah.","conceptName":"peredaran","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q8","package":5,"number":8,"question":"Gelombang air berkecepatan 1,5 m/s dan panjang gelombang 0,3 m. Frekuensinya adalah ...","options":{"A":"45 Hz","B":"0,2 Hz","C":"5 Hz","D":"1,8 Hz"},"answer":"C","answerText":"5 Hz","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sedang","explain":"f=1,5/0,3=5 Hz.","math":{"title":"Hubungan panjang gelombang, frekuensi, dan cepat rambat","foundation":"Dalam satu periode T, gelombang menempuh satu panjang gelombang λ. Karena v = jarak/waktu = λ/T dan f=1/T, diperoleh v = fλ; bentuk lainnya f = v/λ dan λ = v/f.","steps":["Dalam satu periode, gelombang menempuh λ sehingga v = λ/T.","Karena f = 1/T, diperoleh v = fλ.","Ubah susunan: f = v/λ.","f = 1,5/0,3 = 5 Hz."],"symbol":"wave"},"deepConcept":"Frekuensi menyatakan banyak siklus per detik; periode menyatakan durasi satu siklus, dengan f = 1/T. Kecepatan gelombang terhubung ke frekuensi dan panjang gelombang melalui v = fλ.","conceptName":"gelombang","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Frekuensi 45 Hz dengan panjang gelombang 0,3 m menghasilkan v = fλ = 13,5 m/s, bukan 1,5 m/s.","B":"Frekuensi 0,2 Hz dengan panjang gelombang 0,3 m menghasilkan v = fλ = 0,06 m/s, bukan 1,5 m/s.","D":"Frekuensi 1,8 Hz dengan panjang gelombang 0,3 m menghasilkan v = fλ = 0,54 m/s, bukan 1,5 m/s."}},{"id":"p5q9","package":5,"number":9,"question":"Tumbuhan yang menghasilkan biji tertutup dalam buah adalah kelompok ...","options":{"A":"Gymnospermae","B":"Pteridophyta","C":"Bryophyta","D":"Angiospermae"},"answer":"D","answerText":"Angiospermae","modul":2,"moduleName":"Keanekaragaman dan Klasifikasi","difficulty":"Sedang","explain":"Biji tumbuhan berbunga terlindung oleh bakal buah yang berkembang.","deepConcept":"Pengelompokan organisme didasarkan pada kumpulan karakter diagnostik, bukan satu ciri acak. Contohnya bulu sejati pada Aves, eksoskeleton kitin dan ruas kaki pada Arthropoda, serta klorofil pada tumbuhan hijau.","conceptName":"kelompok","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q10","package":5,"number":10,"question":"Kelinci hitam (H) dominan terhadap putih (h). Dua kelinci Hh disilangkan. Peluang anak berfenotipe hitam adalah ...","options":{"A":"100%","B":"25%","C":"75%","D":"50%"},"answer":"C","answerText":"75%","modul":5,"moduleName":"Sistem Organ, Sel, dan Genetika","difficulty":"Sedang","explain":"Persilangan Hh menghasilkan 3 fenotipe dominan : 1 resesif.","math":{"title":"Menurunkan peluang dengan kotak Punnett","foundation":"Tiap induk menurunkan satu alel dalam gamet. Daftar semua gamet kedua induk, gabungkan semua pasangan yang sama mungkin, lalu hitung jumlah genotipe/fenotipe sesuai pertanyaan dibagi semua kombinasi.","steps":["Hukum segregasi Mendel: setiap gamet membawa satu dari dua alel induk.","Gamet induk pertama (Hh): H dan h; gamet induk kedua (Hh): H dan h.","Empat kotak Punnett yang sama peluangnya: HH, Hh, Hh, hh.","Keturunan yang memenuhi target = 3 dari 4 kemungkinan → 3/4 × 100% = 75%."],"symbol":"genetics"},"deepConcept":"Pada dominansi lengkap, alel dominan muncul pada genotipe heterozigot; fenotipe resesif membutuhkan dua alel resesif. Rasio dihitung dari probabilitas gamet dan kotak Punnett, bukan menebak dari tampilan induk.","conceptName":"genetika","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Peluang tersebut tidak sesuai dengan menghitung semua kombinasi gamet pada kotak Punnett. Keturunan yang memenuhi target = 3 dari 4 kemungkinan → 3/4 × 100% = 75%.","B":"Peluang tersebut tidak sesuai dengan menghitung semua kombinasi gamet pada kotak Punnett. Keturunan yang memenuhi target = 3 dari 4 kemungkinan → 3/4 × 100% = 75%.","D":"Peluang tersebut tidak sesuai dengan menghitung semua kombinasi gamet pada kotak Punnett. Keturunan yang memenuhi target = 3 dari 4 kemungkinan → 3/4 × 100% = 75%."}},{"id":"p5q11","package":5,"number":11,"question":"Satu langkah dalam kunci dikotomi idealnya menyajikan ...","options":{"A":"empat dugaan tanpa ciri pembeda","B":"dua ciri alternatif yang saling berlawanan","C":"hanya nama latin organisme","D":"satu ciri yang selalu benar bagi semua organisme"},"answer":"B","answerText":"dua ciri alternatif yang saling berlawanan","modul":2,"moduleName":"Keanekaragaman dan Klasifikasi","difficulty":"Mudah","explain":"Identifikasi dikotomis bekerja dengan dua pilihan yang kontras.","deepConcept":"Kunci dikotomi menggunakan sepasang ciri yang saling berlawanan pada tiap langkah agar spesimen tersaring menuju identitas yang sesuai.","conceptName":"identifikasi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q12","package":5,"number":12,"question":"Sebanyak 250 g air naik suhu 10 °C. Dengan c=4.200 J/kg°C, kalor yang diserap adalah ...","options":{"A":"42.000 J","B":"1.050 J","C":"10.500 J","D":"105.000 J"},"answer":"C","answerText":"10.500 J","modul":10,"moduleName":"Suhu dan Kalor","difficulty":"Sulit","explain":"m=0,25 kg, Q=0,25×4.200×10.","math":{"title":"Kalor jenis dan perubahan suhu","foundation":"Kalor jenis c didefinisikan sebagai energi kalor yang dibutuhkan per satuan massa untuk menaikkan suhu sebesar satu derajat: c = Q/(mΔT). Susun ulang menjadi Q = mcΔT, berlaku selama tidak ada perubahan wujud.","steps":["Definisi kalor jenis: c = Q/(mΔT).","Kalikan kedua ruas dengan mΔT → Q = mcΔT.","Massa m = 0,25 kg; kalor jenis c = 4.200 J/(kg·°C); perubahan suhu ΔT = 10 °C.","Q = 0,25 × 4.200 × 10 = 10.500 J. Satuan kg dan °C saling habis."],"symbol":"heat"},"deepConcept":"Kalor adalah energi yang berpindah karena beda suhu. Saat tidak terjadi perubahan wujud, Q = mcΔT; makin besar massa, kalor jenis, atau selisih suhu, makin besar energi yang diperlukan.","conceptName":"kalor","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Kalor 42.000 J menghasilkan ΔT = Q/(mc) = 42.000/(0,25×4.200), berbeda dari ΔT soal 10 °C. Yang memenuhi Q = mcΔT adalah 10.500 J.","B":"Kalor 1.050 J menghasilkan ΔT = Q/(mc) = 1.050/(0,25×4.200), berbeda dari ΔT soal 10 °C. Yang memenuhi Q = mcΔT adalah 10.500 J.","D":"Kalor 105.000 J menghasilkan ΔT = Q/(mc) = 105.000/(0,25×4.200), berbeda dari ΔT soal 10 °C. Yang memenuhi Q = mcΔT adalah 10.500 J."}},{"id":"p5q13","package":5,"number":13,"question":"Tumbuhan ditempatkan dalam intensitas cahaya naik, tetapi laju fotosintesis berhenti meningkat setelah titik tertentu. Penyebab yang paling logis adalah ...","options":{"A":"cahaya selalu menghentikan reaksi kimia","B":"faktor lain menjadi pembatas","C":"daun tidak menggunakan karbon dioksida","D":"fotosintesis tidak dipengaruhi intensitas cahaya"},"answer":"B","answerText":"faktor lain menjadi pembatas","modul":4,"moduleName":"Fisiologi Tumbuhan","difficulty":"Sedang","explain":"Kejenuhan terjadi ketika faktor lain membatasi proses.","deepConcept":"Fotosintesis memerlukan cahaya, CO₂, air, pigmen, dan enzim. Laju fotosintesis dibatasi faktor yang paling tidak mencukupi; peningkatan cahaya tidak lagi menaikkan laju jika faktor lain menjadi batas.","conceptName":"fotosintesis","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q14","package":5,"number":14,"question":"Planet yang termasuk raksasa gas adalah ...","options":{"A":"Venus","B":"Mars","C":"Merkurius","D":"Jupiter"},"answer":"D","answerText":"Jupiter","modul":12,"moduleName":"Bumi, Tata Surya, dan Antariksa","difficulty":"Sulit","explain":"Jupiter didominasi hidrogen dan helium.","deepConcept":"Rotasi Bumi menghasilkan siang–malam; revolusi Bumi bersama kemiringan sumbu rotasi menghasilkan musim. Orbit planet dan fase Bulan berbeda dari rotasi Bumi.","conceptName":"orbit","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q15","package":5,"number":15,"question":"Sinar datang menumbuk cermin datar tegak lurus permukaan. Sudut pantul terhadap normal adalah ...","options":{"A":"90°","B":"45°","C":"0°","D":"180°"},"answer":"C","answerText":"0°","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sedang","explain":"Sinar datang sepanjang normal dipantulkan kembali pada jalurnya.","math":{"title":"Hukum pemantulan pada cermin datar","foundation":"Sudut datang dan sudut pantul selalu diukur terhadap garis normal (tegak lurus cermin). Hukum pemantulan: i = r. Jika sudut diberikan terhadap permukaan cermin, ubah menjadi i = 90° − sudut permukaan.","steps":["Garis normal selalu tegak lurus permukaan cermin.","Hukum pemantulan: sudut datang i sama dengan sudut pantul r, keduanya terhadap normal.","Sudut pantul r = i (atau sudut datang i = r).","Hasil = 0°."],"symbol":"reflect"},"deepConcept":"Pada cermin datar, sudut datang sama dengan sudut pantul jika diukur dari garis normal. Pada cermin cembung, sinar pantul menyebar sehingga bidang pandang menjadi luas.","conceptName":"pantul","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Sudut 90° tidak sesuai dengan hukum pemantulan untuk sudut terhadap normal 0°. Hubungan sudut yang diminta menghasilkan 0°.","B":"Sudut 45° tidak sesuai dengan hukum pemantulan untuk sudut terhadap normal 0°. Hubungan sudut yang diminta menghasilkan 0°.","D":"Sudut 180° tidak sesuai dengan hukum pemantulan untuk sudut terhadap normal 0°. Hubungan sudut yang diminta menghasilkan 0°."}},{"id":"p5q16","package":5,"number":16,"question":"Sel tumbuhan cenderung lebih kaku dibanding sel hewan karena memiliki ...","options":{"A":"dinding sel tersusun terutama dari selulosa","B":"mitokondria yang hanya ada pada tumbuhan","C":"ribosom yang hanya ada pada tumbuhan","D":"membran plasma dua lapis pada tumbuhan saja"},"answer":"A","answerText":"dinding sel tersusun terutama dari selulosa","modul":5,"moduleName":"Sistem Organ, Sel, dan Genetika","difficulty":"Sulit","explain":"Dinding sel memberikan dukungan mekanis.","deepConcept":"Kloroplas menangkap energi cahaya; mitokondria menghasilkan banyak ATP melalui respirasi aerob; ribosom menyusun protein; badan Golgi memodifikasi dan mengemas produk. DNA sel eukariotik sebagian besar berada di nukleus, sedangkan bakteri memiliki nukleoid.","conceptName":"organel","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q17","package":5,"number":17,"question":"Tindakan paling tepat untuk menekan sampah plastik yang mencapai sungai adalah ...","options":{"A":"membuang plastik ke saluran saat hujan","B":"mengurangi plastik sekali pakai dan mengelola sampah dari sumbernya","C":"membiarkan sampah terurai sendiri dalam sehari","D":"membakar plastik di tepi sungai"},"answer":"B","answerText":"mengurangi plastik sekali pakai dan mengelola sampah dari sumbernya","modul":13,"moduleName":"Ekologi dan Pelestarian Lingkungan","difficulty":"Sedang","explain":"Pengurangan di sumber dan pengelolaan mencegah sampah masuk perairan.","deepConcept":"Polutan yang dimakan organisme dapat berpindah mengikuti aliran materi pada jaring makanan. Mengurangi input polutan dari sumbernya adalah strategi penting perlindungan ekosistem.","conceptName":"pencemar","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q18","package":5,"number":18,"question":"Klasifikasi modern yang memadukan morfologi dengan DNA bertujuan terutama untuk ...","options":{"A":"menilai hubungan kekerabatan lebih akurat","B":"membuat semua organisme memiliki bentuk identik","C":"menghapus perbedaan spesies","D":"mengubah DNA setiap organisme"},"answer":"A","answerText":"menilai hubungan kekerabatan lebih akurat","modul":2,"moduleName":"Keanekaragaman dan Klasifikasi","difficulty":"Sedang","explain":"Data molekuler melengkapi ciri morfologis dalam filogeni.","deepConcept":"Urutan takson dari luas ke sempit ialah kingdom–filum–kelas–ordo–famili–genus–spesies. Makin dekat nenek moyang bersama suatu pasangan organisme, makin dekat pula hubungan evolusionernya.","conceptName":"taksonomi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q19","package":5,"number":19,"question":"Fatamorgana di jalan panas terutama berkaitan dengan ...","options":{"A":"air baru muncul di atas aspal","B":"bayangan benda yang selalu berasal dari cermin","C":"pembiasan cahaya akibat perbedaan indeks bias lapisan udara","D":"pemantulan gelombang radio semata"},"answer":"C","answerText":"pembiasan cahaya akibat perbedaan indeks bias lapisan udara","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sulit","explain":"Gradien suhu udara menimbulkan gradien indeks bias.","deepConcept":"Pembiasan terjadi karena kecepatan rambat cahaya berubah ketika indeks bias medium berbeda. Dari medium indeks rendah ke tinggi, sinar mendekati normal; dari tinggi ke rendah, sinar menjauhi normal.","conceptName":"bias","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q20","package":5,"number":20,"question":"Seorang siswa mencatat suhu air 25 °C, 27 °C, dan 29 °C pada tiga waktu. Data tersebut tergolong ...","options":{"A":"kualitatif","B":"kuantitatif","C":"opini","D":"hipotesis"},"answer":"B","answerText":"kuantitatif","modul":1,"moduleName":"Keterampilan dan Metode Ilmiah","difficulty":"Sedang","explain":"Data yang berbentuk angka adalah data kuantitatif.","deepConcept":"Data kuantitatif berupa besaran terukur (angka dan satuan), sedangkan data kualitatif berupa kategori atau deskripsi. Data terukur perlu dicatat dengan satuan dan kondisi pengukuran.","conceptName":"data","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q21","package":5,"number":21,"question":"Pemanasan air tanah oleh aktivitas geotermal dapat membentuk semburan air panas periodik yang disebut ...","options":{"A":"dune","B":"delta","C":"stalaktit","D":"geyser"},"answer":"D","answerText":"geyser","modul":12,"moduleName":"Bumi, Tata Surya, dan Antariksa","difficulty":"Sedang","explain":"Geyser meletus akibat tekanan dan pemanasan air bawah tanah.","deepConcept":"Litosfer tersusun dari lempeng yang bergerak; zona subduksi muncul saat satu lempeng menunjam. Cuaca terutama berlangsung di troposfer; aktivitas geotermal terjadi akibat panas dari dalam Bumi.","conceptName":"bumi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q22","package":5,"number":22,"question":"Jika katup antara serambi dan bilik kiri gagal menutup sempurna, saat bilik berkontraksi darah dapat ...","options":{"A":"berubah menjadi cairan limfa","B":"mengalir dari paru-paru ke insang","C":"mengalir balik ke serambi kiri","D":"berhenti mengandung hemoglobin"},"answer":"C","answerText":"mengalir balik ke serambi kiri","modul":3,"moduleName":"Fisiologi Hewan","difficulty":"Sulit","explain":"Insufisiensi katup mitral memicu regurgitasi.","deepConcept":"Aliran darah sistemik: bilik kiri → aorta → jaringan → vena kava → serambi kanan. Aliran pulmonal: bilik kanan → arteri pulmonalis → paru-paru → vena pulmonalis → serambi kiri. Katup menjaga aliran satu arah.","conceptName":"peredaran","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q23","package":5,"number":23,"question":"Grafik memperlihatkan massa tanaman naik seiring penambahan pupuk, lalu turun pada dosis sangat tinggi. Kesimpulan paling tepat adalah ...","options":{"A":"semua dosis menghasilkan massa identik","B":"semakin banyak pupuk pasti selalu lebih baik","C":"pupuk tidak memengaruhi pertumbuhan","D":"terdapat dosis optimum dalam rentang yang diuji"},"answer":"D","answerText":"terdapat dosis optimum dalam rentang yang diuji","modul":1,"moduleName":"Keterampilan dan Metode Ilmiah","difficulty":"Sulit","explain":"Respons yang berbalik menunjukkan kemungkinan titik optimum.","deepConcept":"Variabel bebas adalah faktor yang sengaja diubah; variabel terikat adalah hasil yang diukur; variabel kontrol adalah faktor lain yang dibuat tetap. Perbandingan bermakna jika perlakuan berbeda pada satu faktor utama saja.","conceptName":"variabel","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q24","package":5,"number":24,"question":"Pertukaran oksigen dan karbon dioksida antara darah dan alveolus terjadi melalui ...","options":{"A":"difusi","B":"fotosintesis","C":"endositosis partikel besar","D":"osmosis mineral saja"},"answer":"A","answerText":"difusi","modul":3,"moduleName":"Fisiologi Hewan","difficulty":"Mudah","explain":"Gas bergerak menurut gradien tekanan parsial.","deepConcept":"Aliran darah sistemik: bilik kiri → aorta → jaringan → vena kava → serambi kanan. Aliran pulmonal: bilik kanan → arteri pulmonalis → paru-paru → vena pulmonalis → serambi kiri. Katup menjaga aliran satu arah.","conceptName":"peredaran","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q25","package":5,"number":25,"question":"Tempat penyimpanan DNA utama dalam sel hewan adalah ...","options":{"A":"dinding sel","B":"vakuola tengah","C":"nukleus","D":"klorofil"},"answer":"C","answerText":"nukleus","modul":5,"moduleName":"Sistem Organ, Sel, dan Genetika","difficulty":"Mudah","explain":"Inti sel menyimpan mayoritas materi genetik sel hewan.","deepConcept":"Kloroplas menangkap energi cahaya; mitokondria menghasilkan banyak ATP melalui respirasi aerob; ribosom menyusun protein; badan Golgi memodifikasi dan mengemas produk. DNA sel eukariotik sebagian besar berada di nukleus, sedangkan bakteri memiliki nukleoid.","conceptName":"organel","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q26","package":5,"number":26,"question":"Balon udara panas naik karena udara di dalam balon setelah dipanaskan menjadi ...","options":{"A":"tidak mempunyai massa sama sekali","B":"bermassa jenis lebih tinggi","C":"bermassa jenis lebih rendah daripada udara sekitarnya","D":"menjadi padat"},"answer":"C","answerText":"bermassa jenis lebih rendah daripada udara sekitarnya","modul":10,"moduleName":"Suhu dan Kalor","difficulty":"Sedang","explain":"Udara hangat mengembang sehingga ρ menurun.","deepConcept":"Kalor adalah energi yang berpindah karena beda suhu. Saat tidak terjadi perubahan wujud, Q = mcΔT; makin besar massa, kalor jenis, atau selisih suhu, makin besar energi yang diperlukan.","conceptName":"kalor","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q27","package":5,"number":27,"question":"Sumber bunyi menghasilkan 200 getaran dalam 4 s. Frekuensinya adalah ...","options":{"A":"25 Hz","B":"4 Hz","C":"800 Hz","D":"50 Hz"},"answer":"D","answerText":"50 Hz","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sedang","explain":"f=n/t=200/4=50 Hz.","math":{"title":"Frekuensi dan periode dari definisi","foundation":"Frekuensi f adalah banyaknya getaran n dalam waktu t, maka f = n/t. Periode T adalah waktu satu getaran, sehingga T = t/n = 1/f. Satuan f = hertz (Hz), T = detik (s).","steps":["Frekuensi adalah getaran per detik: f = n/t.","Periode adalah detik per getaran: T = t/n = 1/f.","Diketahui n = 200 dan t = 4 s, jadi f = 200/4 = 50 Hz."],"symbol":"frequency"},"deepConcept":"Frekuensi menyatakan banyak siklus per detik; periode menyatakan durasi satu siklus, dengan f = 1/T. Kecepatan gelombang terhubung ke frekuensi dan panjang gelombang melalui v = fλ.","conceptName":"gelombang","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Frekuensi 25 Hz akan menghasilkan n = f×t = 100 getaran selama 4 s, bukan 200 getaran.","B":"Frekuensi 4 Hz akan menghasilkan n = f×t = 16 getaran selama 4 s, bukan 200 getaran.","C":"Frekuensi 800 Hz akan menghasilkan n = f×t = 3.200 getaran selama 4 s, bukan 200 getaran."}},{"id":"p5q28","package":5,"number":28,"question":"Burung bangau memakan ikan kecil di sungai. Interaksi bangau dan ikan tersebut adalah ...","options":{"A":"predasi","B":"mutualisme","C":"komensalisme","D":"saprofitisme"},"answer":"A","answerText":"predasi","modul":13,"moduleName":"Ekologi dan Pelestarian Lingkungan","difficulty":"Sedang","explain":"Pemangsa menangkap dan memakan mangsa.","deepConcept":"Mutualisme menguntungkan kedua pihak; komensalisme menguntungkan satu pihak tanpa dampak berarti pada pihak lain; parasitisme merugikan inang; predasi membunuh/memakan mangsa; kompetisi terjadi ketika organisme memperebutkan sumber terbatas.","conceptName":"interaksi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q29","package":5,"number":29,"question":"Dua resistor seri masing-masing 15 Ω dan 5 Ω dipasang pada sumber 10 V. Kuat arusnya adalah ...","options":{"A":"0,2 A","B":"2 A","C":"0,5 A","D":"5 A"},"answer":"C","answerText":"0,5 A","modul":8,"moduleName":"Listrik dan Magnet","difficulty":"Sedang","explain":"R total=20 Ω; I=10/20=0,5 A.","math":{"title":"Mengapa hambatan seri dijumlahkan?","foundation":"Arus I sama melalui setiap resistor seri; tegangan sumber terbagi: V total = V₁+V₂+… = IR₁+IR₂+… = I(R₁+R₂+…). Membagi kedua ruas dengan I menghasilkan R total = ΣR.","steps":["Arus pada semua resistor seri sama.","Tegangan total V = Σ(IRᵢ) = I ΣRᵢ → R total = ΣRᵢ.","R total = 15 + 5 = 20 Ω.","I = V/R total = 10/20 = 0,5 A. Arus ini sama pada setiap resistor seri."],"symbol":"series"},"deepConcept":"Rangkaian seri memiliki arus yang sama dan tegangan terbagi, sehingga R total dijumlahkan. Rangkaian paralel memiliki tegangan yang sama dan arus terbagi, sehingga kebalikan hambatan dijumlahkan.","conceptName":"rangkaian","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Arus 0,2 A akan memerlukan tegangan V = IR = 0,2×20 = 4 V, tidak sama dengan baterai 10 V.","B":"Arus 2 A akan memerlukan tegangan V = IR = 2×20 = 40 V, tidak sama dengan baterai 10 V.","D":"Arus 5 A akan memerlukan tegangan V = IR = 5×20 = 100 V, tidak sama dengan baterai 10 V."}},{"id":"p5q30","package":5,"number":30,"question":"Tekanan hidrostatis di dasar wadah minyak dengan ρ=800 kg/m³, tinggi cairan 2 m, g=10 m/s² adalah ...","options":{"A":"1.600 Pa","B":"16.000 Pa","C":"20.000 Pa","D":"8.000 Pa"},"answer":"B","answerText":"16.000 Pa","modul":7,"moduleName":"Wujud Benda dan Fluida","difficulty":"Sedang","explain":"p=800×10×2=16.000 Pa.","math":{"title":"Penurunan tekanan hidrostatis","foundation":"Bayangkan kolom cairan berluas A dan tinggi h. Volumenya V = Ah, massanya m = ρAh, beratnya F = mg = ρAhg. Tekanan p = F/A sehingga p = ρgh. Untuk dua titik, Δp = ρgΔh.","steps":["Tekanan kolom cairan: p = F/A. Dengan F = mg = ρAhg, maka p = ρgh.","Yang dicari tekanan hidrostatis relatif terhadap permukaan, bukan tekanan absolut.","ρ = 800 kg/m³, g = 10 m/s², h = 2 m.","p = 800 × 10 × 2 = 16.000 Pa."],"symbol":"hydro"},"deepConcept":"Tekanan hidrostatis adalah tekanan akibat berat kolom fluida di atas titik. Tekanan bertambah jika massa jenis, percepatan gravitasi, atau kedalaman meningkat.","conceptName":"hidrostatis","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Tekanan 1.600 Pa mengharuskan kedalaman h = p/(ρg) = 0,2 m, bukan 2 m.","C":"Tekanan 20.000 Pa mengharuskan kedalaman h = p/(ρg) = 2,5 m, bukan 2 m.","D":"Tekanan 8.000 Pa mengharuskan kedalaman h = p/(ρg) = 1 m, bukan 2 m."}},{"id":"p5q31","package":5,"number":31,"question":"Komunitas A memiliki empat spesies dengan jumlah individu hampir sama, sedangkan komunitas B didominasi satu spesies. Dengan kekayaan spesies sama, komunitas ...","options":{"A":"A cenderung memiliki kemerataan lebih tinggi","B":"keduanya pasti memiliki jumlah individu sama","C":"B pasti memiliki kemerataan lebih tinggi","D":"perbedaan kelimpahan tidak relevan"},"answer":"A","answerText":"A cenderung memiliki kemerataan lebih tinggi","modul":2,"moduleName":"Keanekaragaman dan Klasifikasi","difficulty":"Sulit","explain":"Kemerataan tinggi jika kelimpahan tiap spesies relatif seragam.","deepConcept":"Urutan takson dari luas ke sempit ialah kingdom–filum–kelas–ordo–famili–genus–spesies. Makin dekat nenek moyang bersama suatu pasangan organisme, makin dekat pula hubungan evolusionernya.","conceptName":"taksonomi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q32","package":5,"number":32,"question":"Pada tekanan udara lebih rendah, air umumnya mendidih pada suhu ...","options":{"A":"lebih tinggi tanpa batas","B":"selalu 0 °C","C":"selalu 100 °C","D":"lebih rendah daripada di permukaan laut"},"answer":"D","answerText":"lebih rendah daripada di permukaan laut","modul":7,"moduleName":"Wujud Benda dan Fluida","difficulty":"Sedang","explain":"Tekanan yang turun menurunkan titik didih.","deepConcept":"Tekanan hidrostatis adalah tekanan akibat berat kolom fluida di atas titik. Tekanan bertambah jika massa jenis, percepatan gravitasi, atau kedalaman meningkat.","conceptName":"hidrostatis","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q33","package":5,"number":33,"question":"Mencuci tangan memakai sabun membantu mencegah penyakit karena ...","options":{"A":"membuat tubuh steril permanen","B":"mengangkat kotoran dan mikroorganisme dari kulit","C":"menambah oksigen darah secara langsung","D":"mengganti seluruh vaksin"},"answer":"B","answerText":"mengangkat kotoran dan mikroorganisme dari kulit","modul":14,"moduleName":"Kesehatan, Lingkungan, dan Teknologi","difficulty":"Sedang","explain":"Sabun dan gesekan membantu menyingkirkan patogen.","deepConcept":"Pencegahan penyakit mencakup pengendalian pajanan, sanitasi, vaksinasi, dan perawatan yang tepat. Vaksin merangsang respons imun adaptif dan memori; antibiotik hanya bermanfaat untuk infeksi yang sesuai, bukan semua penyakit.","conceptName":"kesehatan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q34","package":5,"number":34,"question":"Organisme pengurai dalam ekosistem berfungsi utama ...","options":{"A":"menghilangkan kebutuhan fotosintesis","B":"mengubah semua konsumen menjadi produsen","C":"menghentikan daur materi","D":"mengembalikan unsur hara dari sisa organisme"},"answer":"D","answerText":"mengembalikan unsur hara dari sisa organisme","modul":13,"moduleName":"Ekologi dan Pelestarian Lingkungan","difficulty":"Sedang","explain":"Dekomposer melepaskan unsur hara ke lingkungan.","deepConcept":"Dalam rantai makanan, produsen membentuk bahan organik melalui fotosintesis, konsumen I memakan produsen, konsumen II memakan konsumen I, dan pengurai mendaur ulang unsur hara.","conceptName":"rantai","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q35","package":5,"number":35,"question":"Beban 120 N berada 15 cm di kiri tumpu, sedangkan gaya kuasa bekerja 45 cm di kanan. Gaya setimbang adalah ...","options":{"A":"60 N","B":"40 N","C":"15 N","D":"360 N"},"answer":"B","answerText":"40 N","modul":6,"moduleName":"Mekanika","difficulty":"Sulit","explain":"120×15 = F×45; F=40 N.","math":{"title":"Keseimbangan momen gaya","foundation":"Momen gaya terhadap titik tumpu adalah τ = F × l (lengan tegak lurus). Tuas seimbang apabila momen searah jarum jam sama dengan momen berlawanan arah: F₁l₁ = F₂l₂.","steps":["Abaikan gesekan dan massa tuas; jumlah momen terhadap titik tumpu = 0.","Momen sisi pertama = momen sisi kedua: F₁ × l₁ = F₂ × l₂.","120 × 15 = F₂ × 45 (lengan sama-sama dalam cm).","F₂ = (120 × 15)/45 = 40 N."],"symbol":"lever"},"deepConcept":"Gaya adalah besaran vektor; resultan harus mempertimbangkan arah. Benda bermassa m mengalami percepatan a menurut ΣF = ma. Gaya gesek yang melawan gerak dikurangkan dari gaya dorong.","conceptName":"gaya","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Gaya 60 N pada lengan 45 cm menghasilkan momen 2.700 N·cm, sementara momen sisi lain 1.800 N·cm. Momen belum seimbang.","C":"Gaya 15 N pada lengan 45 cm menghasilkan momen 675 N·cm, sementara momen sisi lain 1.800 N·cm. Momen belum seimbang.","D":"Gaya 360 N pada lengan 45 cm menghasilkan momen 16.200 N·cm, sementara momen sisi lain 1.800 N·cm. Momen belum seimbang."}},{"id":"p5q36","package":5,"number":36,"question":"Insulin yang diproduksi bakteri hasil rekayasa genetika adalah contoh penerapan ...","options":{"A":"filtrasi gravitasi","B":"bioteknologi modern","C":"pembiasan cahaya","D":"sublimasi"},"answer":"B","answerText":"bioteknologi modern","modul":14,"moduleName":"Kesehatan, Lingkungan, dan Teknologi","difficulty":"Sedang","explain":"Gen insulin dapat diekspresikan pada mikroorganisme rekombinan.","deepConcept":"Bioteknologi memanfaatkan sel atau proses biologis untuk menghasilkan produk. Fermentasi adalah proses metabolik mikroba; teknik DNA rekombinan memungkinkan produksi protein seperti insulin.","conceptName":"biotek","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q37","package":5,"number":37,"question":"Piston berpenampang 8 cm² terhubung dengan piston 160 cm². Gaya 25 N pada piston kecil menghasilkan ...","options":{"A":"1.000 N","B":"250 N","C":"125 N","D":"500 N"},"answer":"D","answerText":"500 N","modul":7,"moduleName":"Wujud Benda dan Fluida","difficulty":"Sulit","explain":"Perbandingan luas 20; gaya keluaran 25×20.","math":{"title":"Penurunan hukum Pascal","foundation":"Dalam fluida tertutup yang ideal, tambahan tekanan diteruskan sama besar: p₁ = p₂. Karena p = F/A, diperoleh F₁/A₁ = F₂/A₂. Piston berluas lebih besar menghasilkan gaya lebih besar.","steps":["Tekanan sama: F₁/A₁ = F₂/A₂.","Susun ulang sesuai gaya yang dicari: F₂ = F₁ × (A₂/A₁), atau F₁ = F₂ × (A₁/A₂).","F₂ = 25 × (160/8) = 500 N.","Perbandingan luas bebas satuan karena pembilang dan penyebut memakai cm² yang sama."],"symbol":"pascal"},"deepConcept":"Hukum Pascal menghubungkan kenaikan tekanan yang sama dalam fluida tertutup. Karena p = F/A, perbandingan gaya piston sebanding perbandingan luasnya; hasil ideal mengabaikan gesekan.","conceptName":"hidrolik","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Gaya keluaran 1.000 N memberi tekanan di piston besar F₂/A₂ = 1.000/160 = 6,25 N/cm², berbeda dari tekanan masuk 3,125 N/cm².","B":"Gaya keluaran 250 N memberi tekanan di piston besar F₂/A₂ = 250/160 = 1,5625 N/cm², berbeda dari tekanan masuk 3,125 N/cm².","C":"Gaya keluaran 125 N memberi tekanan di piston besar F₂/A₂ = 125/160 = 0,78125 N/cm², berbeda dari tekanan masuk 3,125 N/cm²."}},{"id":"p5q38","package":5,"number":38,"question":"Benda homogen bermassa 150 g dan volume 200 cm³ berada dalam air. Keadaannya adalah ...","options":{"A":"menguap","B":"tenggelam","C":"melayang dalam posisi apa pun tanpa bagian muncul","D":"terapung"},"answer":"D","answerText":"terapung","modul":7,"moduleName":"Wujud Benda dan Fluida","difficulty":"Sedang","explain":"ρ=0,75 g/cm³ lebih kecil dari air.","math":{"title":"Definisi massa jenis","foundation":"Massa jenis menyatakan berapa massa yang terdapat dalam setiap satuan volume: ρ = m/V. Satuan harus konsisten: 1.000 cm³ = 0,001 m³ dan 1 g/cm³ = 1.000 kg/m³.","steps":["Dari definisi, massa jenis ρ = massa/volume = m/V.","Gunakan satuan konsisten: m = 150 g; V = 200 cm³.","ρ = 150/200 = 0,75 g/cm³.","Bandingkan dengan massa jenis air ≈ 1 g/cm³: benda dengan ρ lebih kecil dapat terapung (jika bebas dan tidak ada faktor lain)."],"symbol":"density"},"deepConcept":"Massa jenis ρ = m/V; benda bebas dalam fluida yang massa jenisnya lebih kecil dari benda cenderung tenggelam, sebaliknya dapat terapung. Untuk benda terapung, gaya apung mengimbangi berat benda.","conceptName":"massa","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{}},{"id":"p5q39","package":5,"number":39,"question":"Pada dua magnet batang, kutub utara dan kutub utara yang didekatkan akan ...","options":{"A":"melebur menjadi satu kutub","B":"tidak mengalami gaya sama sekali","C":"tolak-menolak","D":"tarik-menarik"},"answer":"C","answerText":"tolak-menolak","modul":8,"moduleName":"Listrik dan Magnet","difficulty":"Sedang","explain":"Kutub magnet sejenis saling tolak.","deepConcept":"Muatan bergerak/arus membentuk medan magnet. Arah medan di kumparan ditentukan arah arus; membalik arus dapat menukar kutub, sedangkan memperbanyak lilitan dapat memperkuat medan dengan kondisi lain tetap.","conceptName":"magnet","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q40","package":5,"number":40,"question":"Dalam pengolahan limbah organik, digester anaerob dapat menghasilkan gas bahan bakar berupa ...","options":{"A":"metana","B":"neon","C":"helium murni","D":"ozon"},"answer":"A","answerText":"metana","modul":14,"moduleName":"Kesehatan, Lingkungan, dan Teknologi","difficulty":"Sulit","explain":"Mikroba anaerob memproduksi biogas kaya metana.","deepConcept":"Teknologi lingkungan bekerja melalui proses fisika (filtrasi), biologi (bioremediasi/digesti anaerob), dan pengendalian sumber. Pencegahan di sumber umumnya mengurangi beban pengolahan hilir.","conceptName":"lingkungan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q41","package":5,"number":41,"question":"Kereta mainan bermassa 2 kg diberi gaya tarik 14 N dan gesekan 4 N. Percepatannya adalah ...","options":{"A":"7 m/s²","B":"5 m/s²","C":"9 m/s²","D":"2 m/s²"},"answer":"B","answerText":"5 m/s²","modul":6,"moduleName":"Mekanika","difficulty":"Sedang","explain":"F net=10 N; a=10/2=5 m/s².","math":{"title":"Hukum II Newton dan resultan gaya","foundation":"Hukum II Newton menyatakan ΣF = m a. Gaya berlawanan arah diberi tanda berlawanan sehingga ΣF = F dorong − F gesek; akibatnya a = ΣF/m.","steps":["Pilih arah dorong/tarik sebagai arah positif.","Dari Hukum II Newton: ΣF = ma, sehingga a = ΣF/m.","Gaya bersih ΣF = 14 − 4 = 10 N.","a = 10/2 = 5 m/s²."],"symbol":"newton"},"deepConcept":"Gaya adalah besaran vektor; resultan harus mempertimbangkan arah. Benda bermassa m mengalami percepatan a menurut ΣF = ma. Gaya gesek yang melawan gerak dikurangkan dari gaya dorong.","conceptName":"gaya","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Jika percepatan 7 m/s², gaya bersih yang dibutuhkan m×a = 2×7 = 14 N, padahal soal menetapkan gaya bersih 10 N.","C":"Jika percepatan 9 m/s², gaya bersih yang dibutuhkan m×a = 2×9 = 18 N, padahal soal menetapkan gaya bersih 10 N.","D":"Jika percepatan 2 m/s², gaya bersih yang dibutuhkan m×a = 2×2 = 4 N, padahal soal menetapkan gaya bersih 10 N."}},{"id":"p5q42","package":5,"number":42,"question":"Pada tegangan 24 V, sebuah hambatan dilalui arus 3 A. Besar hambatan adalah ...","options":{"A":"8 Ω","B":"72 Ω","C":"3 Ω","D":"21 Ω"},"answer":"A","answerText":"8 Ω","modul":8,"moduleName":"Listrik dan Magnet","difficulty":"Sedang","explain":"R=V/I=24/3=8 Ω.","math":{"title":"Hukum Ohm","foundation":"Untuk resistor ohmik pada kondisi tetap, tegangan V sebanding dengan arus I: V = I R. Dengan membagi kedua ruas, I = V/R atau R = V/I sesuai besaran yang ditanyakan.","steps":["Mulai dari Hukum Ohm: V = I × R.","Bagi kedua ruas dengan I → R = V/I.","R = 24/3 = 8 Ω."],"symbol":"ohm"},"deepConcept":"Rangkaian seri memiliki arus yang sama dan tegangan terbagi, sehingga R total dijumlahkan. Rangkaian paralel memiliki tegangan yang sama dan arus terbagi, sehingga kebalikan hambatan dijumlahkan.","conceptName":"rangkaian","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"B":"Hambatan 72 Ω dengan arus 3 A memerlukan V = IR = 216 V, bukan 24 V.","C":"Hambatan 3 Ω dengan arus 3 A memerlukan V = IR = 9 V, bukan 24 V.","D":"Hambatan 21 Ω dengan arus 3 A memerlukan V = IR = 63 V, bukan 24 V."}},{"id":"p5q43","package":5,"number":43,"question":"Benda 0,5 kg bergerak 4 m/s. Energi kinetiknya sebesar ...","options":{"A":"1 J","B":"2 J","C":"4 J","D":"8 J"},"answer":"C","answerText":"4 J","modul":11,"moduleName":"Bentuk Energi dan Perubahannya","difficulty":"Sulit","explain":"Ek=½×0,5×4²=4 J.","math":{"title":"Asal rumus energi kinetik","foundation":"Usaha W = Fs = mas. Untuk benda mulai dari diam dengan percepatan tetap, v² = 2as, maka as = v²/2. Jadi W = m(v²/2) = ½mv², yaitu energi kinetik akhir.","steps":["Usaha untuk mempercepat benda dari diam menjadi energi kinetiknya: W = ½ m v².","Kuadratkan kecepatan terlebih dahulu: v² = 4² = 16 (m/s)².","Eₖ = ½ × 0,5 × 16 = 4 J.","Perhatikan: energi kinetik berbanding lurus dengan kuadrat kecepatan."],"symbol":"kinetic"},"deepConcept":"Energi kinetik bergantung pada massa dan kuadrat kelajuan: Eₖ = ½mv². Jika kecepatan menjadi dua kali, energi kinetik menjadi empat kali.","conceptName":"mekanik","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Dengan energi 1 J dan massa 0,5 kg, kelajuan seharusnya v = √(2E/m) ≈ 2 m/s, bukan 4 m/s.","B":"Dengan energi 2 J dan massa 0,5 kg, kelajuan seharusnya v = √(2E/m) ≈ 2,82843 m/s, bukan 4 m/s.","D":"Dengan energi 8 J dan massa 0,5 kg, kelajuan seharusnya v = √(2E/m) ≈ 5,65685 m/s, bukan 4 m/s."}},{"id":"p5q44","package":5,"number":44,"question":"Daerah bayangan inti pada peristiwa gerhana disebut ...","options":{"A":"magnetosfer","B":"penumbra","C":"troposfer","D":"umbra"},"answer":"D","answerText":"umbra","modul":12,"moduleName":"Bumi, Tata Surya, dan Antariksa","difficulty":"Sedang","explain":"Umbra adalah daerah bayangan paling gelap.","deepConcept":"Gerhana Matahari terjadi ketika Bulan berada di antara Matahari–Bumi; gerhana Bulan ketika Bumi berada di antara Matahari–Bulan. Umbra merupakan bagian bayangan paling gelap.","conceptName":"gerhana","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q45","package":5,"number":45,"question":"Kutikula berlilin pada permukaan daun membantu tumbuhan ...","options":{"A":"mengangkut gula ke batang","B":"menambah laju kehilangan air tanpa batas","C":"mengurangi kehilangan air melalui penguapan","D":"menghasilkan biji secara langsung"},"answer":"C","answerText":"mengurangi kehilangan air melalui penguapan","modul":4,"moduleName":"Fisiologi Tumbuhan","difficulty":"Mudah","explain":"Lapisan kutikula mengurangi transpirasi epidermis.","deepConcept":"Tumbuhan mengendalikan neraca air melalui akar, stomata, dan kutikula. Luas daun yang kecil serta kutikula tebal mengurangi kehilangan air; penutupan stomata juga dapat mengurangi masuknya CO₂.","conceptName":"air","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q46","package":5,"number":46,"question":"Pembangkit menghasilkan listrik 300 J dari energi masukan 1.200 J. Efisiensinya ...","options":{"A":"40%","B":"25%","C":"75%","D":"15%"},"answer":"B","answerText":"25%","modul":11,"moduleName":"Bentuk Energi dan Perubahannya","difficulty":"Sedang","explain":"η=300/1.200×100%=25%.","math":{"title":"Efisiensi dari konservasi energi","foundation":"Energi masuk tidak seluruhnya berubah menjadi keluaran yang diinginkan. Secara definisi, efisiensi η = (E berguna/E masuk)×100%. Pada alat biasa, sisanya terbuang sebagai kalor, suara, dll.","steps":["Efisiensi adalah proporsi energi masuk yang benar-benar menjadi energi berguna.","Dari definisi bagian = keluaran/masukan, sehingga η = E berguna/E masuk × 100%.","η = (300/1.200) × 100% = 25%.","Energi yang tidak menjadi keluaran berguna = 900 J (misalnya terdisipasi sebagai kalor)."],"symbol":"efficiency"},"deepConcept":"Energi tidak diciptakan dari ketiadaan. Efisiensi adalah persentase energi masuk yang menjadi keluaran berguna; tidak mengukur energi yang “hilang”, tetapi energi yang berpindah ke bentuk tak diinginkan.","conceptName":"energi","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Efisiensi 40% menyatakan energi berguna 480 J dari masukan 1.200 J, padahal keluaran soal 300 J.","C":"Efisiensi 75% menyatakan energi berguna 900 J dari masukan 1.200 J, padahal keluaran soal 300 J.","D":"Efisiensi 15% menyatakan energi berguna 180 J dari masukan 1.200 J, padahal keluaran soal 300 J."}},{"id":"p5q47","package":5,"number":47,"question":"Pada fase S siklus sel, proses terpenting adalah ...","options":{"A":"pembentukan gamet tanpa DNA","B":"pemisahan sitoplasma","C":"replikasi DNA","D":"penghilangan semua kromosom"},"answer":"C","answerText":"replikasi DNA","modul":5,"moduleName":"Sistem Organ, Sel, dan Genetika","difficulty":"Sedang","explain":"Materi genetik digandakan pada fase S.","deepConcept":"Mitosis menghasilkan sel anak dengan jumlah kromosom umumnya sama, sedangkan meiosis mengurangi jumlah kromosom menjadi separuh. Sebelum pembelahan, DNA direplikasi pada fase S; kromosom sejajar pada metafase dan kromatid saudara berpisah pada anafase mitosis.","conceptName":"pembelahan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q48","package":5,"number":48,"question":"Kereta bergerak 90 km selama 1,5 jam. Kelajuan rata-ratanya adalah ...","options":{"A":"90 km/jam","B":"135 km/jam","C":"60 km/jam","D":"45 km/jam"},"answer":"C","answerText":"60 km/jam","modul":6,"moduleName":"Mekanika","difficulty":"Sedang","explain":"90/1,5 = 60 km/jam.","math":{"title":"Kelajuan dari definisi gerak","foundation":"Kelajuan rata-rata didefinisikan sebagai total jarak dibagi total waktu: v = s/t. Jika jarak dan waktu memakai satuan yang tidak cocok, konversikan terlebih dahulu.","steps":["Besaran diketahui: jarak s = 90 km; waktu t = 1,5 jam.","Definisi kelajuan rata-rata: v = s/t.","Satuan jarak dan waktu sudah sepadan.","v = 90/1,5 = 60 km/jam."],"symbol":"speed"},"deepConcept":"Kelajuan rata-rata memakai jarak tempuh total dibagi durasi total. Untuk memperoleh m/s, pakai meter dan detik; 1 km = 1.000 m dan 1 menit = 60 detik.","conceptName":"kelajuan","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Nilai 90 km/jam tidak sama dengan s/t = 90/1,5 = 60 km/jam untuk data pada soal.","B":"Nilai 135 km/jam tidak sama dengan s/t = 90/1,5 = 60 km/jam untuk data pada soal.","D":"Nilai 45 km/jam tidak sama dengan s/t = 90/1,5 = 60 km/jam untuk data pada soal."}},{"id":"p5q49","package":5,"number":49,"question":"Pelangi tampak setelah hujan terutama karena cahaya Matahari mengalami ...","options":{"A":"gelombang bunyi yang menembus awan","B":"pembiasan, dispersi, dan pemantulan internal di tetes air","C":"hanya konduksi kalor","D":"interaksi medan magnet bumi saja"},"answer":"B","answerText":"pembiasan, dispersi, dan pemantulan internal di tetes air","modul":9,"moduleName":"Gelombang dan Optik","difficulty":"Sulit","explain":"Tetes air memisah warna cahaya melalui proses optik.","deepConcept":"Pembiasan terjadi karena kecepatan rambat cahaya berubah ketika indeks bias medium berbeda. Dari medium indeks rendah ke tinggi, sinar mendekati normal; dari tinggi ke rendah, sinar menjauhi normal.","conceptName":"bias","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Cari kata kunci pada fenomena atau struktur yang disebut, lalu bedakan fungsi dan mekanismenya dari tiga pilihan lain."},{"id":"p5q50","package":5,"number":50,"question":"Resistor 2 Ω dan 6 Ω disusun paralel. Hambatan penggantinya ...","options":{"A":"2 Ω","B":"8 Ω","C":"1,5 Ω","D":"4 Ω"},"answer":"C","answerText":"1,5 Ω","modul":8,"moduleName":"Listrik dan Magnet","difficulty":"Sulit","explain":"R=(2×6)/(2+6)=1,5 Ω.","math":{"title":"Mengapa rumus paralel berupa kebalikan?","foundation":"Tegangan V sama pada setiap cabang paralel; arus total adalah penjumlahan arus cabang: I = V/R₁+V/R₂. Karena I=V/R total, pembagian dengan V menghasilkan 1/R total = 1/R₁+1/R₂.","steps":["Tegangan pada setiap cabang paralel sama, sedangkan arus total adalah jumlah arus cabang.","Karena I total = Σ(V/Rᵢ) = V/R total, maka 1/R total = Σ(1/Rᵢ).","Untuk dua resistor, R total = (R₁ × R₂)/(R₁ + R₂) = (2 × 6)/(2 + 6) = 1,5 Ω."],"symbol":"parallel"},"deepConcept":"Rangkaian seri memiliki arus yang sama dan tegangan terbagi, sehingga R total dijumlahkan. Rangkaian paralel memiliki tegangan yang sama dan arus terbagi, sehingga kebalikan hambatan dijumlahkan.","conceptName":"rangkaian","misconception":"Jangan memilih pilihan hanya karena mengandung istilah yang terdengar ilmiah. Pilihan harus cocok dengan kondisi, arah proses, besaran, serta mekanisme yang ditanyakan.","hint":"Identifikasi besaran atau proses yang diketahui, lalu tentukan prinsip yang menghubungkannya dengan hal yang ditanyakan. Periksa satuan dan kata kunci pada soal.","wrongChecks":{"A":"Hambatan 2 Ω berbeda dari (R₁R₂)/(R₁+R₂) = 1,5 Ω; hambatan paralel juga harus lebih kecil daripada setiap cabang.","B":"Hambatan 8 Ω berbeda dari (R₁R₂)/(R₁+R₂) = 1,5 Ω; hambatan paralel juga harus lebih kecil daripada setiap cabang.","D":"Hambatan 4 Ω berbeda dari (R₁R₂)/(R₁+R₂) = 1,5 Ω; hambatan paralel juga harus lebih kecil daripada setiap cabang."}}];
window.KLUB_MODULES={"1": "Keterampilan dan Metode Ilmiah", "2": "Keanekaragaman dan Klasifikasi", "3": "Fisiologi Hewan", "4": "Fisiologi Tumbuhan", "5": "Sistem Organ, Sel, dan Genetika", "6": "Mekanika", "7": "Wujud Benda dan Fluida", "8": "Listrik dan Magnet", "9": "Gelombang dan Optik", "10": "Suhu dan Kalor", "11": "Bentuk Energi dan Perubahannya", "12": "Bumi, Tata Surya, dan Antariksa", "13": "Ekologi dan Pelestarian Lingkungan", "14": "Kesehatan, Lingkungan, dan Teknologi"};
window.KLUB_OVERVIEW={"1": "Belajar bertanya secara ilmiah, merancang eksperimen adil, membedakan variabel, memeriksa data, dan menarik kesimpulan yang tidak melampaui bukti.", "2": "Klasifikasikan makhluk hidup memakai ciri yang dapat diamati, hubungan genetik, tingkatan takson, dan tiga tingkat keanekaragaman.", "3": "Hubungkan struktur dengan fungsi: pencernaan, pernapasan, peredaran darah, ekskresi, respons saraf, dan pengaturan suhu tubuh.", "4": "Telusuri jalur transport tumbuhan, fotosintesis, regulasi stomata, hormon pertumbuhan, serta gerak tropisme dan nasti.", "5": "Pahami sel dan organel, pembelahan sel, materi genetik, aturan segregasi Mendel, serta cara membaca tabel peluang keturunan.", "6": "Gunakan besaran, arah gaya, usaha, keseimbangan momen, dan hukum Newton untuk menalar gerak dan pesawat sederhana.", "7": "Turunkan tekanan dari gaya per luas, hubungkan kedalaman dengan tekanan fluida, pahami Pascal, massa jenis, dan perubahan wujud.", "8": "Gunakan kekekalan arus dan tegangan bersama Hukum Ohm, serta hubungkan arus listrik dengan pembentukan medan magnet.", "9": "Mulailah dari definisi getaran, lalu turunkan hubungan frekuensi–periode–gelombang. Bedakan pemantulan, pembiasan, dan pembentukan bayangan.", "10": "Bedakan suhu dan kalor; turunkan Q = mcΔT dari definisi kalor jenis, lalu periksa konduksi, konveksi, radiasi, dan pemuaian.", "11": "Amati perubahan bentuk energi dan konservasinya, kemudian turunkan energi mekanik dan efisiensi alat dari kerja serta energi.", "12": "Bedakan rotasi dan revolusi, fase Bulan dan gerhana, lalu kaitkan proses Bumi dengan atmosfer, lempeng, gempa, dan geotermal.", "13": "Pelajari tingkat trofik, jaring makanan, interaksi antarpopulasi, aliran materi, dampak spesies invasif, dan strategi konservasi.", "14": "Terapkan prinsip kesehatan masyarakat, bioteknologi, rekayasa genetika, sensor, pemantauan lingkungan, dan pengolahan polutan."};
